INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 19, E'Every man also to whom God hath given riches and wealth, and hath given him power to eat thereof, and to take his portion, and to rejoice in his labour; this is the gift of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 20, E'For he shall not much remember the days of his life; because God answereth him in the joy of his heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 6, 1, E'There is an evil which I have seen under the sun, and it is common among men:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 6, 2, E'A man to whom God hath given riches, wealth, and honour, so that he wanteth nothing for his soul of all that he desireth, yet God giveth him not power to eat thereof, but a stranger eateth it: this is vanity, and it is an evil disease.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 6, 3, E'If a man beget an hundred children, and live many years, so that the days of his years be many, and his soul be not filled with good, and also that he have no burial; I say, that an untimely birth is better than he.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 6, 4, E'For he cometh in with vanity, and departeth in darkness, and his name shall be covered with darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 6, 5, E'Moreover he hath not seen the sun, nor known any thing: this hath more rest than the other.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 6, 6, E'Yea, though he live a thousand years twice told, yet hath he seen no good: do not all go to one place?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 6, 7, E'All the labour of man is for his mouth, and yet the appetite is not filled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 6, 8, E'For what hath the wise more than the fool? what hath the poor, that knoweth to walk before the living?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 6, 9, E'Better is the sight of the eyes than the wandering of the desire: this is also vanity and vexation of spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 6, 10, E'That which hath been is named already, and it is known that it is man: neither may he contend with him that is mightier than he.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 6, 11, E'Seeing there be many things that increase vanity, what is man the better?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 6, 12, E'For who knoweth what is good for man in this life, all the days of his vain life which he spendeth as a shadow? for who can tell a man what shall be after him under the sun?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 1, E'A good name is better than precious ointment; and the day of death than the day of oneâ€™s birth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 2, E'It is better to go to the house of mourning, than to go to the house of feasting: for that is the end of all men; and the living will lay it to his heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 3, E'Sorrow is better than laughter: for by the sadness of the countenance the heart is made better.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 4, E'The heart of the wise is in the house of mourning; but the heart of fools is in the house of mirth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 5, E'It is better to hear the rebuke of the wise, than for a man to hear the song of fools.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 6, E'For as the crackling of thorns under a pot, so is the laughter of the fool: this also is vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 7, E'Surely oppression maketh a wise man mad; and a gift destroyeth the heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 8, E'Better is the end of a thing than the beginning thereof: and the patient in spirit is better than the proud in spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 9, E'Be not hasty in thy spirit to be angry: for anger resteth in the bosom of fools.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 10, E'Say not thou, What is the cause that the former days were better than these? for thou dost not enquire wisely concerning this.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 11, E'Wisdom is good with an inheritance: and by it there is profit to them that see the sun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 12, E'For wisdom is a defence, and money is a defence: but the excellency of knowledge is, that wisdom giveth life to them that have it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 13, E'Consider the work of God: for who can make that straight, which he hath made crooked?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 14, E'In the day of prosperity be joyful, but in the day of adversity consider: God also hath set the one over against the other, to the end that man should find nothing after him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 15, E'All things have I seen in the days of my vanity: there is a just man that perisheth in his righteousness, and there is a wicked man that prolongeth his life in his wickedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 16, E'Be not righteous over much; neither make thyself over wise: why shouldest thou destroy thyself ?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 17, E'Be not over much wicked, neither be thou foolish: why shouldest thou die before thy time?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 18, E'It is good that thou shouldest take hold of this; yea, also from this withdraw not thine hand: for he that feareth God shall come forth of them all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 19, E'Wisdom strengtheneth the wise more than ten mighty men which are in the city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 20, E'For there is not a just man upon earth, that doeth good, and sinneth not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 21, E'Also take no heed unto all words that are spoken; lest thou hear thy servant curse thee:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 22, E'For oftentimes also thine own heart knoweth that thou thyself likewise hast cursed others.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 23, E'All this have I proved by wisdom: I said, I will be wise; but it was far from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 24, E'That which is far off, and exceeding deep, who can find it out?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 25, E'I applied mine heart to know, and to search, and to seek out wisdom, and the reason of things, and to know the wickedness of folly, even of foolishness and madness:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 26, E'And I find more bitter than death the woman, whose heart is snares and nets, and her hands as bands: whoso pleaseth God shall escape from her; but the sinner shall be taken by her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 27, E'Behold, this have I found, saith the preacher, counting one by one, to find out the account:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 28, E'Which yet my soul seeketh, but I find not: one man among a thousand have I found; but a woman among all those have I not found.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 7, 29, E'Lo, this only have I found, that God hath made man upright; but they have sought out many inventions.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 1, E'Who is as the wise man? and who knoweth the interpretation of a thing? a manâ€™s wisdom maketh his face to shine, and the boldness of his face shall be changed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 2, E'I counsel thee to keep the kingâ€™s commandment, and that in regard of the oath of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 3, E'Be not hasty to go out of his sight: stand not in an evil thing; for he doeth whatsoever pleaseth him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 4, E'Where the word of a king is, there is power: and who may say unto him, What doest thou?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 5, E'Whoso keepeth the commandment shall feel no evil thing: and a wise manâ€™s heart discerneth both time and judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 6, E'Because to every purpose there is time and judgment, therefore the misery of man is great upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 7, E'For he knoweth not that which shall be: for who can tell him when it shall be?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 8, E'There is no man that hath power over the spirit to retain the spirit; neither hath he power in the day of death: and there is no discharge in that war; neither shall wickedness deliver those that are given to it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 9, E'All this have I seen, and applied my heart unto every work that is done under the sun: there is a time wherein one man ruleth over another to his own hurt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 10, E'And so I saw the wicked buried, who had come and gone from the place of the holy, and they were forgotten in the city where they had so done: this is also vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 11, E'Because sentence against an evil work is not executed speedily, therefore the heart of the sons of men is fully set in them to do evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 12, E'Though a sinner do evil an hundred times, and his days be prolonged, yet surely I know that it shall be well with them that fear God, which fear before him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 13, E'But it shall not be well with the wicked, neither shall he prolong his days, which are as a shadow; because he feareth not before God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 14, E'There is a vanity which is done upon the earth; that there be just men, unto whom it happeneth according to the work of the wicked; again, there be wicked men, to whom it happeneth according to the work of the righteous: I said that this also is vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 15, E'Then I commended mirth, because a man hath no better thing under the sun, than to eat, and to drink, and to be merry: for that shall abide with him of his labour the days of his life, which God giveth him under the sun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 16, E'When I applied mine heart to know wisdom, and to see the business that is done upon the earth: (for also there is that neither day nor night seeth sleep with his eyes:)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 8, 17, E'Then I beheld all the work of God, that a man cannot find out the work that is done under the sun: because though a man labour to seek it out, yet he shall not find it; yea farther; though a wise man think to know it, yet shall he not be able to find it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 1, E'For all this I considered in my heart even to declare all this, that the righteous, and the wise, and their works, are in the hand of God: no man knoweth either love or hatred by all that is before them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 2, E'All things come alike to all: there is one event to the righteous, and to the wicked; to the good and to the clean, and to the unclean; to him that sacrificeth, and to him that sacrificeth not: as is the good, so is the sinner; and he that sweareth, as he that feareth an oath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 3, E'This is an evil among all things that are done under the sun, that there is one event unto all: yea, also the heart of the sons of men is full of evil, and madness is in their heart while they live, and after that they go to the dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 4, E'For to him that is joined to all the living there is hope: for a living dog is better than a dead lion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 5, E'For the living know that they shall die: but the dead know not any thing, neither have they any more a reward; for the memory of them is forgotten.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 6, E'Also their love, and their hatred, and their envy, is now perished; neither have they any more a portion for ever in any thing that is done under the sun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 7, E'Go thy way, eat thy bread with joy, and drink thy wine with a merry heart; for God now accepteth thy works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 8, E'Let thy garments be always white; and let thy head lack no ointment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 9, E'Live joyfully with the wife whom thou lovest all the days of the life of thy vanity, which he hath given thee under the sun, all the days of thy vanity: for that is thy portion in this life, and in thy labour which thou takest under the sun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 10, E'Whatsoever thy hand findeth to do, do it with thy might; for there is no work, nor device, nor knowledge, nor wisdom, in the grave, whither thou goest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 11, E'I returned, and saw under the sun, that the race is not to the swift, nor the battle to the strong, neither yet bread to the wise, nor yet riches to men of understanding, nor yet favour to men of skill; but time and chance happeneth to them all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 12, E'For man also knoweth not his time: as the fishes that are taken in an evil net, and as the birds that are caught in the snare; so are the sons of men snared in an evil time, when it falleth suddenly upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 13, E'This wisdom have I seen also under the sun, and it seemed great unto me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 14, E'There was a little city, and few men within it; and there came a great king against it, and besieged it, and built great bulwarks against it:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 15, E'Now there was found in it a poor wise man, and he by his wisdom delivered the city; yet no man remembered that same poor man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 16, E'Then said I, Wisdom is better than strength: nevertheless the poor manâ€™s wisdom is despised, and his words are not heard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 17, E'The words of wise men are heard in quiet more than the cry of him that ruleth among fools.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 9, 18, E'Wisdom is better than weapons of war: but one sinner destroyeth much good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 1, E'Dead flies cause the ointment of the apothecary to send forth a stinking savour: so doth a little folly him that is in reputation for wisdom and honour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 2, E'A wise manâ€™s heart is at his right hand; but a foolâ€™s heart at his left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 3, E'Yea also, when he that is a fool walketh by the way, his wisdom faileth him, and he saith to every one that he is a fool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 4, E'If the spirit of the ruler rise up against thee, leave not thy place; for yielding pacifieth great offences.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 5, E'There is an evil which I have seen under the sun, as an error which proceedeth from the ruler:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 6, E'Folly is set in great dignity, and the rich sit in low place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 7, E'I have seen servants upon horses, and princes walking as servants upon the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 8, E'He that diggeth a pit shall fall into it; and whoso breaketh an hedge, a serpent shall bite him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 9, E'Whoso removeth stones shall be hurt therewith; and he that cleaveth wood shall be endangered thereby.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 10, E'If the iron be blunt, and he do not whet the edge, then must he put to more strength: but wisdom is profitable to direct.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 11, E'Surely the serpent will bite without enchantment; and a babbler is no better.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 12, E'The words of a wise manâ€™s mouth are gracious; but the lips of a fool will swallow up himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 13, E'The beginning of the words of his mouth is foolishness: and the end of his talk is mischievous madness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 14, E'A fool also is full of words: a man cannot tell what shall be; and what shall be after him, who can tell him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 15, E'The labour of the foolish wearieth every one of them, because he knoweth not how to go to the city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 16, E'Woe to thee, O land, when thy king is a child, and thy princes eat in the morning!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 17, E'Blessed art thou, O land, when thy king is the son of nobles, and thy princes eat in due season, for strength, and not for drunkenness!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 18, E'By much slothfulness the building decayeth; and through idleness of the hands the house droppeth through.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 19, E'A feast is made for laughter, and wine maketh merry: but money answereth all things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 10, 20, E'Curse not the king, no not in thy thought; and curse not the rich in thy bedchamber: for a bird of the air shall carry the voice, and that which hath wings shall tell the matter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 11, 1, E'Cast thy bread upon the waters: for thou shalt find it after many days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 11, 2, E'Give a portion to seven, and also to eight; for thou knowest not what evil shall be upon the earth.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Ecclesiastes') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 11, 3, E'If the clouds be full of rain, they empty themselves upon the earth: and if the tree fall toward the south, or toward the north, in the place where the tree falleth, there it shall be.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 11, 4, E'He that observeth the wind shall not sow; and he that regardeth the clouds shall not reap.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 11, 5, E'As thou knowest not what is the way of the spirit, nor how the bones do grow in the womb of her that is with child: even so thou knowest not the works of God who maketh all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 11, 6, E'In the morning sow thy seed, and in the evening withhold not thine hand: for thou knowest not whether shall prosper, either this or that, or whether they both shall be alike good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 11, 7, E'Truly the light is sweet, and a pleasant thing it is for the eyes to behold the sun:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 11, 8, E'But if a man live many years, and rejoice in them all; yet let him remember the days of darkness; for they shall be many. All that cometh is vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 11, 9, E'Rejoice, O young man, in thy youth; and let thy heart cheer thee in the days of thy youth, and walk in the ways of thine heart, and in the sight of thine eyes: but know thou, that for all these things God will bring thee into judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 11, 10, E'Therefore remove sorrow from thy heart, and put away evil from thy flesh: for childhood and youth are vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 1, E'Remember now thy Creator in the days of thy youth, while the evil days come not, nor the years draw nigh, when thou shalt say, I have no pleasure in them;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 2, E'While the sun, or the light, or the moon, or the stars, be not darkened, nor the clouds return after the rain:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 3, E'In the day when the keepers of the house shall tremble, and the strong men shall bow themselves, and the grinders cease because they are few, and those that look out of the windows be darkened,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 4, E'And the doors shall be shut in the streets, when the sound of the grinding is low, and he shall rise up at the voice of the bird, and all the daughters of musick shall be brought low;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 5, E'Also when they shall be afraid of that which is high, and fears shall be in the way, and the almond tree shall flourish, and the grasshopper shall be a burden, and desire shall fail: because man goeth to his long home, and the mourners go about the streets:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 6, E'Or ever the silver cord be loosed, or the golden bowl be broken, or the pitcher be broken at the fountain, or the wheel broken at the cistern.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 7, E'Then shall the dust return to the earth as it was: and the spirit shall return unto God who gave it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 8, E'Vanity of vanities, saith the preacher; all is vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 9, E'And moreover, because the preacher was wise, he still taught the people knowledge; yea, he gave good heed, and sought out, and set in order many proverbs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 10, E'The preacher sought to find out acceptable words: and that which was written was upright, even words of truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 11, E'The words of the wise are as goads, and as nails fastened by the masters of assemblies, which are given from one shepherd.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 12, E'And further, by these, my son, be admonished: of making many books there is no end; and much study is a weariness of the flesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 13, E'Let us hear the conclusion of the whole matter: Fear God, and keep his commandments: for this is the whole duty of man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 12, 14, E'For God shall bring every work into judgment, with every secret thing, whether it be good, or whether it be evil.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Ecclesiastes') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 1, E'The song of songs, which is Solomonâ€™s.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 2, E'Let him kiss me with the kisses of his mouth: for thy love is better than wine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 3, E'Because of the savour of thy good ointments thy name is as ointment poured forth, therefore do the virgins love thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 4, E'Draw me, we will run after thee: the king hath brought me into his chambers: we will be glad and rejoice in thee, we will remember thy love more than wine: the upright love thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 5, E'I am black, but comely, O ye daughters of Jerusalem, as the tents of Kedar, as the curtains of Solomon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 6, E'Look not upon me, because I am black, because the sun hath looked upon me: my motherâ€™s children were angry with me; they made me the keeper of the vineyards; but mine own vineyard have I not kept.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 7, E'Tell me, O thou whom my soul loveth, where thou feedest, where thou makest thy flock to rest at noon: for why should I be as one that turneth aside by the flocks of thy companions?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 8, E'If thou know not, O thou fairest among women, go thy way forth by the footsteps of the flock, and feed thy kids beside the shepherdsâ€™ tents.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 9, E'I have compared thee, O my love, to a company of horses in Pharaohâ€™s chariots.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 10, E'Thy cheeks are comely with rows of jewels, thy neck with chains of gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 11, E'We will make thee borders of gold with studs of silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 12, E'While the king sitteth at his table, my spikenard sendeth forth the smell thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 13, E'A bundle of myrrh is my well-beloved unto me; he shall lie all night betwixt my breasts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 14, E'My beloved is unto me as a cluster of camphire in the vineyards of Engedi.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 15, E'Behold, thou art fair, my love; behold, thou art fair; thou hast dovesâ€™ eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 16, E'Behold, thou art fair, my beloved, yea, pleasant: also our bed is green.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 1, 17, E'The beams of our house are cedar, and our rafters of fir.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 1, E'I am the rose of Sharon, and the lily of the valleys.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 2, E'As the lily among thorns, so is my love among the daughters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 3, E'As the apple tree among the trees of the wood, so is my beloved among the sons. I sat down under his shadow with great delight, and his fruit was sweet to my taste.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 4, E'He brought me to the banqueting house, and his banner over me was love.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 5, E'Stay me with flagons, comfort me with apples: for I am sick of love.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 6, E'His left hand is under my head, and his right hand doth embrace me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 7, E'I charge you, O ye daughters of Jerusalem, by the roes, and by the hinds of the field, that ye stir not up, nor awake my love, till he please.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 8, E'The voice of my beloved! behold, he cometh leaping upon the mountains, skipping upon the hills.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 9, E'My beloved is like a roe or a young hart: behold, he standeth behind our wall, he looketh forth at the windows, shewing himself through the lattice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 10, E'My beloved spake, and said unto me, Rise up, my love, my fair one, and come away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 11, E'For, lo, the winter is past, the rain is over and gone;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 12, E'The flowers appear on the earth; the time of the singing of birds is come, and the voice of the turtle is heard in our land;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 13, E'The fig tree putteth forth her green figs, and the vines with the tender grape give a good smell. Arise, my love, my fair one, and come away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 14, E'O my dove, that art in the clefts of the rock, in the secret places of the stairs, let me see thy countenance, let me hear thy voice; for sweet is thy voice, and thy countenance is comely.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 15, E'Take us the foxes, the little foxes, that spoil the vines: for our vines have tender grapes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 16, E'My beloved is mine, and I am his: he feedeth among the lilies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 2, 17, E'Until the day break, and the shadows flee away, turn, my beloved, and be thou like a roe or a young hart upon the mountains of Bether.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 3, 1, E'By night on my bed I sought him whom my soul loveth: I sought him, but I found him not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 3, 2, E'I will rise now, and go about the city in the streets, and in the broad ways I will seek him whom my soul loveth: I sought him, but I found him not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 3, 3, E'The watchmen that go about the city found me: to whom I said, Saw ye him whom my soul loveth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 3, 4, E'It was but a little that I passed from them, but I found him whom my soul loveth: I held him, and would not let him go, until I had brought him into my motherâ€™s house, and into the chamber of her that conceived me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 3, 5, E'I charge you, O ye daughters of Jerusalem, by the roes, and by the hinds of the field, that ye stir not up, nor awake my love, till he please.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 3, 6, E'Who is this that cometh out of the wilderness like pillars of smoke, perfumed with myrrh and frankincense, with all powders of the merchant?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 3, 7, E'Behold his bed, which is Solomonâ€™s; threescore valiant men are about it, of the valiant of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 3, 8, E'They all hold swords, being expert in war: every man hath his sword upon his thigh because of fear in the night.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 3, 9, E'King Solomon made himself a chariot of the wood of Lebanon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 3, 10, E'He made the pillars thereof of silver, the bottom thereof of gold, the covering of it of purple, the midst thereof being paved with love, for the daughters of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 3, 11, E'Go forth, O ye daughters of Zion, and behold king Solomon with the crown wherewith his mother crowned him in the day of his espousals, and in the day of the gladness of his heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 1, E'Behold, thou art fair, my love; behold, thou art fair; thou hast dovesâ€™ eyes within thy locks: thy hair is as a flock of goats, that appear from mount Gilead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 2, E'Thy teeth are like a flock of sheep that are even shorn, which came up from the washing; whereof every one bear twins, and none is barren among them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 3, E'Thy lips are like a thread of scarlet, and thy speech is comely: thy temples are like a piece of a pomegranate within thy locks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 4, E'Thy neck is like the tower of David builded for an armoury, whereon there hang a thousand bucklers, all shields of mighty men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 5, E'Thy two breasts are like two young roes that are twins, which feed among the lilies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 6, E'Until the day break, and the shadows flee away, I will get me to the mountain of myrrh, and to the hill of frankincense.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 7, E'Thou art all fair, my love; there is no spot in thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 8, E'Come with me from Lebanon, my spouse, with me from Lebanon: look from the top of Amana, from the top of Shenir and Hermon, from the lionsâ€™ dens, from the mountains of the leopards.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 9, E'Thou hast ravished my heart, my sister, my spouse; thou hast ravished my heart with one of thine eyes, with one chain of thy neck.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 10, E'How fair is thy love, my sister, my spouse! how much better is thy love than wine! and the smell of thine ointments than all spices!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 11, E'Thy lips, O my spouse, drop as the honeycomb: honey and milk are under thy tongue; and the smell of thy garments is like the smell of Lebanon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 12, E'A garden inclosed is my sister, my spouse; a spring shut up, a fountain sealed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 13, E'Thy plants are an orchard of pomegranates, with pleasant fruits; camphire, with spikenard,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 14, E'Spikenard and saffron; calamus and cinnamon, with all trees of frankincense; myrrh and aloes, with all the chief spices:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 15, E'A fountain of gardens, a well of living waters, and streams from Lebanon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 4, 16, E'Awake, O north wind; and come, thou south; blow upon my garden, that the spices thereof may flow out. Let my beloved come into his garden, and eat his pleasant fruits.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 1, E'I am come into my garden, my sister, my spouse: I have gathered my myrrh with my spice; I have eaten my honeycomb with my honey; I have drunk my wine with my milk: eat, O friends; drink, yea, drink abundantly, O beloved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 2, E'I sleep, but my heart waketh: it is the voice of my beloved that knocketh, saying, Open to me, my sister, my love, my dove, my undefiled: for my head is filled with dew, and my locks with the drops of the night.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 3, E'I have put off my coat; how shall I put it on? I have washed my feet; how shall I defile them?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 4, E'My beloved put in his hand by the hole of the door, and my bowels were moved for him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 5, E'I rose up to open to my beloved; and my hands dropped with myrrh, and my fingers with sweet smelling myrrh, upon the handles of the lock.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 6, E'I opened to my beloved; but my beloved had withdrawn himself, and was gone: my soul failed when he spake: I sought him, but I could not find him; I called him, but he gave me no answer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 7, E'The watchmen that went about the city found me, they smote me, they wounded me; the keepers of the walls took away my veil from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 8, E'I charge you, O daughters of Jerusalem, if ye find my beloved, that ye tell him, that I am sick of love.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 9, E'What is thy beloved more than another beloved, O thou fairest among women? what is thy beloved more than another beloved, that thou dost so charge us?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 10, E'My beloved is white and ruddy, the chiefest among ten thousand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 11, E'His head is as the most fine gold, his locks are bushy, and black as a raven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 12, E'His eyes are as the eyes of doves by the rivers of waters, washed with milk, and fitly set.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 13, E'His cheeks are as a bed of spices, as sweet flowers: his lips like lilies, dropping sweet smelling myrrh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 14, E'His hands are as gold rings set with the beryl: his belly is as bright ivory overlaid with sapphires.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 15, E'His legs are as pillars of marble, set upon sockets of fine gold: his countenance is as Lebanon, excellent as the cedars.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 5, 16, E'His mouth is most sweet: yea, he is altogether lovely. This is my beloved, and this is my friend, O daughters of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 1, E'Whither is thy beloved gone, O thou fairest among women? whither is thy beloved turned aside? that we may seek him with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 2, E'My beloved is gone down into his garden, to the beds of spices, to feed in the gardens, and to gather lilies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 3, E'I am my belovedâ€™s, and my beloved is mine: he feedeth among the lilies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 4, E'Thou art beautiful, O my love, as Tirzah, comely as Jerusalem, terrible as an army with banners.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 5, E'Turn away thine eyes from me, for they have overcome me: thy hair is as a flock of goats that appear from Gilead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 6, E'Thy teeth are as a flock of sheep which go up from the washing, whereof every one beareth twins, and there is not one barren among them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 7, E'As a piece of a pomegranate are thy temples within thy locks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 8, E'There are threescore queens, and fourscore concubines, and virgins without number.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 9, E'My dove, my undefiled is but one; she is the only one of her mother, she is the choice one of her that bare her. The daughters saw her, and blessed her; yea, the queens and the concubines, and they praised her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 10, E'Who is she that looketh forth as the morning, fair as the moon, clear as the sun, and terrible as an army with banners?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 11, E'I went down into the garden of nuts to see the fruits of the valley, and to see whether the vine flourished, and the pomegranates budded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 12, E'Or ever I was aware, my soul made me like the chariots of Amminadib.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 6, 13, E'Return, return, O Shulamite; return, return, that we may look upon thee. What will ye see in the Shulamite? As it were the company of two armies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 1, E'How beautiful are thy feet with shoes, O princeâ€™s daughter! the joints of thy thighs are like jewels, the work of the hands of a cunning workman.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 2, E'Thy navel is like a round goblet, which wanteth not liquor: thy belly is like an heap of wheat set about with lilies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 3, E'Thy two breasts are like two young roes that are twins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 4, E'Thy neck is as a tower of ivory; thine eyes like the fishpools in Heshbon, by the gate of Bathrabbim: thy nose is as the tower of Lebanon which looketh toward Damascus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 5, E'Thine head upon thee is like Carmel, and the hair of thine head like purple; the king is held in the galleries.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 6, E'How fair and how pleasant art thou, O love, for delights!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 7, E'This thy stature is like to a palm tree, and thy breasts to clusters of grapes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 8, E'I said, I will go up to the palm tree, I will take hold of the boughs thereof: now also thy breasts shall be as clusters of the vine, and the smell of thy nose like apples;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 9, E'And the roof of thy mouth like the best wine for my beloved, that goeth down sweetly, causing the lips of those that are asleep to speak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 10, E'I am my belovedâ€™s, and his desire is toward me.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Song of Solomon') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 11, E'Come, my beloved, let us go forth into the field; let us lodge in the villages.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 12, E'Let us get up early to the vineyards; let us see if the vine flourish, whether the tender grape appear, and the pomegranates bud forth: there will I give thee my loves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 7, 13, E'The mandrakes give a smell, and at our gates are all manner of pleasant fruits, new and old, which I have laid up for thee, O my beloved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 1, E'O that thou wert as my brother, that sucked the breasts of my mother! when I should find thee without, I would kiss thee; yea, I should not be despised.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 2, E'I would lead thee, and bring thee into my motherâ€™s house, who would instruct me: I would cause thee to drink of spiced wine of the juice of my pomegranate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 3, E'His left hand should be under my head, and his right hand should embrace me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 4, E'I charge you, O daughters of Jerusalem, that ye stir not up, nor awake my love, until he please.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 5, E'Who is this that cometh up from the wilderness, leaning upon her beloved? I raised thee up under the apple tree: there thy mother brought thee forth: there she brought thee forth that bare thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 6, E'Set me as a seal upon thine heart, as a seal upon thine arm: for love is strong as death; jealousy is cruel as the grave: the coals thereof are coals of fire, which hath a most vehement flame.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 7, E'Many waters cannot quench love, neither can the floods drown it: if a man would give all the substance of his house for love, it would utterly be contemned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 8, E'We have a little sister, and she hath no breasts: what shall we do for our sister in the day when she shall be spoken for?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 9, E'If she be a wall, we will build upon her a palace of silver: and if she be a door, we will inclose her with boards of cedar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 10, E'I am a wall, and my breasts like towers: then was I in his eyes as one that found favour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 11, E'Solomon had a vineyard at Baalhamon; he let out the vineyard unto keepers; every one for the fruit thereof was to bring a thousand pieces of silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 12, E'My vineyard, which is mine, is before me: thou, O Solomon, must have a thousand, and those that keep the fruit thereof two hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 13, E'Thou that dwellest in the gardens, the companions hearken to thy voice: cause me to hear it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c3096c37-687b-4065-bd47-466ba4c46790', 8, 14, E'Make haste, my beloved, and be thou like to a roe or to a young hart upon the mountains of spices.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Song of Solomon') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 1, E'The vision of Isaiah the son of Amoz, which he saw concerning Judah and Jerusalem in the days of Uzziah, Jotham, Ahaz, and Hezekiah, kings of Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 2, E'Hear, O heavens, and give ear, O earth: for the LORD hath spoken, I have nourished and brought up children, and they have rebelled against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 3, E'The ox knoweth his owner, and the ass his masterâ€™s crib: but Israel doth not know, my people doth not consider.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 4, E'Ah sinful nation, a people laden with iniquity, a seed of evildoers, children that are corrupters: they have forsaken the LORD, they have provoked the Holy One of Israel unto anger, they are gone away backward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 5, E'Why should ye be stricken any more? ye will revolt more and more: the whole head is sick, and the whole heart faint.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 6, E'From the sole of the foot even unto the head there is no soundness in it; but wounds, and bruises, and putrifying sores: they have not been closed, neither bound up, neither mollified with ointment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 7, E'Your country is desolate, your cities are burned with fire: your land, strangers devour it in your presence, and it is desolate, as overthrown by strangers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 8, E'And the daughter of Zion is left as a cottage in a vineyard, as a lodge in a garden of cucumbers, as a besieged city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 9, E'Except the LORD of hosts had left unto us a very small remnant, we should have been as Sodom, and we should have been like unto Gomorrah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 10, E'Hear the word of the LORD, ye rulers of Sodom; give ear unto the law of our God, ye people of Gomorrah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 11, E'To what purpose is the multitude of your sacrifices unto me? saith the LORD: I am full of the burnt offerings of rams, and the fat of fed beasts; and I delight not in the blood of bullocks, or of lambs, or of he goats.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 12, E'When ye come to appear before me, who hath required this at your hand, to tread my courts?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 13, E'Bring no more vain oblations; incense is an abomination unto me; the new moons and sabbaths, the calling of assemblies, I cannot away with; it is iniquity, even the solemn meeting.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 14, E'Your new moons and your appointed feasts my soul hateth: they are a trouble unto me; I am weary to bear them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 15, E'And when ye spread forth your hands, I will hide mine eyes from you: yea, when ye make many prayers, I will not hear: your hands are full of blood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 16, E'Wash you, make you clean; put away the evil of your doings from before mine eyes; cease to do evil;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 17, E'Learn to do well; seek judgment, relieve the oppressed, judge the fatherless, plead for the widow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 18, E'Come now, and let us reason together, saith the LORD: though your sins be as scarlet, they shall be as white as snow; though they be red like crimson, they shall be as wool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 19, E'If ye be willing and obedient, ye shall eat the good of the land:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 20, E'But if ye refuse and rebel, ye shall be devoured with the sword: for the mouth of the LORD hath spoken it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 21, E'How is the faithful city become an harlot! it was full of judgment; righteousness lodged in it; but now murderers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 22, E'Thy silver is become dross, thy wine mixed with water:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 23, E'Thy princes are rebellious, and companions of thieves: every one loveth gifts, and followeth after rewards: they judge not the fatherless, neither doth the cause of the widow come unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 24, E'Therefore saith the LORD, the LORD of hosts, the mighty One of Israel, Ah, I will ease me of mine adversaries, and avenge me of mine enemies:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 25, E'And I will turn my hand upon thee, and purely purge away thy dross, and take away all thy tin:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 26, E'And I will restore thy judges as at the first, and thy counsellors as at the beginning: afterward thou shalt be called, The city of righteousness, the faithful city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 27, E'Zion shall be redeemed with judgment, and her converts with righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 28, E'And the destruction of the transgressors and of the sinners shall be together, and they that forsake the LORD shall be consumed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 29, E'For they shall be ashamed of the oaks which ye have desired, and ye shall be confounded for the gardens that ye have chosen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 30, E'For ye shall be as an oak whose leaf fadeth, and as a garden that hath no water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 1, 31, E'And the strong shall be as tow, and the maker of it as a spark, and they shall both burn together, and none shall quench them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 1, E'The word that Isaiah the son of Amoz saw concerning Judah and Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 2, E'And it shall come to pass in the last days, that the mountain of the LORDâ€™s house shall be established in the top of the mountains, and shall be exalted above the hills; and all nations shall flow unto it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 3, E'And many people shall go and say, Come ye, and let us go up to the mountain of the LORD, to the house of the God of Jacob; and he will teach us of his ways, and we will walk in his paths: for out of Zion shall go forth the law, and the word of the LORD from Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 4, E'And he shall judge among the nations, and shall rebuke many people: and they shall beat their swords into plowshares, and their spears into pruninghooks: nation shall not lift up sword against nation, neither shall they learn war any more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 5, E'O house of Jacob, come ye, and let us walk in the light of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 6, E'Therefore thou hast forsaken thy people the house of Jacob, because they be replenished from the east, and are soothsayers like the Philistines, and they please themselves in the children of strangers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 7, E'Their land also is full of silver and gold, neither is there any end of their treasures; their land is also full of horses, neither is there any end of their chariots:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 8, E'Their land also is full of idols; they worship the work of their own hands, that which their own fingers have made:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 9, E'And the mean man boweth down, and the great man humbleth himself: therefore forgive them not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 10, E'Enter into the rock, and hide thee in the dust, for fear of the LORD, and for the glory of his majesty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 11, E'The lofty looks of man shall be humbled, and the haughtiness of men shall be bowed down, and the LORD alone shall be exalted in that day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 12, E'For the day of the LORD of hosts shall be upon every one that is proud and lofty, and upon every one that is lifted up; and he shall be brought low:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 13, E'And upon all the cedars of Lebanon, that are high and lifted up, and upon all the oaks of Bashan,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 14, E'And upon all the high mountains, and upon all the hills that are lifted up,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 15, E'And upon every high tower, and upon every fenced wall,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 16, E'And upon all the ships of Tarshish, and upon all pleasant pictures.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 17, E'And the loftiness of man shall be bowed down, and the haughtiness of men shall be made low: and the LORD alone shall be exalted in that day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 18, E'And the idols he shall utterly abolish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 19, E'And they shall go into the holes of the rocks, and into the caves of the earth, for fear of the LORD, and for the glory of his majesty, when he ariseth to shake terribly the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 20, E'In that day a man shall cast his idols of silver, and his idols of gold, which they made each one for himself to worship, to the moles and to the bats;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 21, E'To go into the clefts of the rocks, and into the tops of the ragged rocks, for fear of the LORD, and for the glory of his majesty, when he ariseth to shake terribly the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 2, 22, E'Cease ye from man, whose breath is in his nostrils: for wherein is he to be accounted of ?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 1, E'For, behold, the Lord, the LORD of hosts, doth take away from Jerusalem and from Judah the stay and the staff, the whole stay of bread, and the whole stay of water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 2, E'The mighty man, and the man of war, the judge, and the prophet, and the prudent, and the ancient,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 3, E'The captain of fifty, and the honourable man, and the counsellor, and the cunning artificer, and the eloquent orator.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 4, E'And I will give children to be their princes, and babes shall rule over them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 5, E'And the people shall be oppressed, every one by another, and every one by his neighbour: the child shall behave himself proudly against the ancient, and the base against the honourable.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 6, E'When a man shall take hold of his brother of the house of his father, saying, Thou hast clothing, be thou our ruler, and let this ruin be under thy hand:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 7, E'In that day shall he swear, saying, I will not be an healer; for in my house is neither bread nor clothing: make me not a ruler of the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 8, E'For Jerusalem is ruined, and Judah is fallen: because their tongue and their doings are against the LORD, to provoke the eyes of his glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 9, E'The shew of their countenance doth witness against them; and they declare their sin as Sodom, they hide it not. Woe unto their soul! for they have rewarded evil unto themselves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 10, E'Say ye to the righteous, that it shall be well with him: for they shall eat the fruit of their doings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 11, E'Woe unto the wicked! it shall be ill with him: for the reward of his hands shall be given him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 12, E'As for my people, children are their oppressors, and women rule over them. O my people, they which lead thee cause thee to err, and destroy the way of thy paths.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 13, E'The LORD standeth up to plead, and standeth to judge the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 14, E'The LORD will enter into judgment with the ancients of his people, and the princes thereof: for ye have eaten up the vineyard; the spoil of the poor is in your houses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 15, E'What mean ye that ye beat my people to pieces, and grind the faces of the poor? saith the Lord GOD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 16, E'Moreover the LORD saith, Because the daughters of Zion are haughty, and walk with stretched forth necks and wanton eyes, walking and mincing as they go, and making a tinkling with their feet:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 17, E'Therefore the LORD will smite with a scab the crown of the head of the daughters of Zion, and the LORD will discover their secret parts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 18, E'In that day the Lord will take away the bravery of their tinkling ornaments about their feet, and their cauls, and their round tires like the moon,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 19, E'The chains, and the bracelets, and the mufflers,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 20, E'The bonnets, and the ornaments of the legs, and the headbands, and the tablets, and the earrings,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 21, E'The rings, and nose jewels,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 22, E'The changeable suits of apparel, and the mantles, and the wimples, and the crisping pins,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 23, E'The glasses, and the fine linen, and the hoods, and the vails.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 24, E'And it shall come to pass, that instead of sweet smell there shall be stink; and instead of a girdle a rent; and instead of well set hair baldness; and instead of a stomacher a girding of sackcloth; and burning instead of beauty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 25, E'Thy men shall fall by the sword, and thy mighty in the war.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 3, 26, E'And her gates shall lament and mourn; and she being desolate shall sit upon the ground.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 4, 1, E'And in that day seven women shall take hold of one man, saying, We will eat our own bread, and wear our own apparel: only let us be called by thy name, to take away our reproach.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 4, 2, E'In that day shall the branch of the LORD be beautiful and glorious, and the fruit of the earth shall be excellent and comely for them that are escaped of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 4, 3, E'And it shall come to pass, that he that is left in Zion, and he that remaineth in Jerusalem, shall be called holy, even every one that is written among the living in Jerusalem:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 4, 4, E'When the Lord shall have washed away the filth of the daughters of Zion, and shall have purged the blood of Jerusalem from the midst thereof by the spirit of judgment, and by the spirit of burning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 4, 5, E'And the LORD will create upon every dwelling place of mount Zion, and upon her assemblies, a cloud and smoke by day, and the shining of a flaming fire by night: for upon all the glory shall be a defence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 4, 6, E'And there shall be a tabernacle for a shadow in the day time from the heat, and for a place of refuge, and for a covert from storm and from rain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 1, E'Now will I sing to my wellbeloved a song of my beloved touching his vineyard. My wellbeloved hath a vineyard in a very fruitful hill:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 2, E'And he fenced it, and gathered out the stones thereof, and planted it with the choicest vine, and built a tower in the midst of it, and also made a winepress therein: and he looked that it should bring forth grapes, and it brought forth wild grapes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 3, E'And now, O inhabitants of Jerusalem, and men of Judah, judge, I pray you, betwixt me and my vineyard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 4, E'What could have been done more to my vineyard, that I have not done in it? wherefore, when I looked that it should bring forth grapes, brought it forth wild grapes?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 5, E'And now go to; I will tell you what I will do to my vineyard: I will take away the hedge thereof, and it shall be eaten up; and break down the wall thereof, and it shall be trodden down:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 6, E'And I will lay it waste: it shall not be pruned, nor digged; but there shall come up briers and thorns: I will also command the clouds that they rain no rain upon it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 7, E'For the vineyard of the LORD of hosts is the house of Israel, and the men of Judah his pleasant plant: and he looked for judgment, but behold oppression; for righteousness, but behold a cry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 8, E'Woe unto them that join house to house, that lay field to field, till there be no place, that they may be placed alone in the midst of the earth!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 9, E'In mine ears said the LORD of hosts, Of a truth many houses shall be desolate, even great and fair, without inhabitant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 10, E'Yea, ten acres of vineyard shall yield one bath, and the seed of an homer shall yield an ephah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 11, E'Woe unto them that rise up early in the morning, that they may follow strong drink; that continue until night, till wine inflame them!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 12, E'And the harp, and the viol, the tabret, and pipe, and wine, are in their feasts: but they regard not the work of the LORD, neither consider the operation of his hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 13, E'Therefore my people are gone into captivity, because they have no knowledge: and their honourable men are famished, and their multitude dried up with thirst.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 14, E'Therefore hell hath enlarged herself, and opened her mouth without measure: and their glory, and their multitude, and their pomp, and he that rejoiceth, shall descend into it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 15, E'And the mean man shall be brought down, and the mighty man shall be humbled, and the eyes of the lofty shall be humbled:')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Isaiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 16, E'But the LORD of hosts shall be exalted in judgment, and God that is holy shall be sanctified in righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 17, E'Then shall the lambs feed after their manner, and the waste places of the fat ones shall strangers eat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 18, E'Woe unto them that draw iniquity with cords of vanity, and sin as it were with a cart rope:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 19, E'That say, Let him make speed, and hasten his work, that we may see it: and let the counsel of the Holy One of Israel draw nigh and come, that we may know it!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 20, E'Woe unto them that call evil good, and good evil; that put darkness for light, and light for darkness; that put bitter for sweet, and sweet for bitter!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 21, E'Woe unto them that are wise in their own eyes, and prudent in their own sight!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 22, E'Woe unto them that are mighty to drink wine, and men of strength to mingle strong drink:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 23, E'Which justify the wicked for reward, and take away the righteousness of the righteous from him!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 24, E'Therefore as the fire devoureth the stubble, and the flame consumeth the chaff, so their root shall be as rottenness, and their blossom shall go up as dust: because they have cast away the law of the LORD of hosts, and despised the word of the Holy One of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 25, E'Therefore is the anger of the LORD kindled against his people, and he hath stretched forth his hand against them, and hath smitten them: and the hills did tremble, and their carcases were torn in the midst of the streets. For all this his anger is not turned away, but his hand is stretched out still.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 26, E'And he will lift up an ensign to the nations from far, and will hiss unto them from the end of the earth: and, behold, they shall come with speed swiftly:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 27, E'None shall be weary nor stumble among them; none shall slumber nor sleep; neither shall the girdle of their loins be loosed, nor the latchet of their shoes be broken:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 28, E'Whose arrows are sharp, and all their bows bent, their horsesâ€™ hoofs shall be counted like flint, and their wheels like a whirlwind:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 29, E'Their roaring shall be like a lion, they shall roar like young lions: yea, they shall roar, and lay hold of the prey, and shall carry it away safe, and none shall deliver it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 5, 30, E'And in that day they shall roar against them like the roaring of the sea: and if one look unto the land, behold darkness and sorrow, and the light is darkened in the heavens thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 1, E'In the year that king Uzziah died I saw also the LORD sitting upon a throne, high and lifted up, and his train filled the temple.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 2, E'Above it stood the seraphims: each one had six wings; with twain he covered his face, and with twain he covered his feet, and with twain he did fly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 3, E'And one cried unto another, and said, Holy, holy, holy, is the LORD of hosts: the whole earth is full of his glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 4, E'And the posts of the door moved at the voice of him that cried, and the house was filled with smoke.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 5, E'Then said I, Woe is me! for I am undone; because I am a man of unclean lips, and I dwell in the midst of a people of unclean lips: for mine eyes have seen the King, the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 6, E'Then flew one of the seraphims unto me, having a live coal in his hand, which he had taken with the tongs from off the altar:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 7, E'And he laid it upon my mouth, and said, Lo, this hath touched thy lips; and thine iniquity is taken away, and thy sin purged.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 8, E'Also I heard the voice of the Lord, saying, Whom shall I send, and who will go for us? Then said I, Here am I; send me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 9, E'And he said, Go, and tell this people, Hear ye indeed, but understand not; and see ye indeed, but perceive not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 10, E'Make the heart of this people fat, and make their ears heavy, and shut their eyes; lest they see with their eyes, and hear with their ears, and understand with their heart, and convert, and be healed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 11, E'Then said I, Lord, how long? And he answered, Until the cities be wasted without inhabitant, and the houses without man, and the land be utterly desolate,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 12, E'And the LORD have removed men far away, and there be a great forsaking in the midst of the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 6, 13, E'But yet in it shall be a tenth, and it shall return, and shall be eaten: as a teil tree, and as an oak, whose substance is in them, when they cast their leaves: so the holy seed shall be the substance thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 1, E'And it came to pass in the days of Ahaz the son of Jotham, the son of Uzziah, king of Judah, that Rezin the king of Syria, and Pekah the son of Remaliah, king of Israel, went up toward Jerusalem to war against it, but could not prevail against it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 2, E'And it was told the house of David, saying, Syria is confederate with Ephraim. And his heart was moved, and the heart of his people, as the trees of the wood are moved with the wind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 3, E'Then said the LORD unto Isaiah, Go forth now to meet Ahaz, thou, and Shearjashub thy son, at the end of the conduit of the upper pool in the highway of the fullerâ€™s field;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 4, E'And say unto him, Take heed, and be quiet; fear not, neither be fainthearted for the two tails of these smoking firebrands, for the fierce anger of Rezin with Syria, and of the son of Remaliah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 5, E'Because Syria, Ephraim, and the son of Remaliah, have taken evil counsel against thee, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 6, E'Let us go up against Judah, and vex it, and let us make a breach therein for us, and set a king in the midst of it, even the son of Tabeal:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 7, E'Thus saith the Lord GOD, It shall not stand, neither shall it come to pass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 8, E'For the head of Syria is Damascus, and the head of Damascus is Rezin; and within threescore and five years shall Ephraim be broken, that it be not a people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 9, E'And the head of Ephraim is Samaria, and the head of Samaria is Remaliahâ€™s son. If ye will not believe, surely ye shall not be established.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 10, E'Moreover the LORD spake again unto Ahaz, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 11, E'Ask thee a sign of the LORD thy God; ask it either in the depth, or in the height above.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 12, E'But Ahaz said, I will not ask, neither will I tempt the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 13, E'And he said, Hear ye now, O house of David; Is it a small thing for you to weary men, but will ye weary my God also?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 14, E'Therefore the Lord himself shall give you a sign; Behold, a virgin shall conceive, and bear a son, and shall call his name Immanuel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 15, E'Butter and honey shall he eat, that he may know to refuse the evil, and choose the good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 16, E'For before the child shall know to refuse the evil, and choose the good, the land that thou abhorrest shall be forsaken of both her kings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 17, E'The LORD shall bring upon thee, and upon thy people, and upon thy fatherâ€™s house, days that have not come, from the day that Ephraim departed from Judah; even the king of Assyria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 18, E'And it shall come to pass in that day, that the LORD shall hiss for the fly that is in the uttermost part of the rivers of Egypt, and for the bee that is in the land of Assyria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 19, E'And they shall come, and shall rest all of them in the desolate valleys, and in the holes of the rocks, and upon all thorns, and upon all bushes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 20, E'In the same day shall the Lord shave with a razor that is hired, namely, by them beyond the river, by the king of Assyria, the head, and the hair of the feet: and it shall also consume the beard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 21, E'And it shall come to pass in that day, that a man shall nourish a young cow, and two sheep;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 22, E'And it shall come to pass, for the abundance of milk that they shall give he shall eat butter: for butter and honey shall every one eat that is left in the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 23, E'And it shall come to pass in that day, that every place shall be, where there were a thousand vines at a thousand silverlings, it shall even be for briers and thorns.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 24, E'With arrows and with bows shall men come thither; because all the land shall become briers and thorns.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 7, 25, E'And on all hills that shall be digged with the mattock, there shall not come thither the fear of briers and thorns: but it shall be for the sending forth of oxen, and for the treading of lesser cattle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 1, E'Moreover the LORD said unto me, Take thee a great roll, and write in it with a manâ€™s pen concerning Mahershalalhashbaz.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 2, E'And I took unto me faithful witnesses to record, Uriah the priest, and Zechariah the son of Jeberechiah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 3, E'And I went unto the prophetess; and she conceived, and bare a son. Then said the LORD to me, Call his name Mahershalalhashbaz.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 4, E'For before the child shall have knowledge to cry, My father, and my mother, the riches of Damascus and the spoil of Samaria shall be taken away before the king of Assyria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 5, E'The LORD spake also unto me again, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 6, E'Forasmuch as this people refuseth the waters of Shiloah that go softly, and rejoice in Rezin and Remaliahâ€™s son;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 7, E'Now therefore, behold, the Lord bringeth up upon them the waters of the river, strong and many, even the king of Assyria, and all his glory: and he shall come up over all his channels, and go over all his banks:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 8, E'And he shall pass through Judah; he shall overflow and go over, he shall reach even to the neck; and the stretching out of his wings shall fill the breadth of thy land, O Immanuel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 9, E'Associate yourselves, O ye people, and ye shall be broken in pieces; and give ear, all ye of far countries: gird yourselves, and ye shall be broken in pieces; gird yourselves, and ye shall be broken in pieces.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 10, E'Take counsel together, and it shall come to nought; speak the word, and it shall not stand: for God is with us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 11, E'For the LORD spake thus to me with a strong hand, and instructed me that I should not walk in the way of this people, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 12, E'Say ye not, A confederacy, to all them to whom this people shall say, A confederacy; neither fear ye their fear, nor be afraid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 13, E'Sanctify the LORD of hosts himself; and let him be your fear, and let him be your dread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 14, E'And he shall be for a sanctuary; but for a stone of stumbling and for a rock of offence to both the houses of Israel, for a gin and for a snare to the inhabitants of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 15, E'And many among them shall stumble, and fall, and be broken, and be snared, and be taken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 16, E'Bind up the testimony, seal the law among my disciples.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 17, E'And I will wait upon the LORD, that hideth his face from the house of Jacob, and I will look for him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 18, E'Behold, I and the children whom the LORD hath given me are for signs and for wonders in Israel from the LORD of hosts, which dwelleth in mount Zion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 19, E'And when they shall say unto you, Seek unto them that have familiar spirits, and unto wizards that peep, and that mutter: should not a people seek unto their God? for the living to the dead?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 20, E'To the law and to the testimony: if they speak not according to this word, it is because there is no light in them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 21, E'And they shall pass through it, hardly bestead and hungry: and it shall come to pass, that when they shall be hungry, they shall fret themselves, and curse their king and their God, and look upward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 8, 22, E'And they shall look unto the earth; and behold trouble and darkness, dimness of anguish; and they shall be driven to darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 1, E'Nevertheless the dimness shall not be such as was in her vexation, when at the first he lightly afflicted the land of Zebulun and the land of Naphtali, and afterward did more grievously afflict her by the way of the sea, beyond Jordan, in Galilee of the nations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 2, E'The people that walked in darkness have seen a great light: they that dwell in the land of the shadow of death, upon them hath the light shined.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 3, E'Thou hast multiplied the nation, and not increased the joy: they joy before thee according to the joy in harvest, and as men rejoice when they divide the spoil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 4, E'For thou hast broken the yoke of his burden, and the staff of his shoulder, the rod of his oppressor, as in the day of Midian.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 5, E'For every battle of the warrior is with confused noise, and garments rolled in blood; but this shall be with burning and fuel of fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 6, E'For unto us a child is born, unto us a son is given: and the government shall be upon his shoulder: and his name shall be called Wonderful, Counsellor, The mighty God, The everlasting Father, The Prince of Peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 7, E'Of the increase of his government and peace there shall be no end, upon the throne of David, and upon his kingdom, to order it, and to establish it with judgment and with justice from henceforth even for ever. The zeal of the LORD of hosts will perform this.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 8, E'The Lord sent a word into Jacob, and it hath lighted upon Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 9, E'And all the people shall know, even Ephraim and the inhabitant of Samaria, that say in the pride and stoutness of heart,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 10, E'The bricks are fallen down, but we will build with hewn stones: the sycomores are cut down, but we will change them into cedars.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 11, E'Therefore the LORD shall set up the adversaries of Rezin against him, and join his enemies together;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 12, E'The Syrians before, and the Philistines behind; and they shall devour Israel with open mouth. For all this his anger is not turned away, but his hand is stretched out still.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 13, E'For the people turneth not unto him that smiteth them, neither do they seek the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 14, E'Therefore the LORD will cut off from Israel head and tail, branch and rush, in one day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 15, E'The ancient and honourable, he is the head; and the prophet that teacheth lies, he is the tail.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 16, E'For the leaders of this people cause them to err; and they that are led of them are destroyed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 17, E'Therefore the LORD shall have no joy in their young men, neither shall have mercy on their fatherless and widows: for every one is an hypocrite and an evildoer, and every mouth speaketh folly. For all this his anger is not turned away, but his hand is stretched out still.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 18, E'For wickedness burneth as the fire: it shall devour the briers and thorns, and shall kindle in the thickets of the forest, and they shall mount up like the lifting up of smoke.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 19, E'Through the wrath of the LORD of hosts is the land darkened, and the people shall be as the fuel of the fire: no man shall spare his brother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 20, E'And he shall snatch on the right hand, and be hungry; and he shall eat on the left hand, and they shall not be satisfied: they shall eat every man the flesh of his own arm:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 9, 21, E'Manasseh, Ephraim; and Ephraim, Manasseh: and they together shall be against Judah. For all this his anger is not turned away, but his hand is stretched out still.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 1, E'Woe unto them that decree unrighteous decrees, and that write grievousness which they have prescribed;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 2, E'To turn aside the needy from judgment, and to take away the right from the poor of my people, that widows may be their prey, and that they may rob the fatherless!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 3, E'And what will ye do in the day of visitation, and in the desolation which shall come from far? to whom will ye flee for help? and where will ye leave your glory?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 4, E'Without me they shall bow down under the prisoners, and they shall fall under the slain. For all this his anger is not turned away, but his hand is stretched out still.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Isaiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 5, E'O Assyrian, the rod of mine anger, and the staff in their hand is mine indignation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 6, E'I will send him against an hypocritical nation, and against the people of my wrath will I give him a charge, to take the spoil, and to take the prey, and to tread them down like the mire of the streets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 7, E'Howbeit he meaneth not so, neither doth his heart think so; but it is in his heart to destroy and cut off nations not a few.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 8, E'For he saith, Are not my princes altogether kings?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 9, E'Is not Calno as Carchemish? is not Hamath as Arpad? is not Samaria as Damascus?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 10, E'As my hand hath found the kingdoms of the idols, and whose graven images did excel them of Jerusalem and of Samaria;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 11, E'Shall I not, as I have done unto Samaria and her idols, so do to Jerusalem and her idols?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 12, E'Wherefore it shall come to pass, that when the Lord hath performed his whole work upon mount Zion and on Jerusalem, I will punish the fruit of the stout heart of the king of Assyria, and the glory of his high looks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 13, E'For he saith, By the strength of my hand I have done it, and by my wisdom; for I am prudent: and I have removed the bounds of the people, and have robbed their treasures, and I have put down the inhabitants like a valiant man:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 14, E'And my hand hath found as a nest the riches of the people: and as one gathereth eggs that are left, have I gathered all the earth; and there was none that moved the wing, or opened the mouth, or peeped.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 15, E'Shall the axe boast itself against him that heweth therewith? or shall the saw magnify itself against him that shaketh it? as if the rod should shake itself against them that lift it up, or as if the staff should lift up itself, as if it were no wood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 16, E'Therefore shall the Lord, the Lord of hosts, send among his fat ones leanness; and under his glory he shall kindle a burning like the burning of a fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 17, E'And the light of Israel shall be for a fire, and his Holy One for a flame: and it shall burn and devour his thorns and his briers in one day;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 18, E'And shall consume the glory of his forest, and of his fruitful field, both soul and body: and they shall be as when a standard-bearer fainteth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 19, E'And the rest of the trees of his forest shall be few, that a child may write them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 20, E'And it shall come to pass in that day, that the remnant of Israel, and such as are escaped of the house of Jacob, shall no more again stay upon him that smote them; but shall stay upon the LORD, the Holy One of Israel, in truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 21, E'The remnant shall return, even the remnant of Jacob, unto the mighty God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 22, E'For though thy people Israel be as the sand of the sea, yet a remnant of them shall return: the consumption decreed shall overflow with righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 23, E'For the Lord GOD of hosts shall make a consumption, even determined, in the midst of all the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 24, E'Therefore thus saith the Lord GOD of hosts, O my people that dwellest in Zion, be not afraid of the Assyrian: he shall smite thee with a rod, and shall lift up his staff against thee, after the manner of Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 25, E'For yet a very little while, and the indignation shall cease, and mine anger in their destruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 26, E'And the LORD of hosts shall stir up a scourge for him according to the slaughter of Midian at the rock of Oreb: and as his rod was upon the sea, so shall he lift it up after the manner of Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 27, E'And it shall come to pass in that day, that his burden shall be taken away from off thy shoulder, and his yoke from off thy neck, and the yoke shall be destroyed because of the anointing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 28, E'He is come to Aiath, he is passed to Migron; at Michmash he hath laid up his carriages:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 29, E'They are gone over the passage: they have taken up their lodging at Geba; Ramah is afraid; Gibeah of Saul is fled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 30, E'Lift up thy voice, O daughter of Gallim: cause it to be heard unto Laish, O poor Anathoth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 31, E'Madmenah is removed; the inhabitants of Gebim gather themselves to flee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 32, E'As yet shall he remain at Nob that day: he shall shake his hand against the mount of the daughter of Zion, the hill of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 33, E'Behold, the Lord, the LORD of hosts, shall lop the bough with terror: and the high ones of stature shall be hewn down, and the haughty shall be humbled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 10, 34, E'And he shall cut down the thickets of the forest with iron, and Lebanon shall fall by a mighty one.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 1, E'And there shall come forth a rod out of the stem of Jesse, and a Branch shall grow out of his roots:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 2, E'And the spirit of the LORD shall rest upon him, the spirit of wisdom and understanding, the spirit of counsel and might, the spirit of knowledge and of the fear of the LORD;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 3, E'And shall make him of quick understanding in the fear of the LORD: and he shall not judge after the sight of his eyes, neither reprove after the hearing of his ears:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 4, E'But with righteousness shall he judge the poor, and reprove with equity for the meek of the earth: and he shall smite the earth with the rod of his mouth, and with the breath of his lips shall he slay the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 5, E'And righteousness shall be the girdle of his loins, and faithfulness the girdle of his reins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 6, E'The wolf also shall dwell with the lamb, and the leopard shall lie down with the kid; and the calf and the young lion and the fatling together; and a little child shall lead them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 7, E'And the cow and the bear shall feed; their young ones shall lie down together: and the lion shall eat straw like the ox.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 8, E'And the sucking child shall play on the hole of the asp, and the weaned child shall put his hand on the cockatriceâ€™ den.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 9, E'They shall not hurt nor destroy in all my holy mountain: for the earth shall be full of the knowledge of the LORD, as the waters cover the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 10, E'And in that day there shall be a root of Jesse, which shall stand for an ensign of the people; to it shall the Gentiles seek: and his rest shall be glorious.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 11, E'And it shall come to pass in that day, that the Lord shall set his hand again the second time to recover the remnant of his people, which shall be left, from Assyria, and from Egypt, and from Pathros, and from Cush, and from Elam, and from Shinar, and from Hamath, and from the islands of the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 12, E'And he shall set up an ensign for the nations, and shall assemble the outcasts of Israel, and gather together the dispersed of Judah from the four corners of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 13, E'The envy also of Ephraim shall depart, and the adversaries of Judah shall be cut off: Ephraim shall not envy Judah, and Judah shall not vex Ephraim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 14, E'But they shall fly upon the shoulders of the Philistines toward the west; they shall spoil them of the east together: they shall lay their hand upon Edom and Moab; and the children of Ammon shall obey them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 15, E'And the LORD shall utterly destroy the tongue of the Egyptian sea; and with his mighty wind shall he shake his hand over the river, and shall smite it in the seven streams, and make men go over dryshod.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 11, 16, E'And there shall be an highway for the remnant of his people, which shall be left, from Assyria; like as it was to Israel in the day that he came up out of the land of Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 12, 1, E'And in that day thou shalt say, O LORD, I will praise thee: though thou wast angry with me, thine anger is turned away, and thou comfortedst me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 12, 2, E'Behold, God is my salvation; I will trust, and not be afraid: for the LORD JEHOVAH is my strength and my song; he also is become my salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 12, 3, E'Therefore with joy shall ye draw water out of the wells of salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 12, 4, E'And in that day shall ye say, Praise the LORD, call upon his name, declare his doings among the people, make mention that his name is exalted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 12, 5, E'Sing unto the LORD; for he hath done excellent things: this is known in all the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 12, 6, E'Cry out and shout, thou inhabitant of Zion: for great is the Holy One of Israel in the midst of thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 1, E'The burden of Babylon, which Isaiah the son of Amoz did see.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 2, E'Lift ye up a banner upon the high mountain, exalt the voice unto them, shake the hand, that they may go into the gates of the nobles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 3, E'I have commanded my sanctified ones, I have also called my mighty ones for mine anger, even them that rejoice in my highness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 4, E'The noise of a multitude in the mountains, like as of a great people; a tumultuous noise of the kingdoms of nations gathered together: the LORD of hosts mustereth the host of the battle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 5, E'They come from a far country, from the end of heaven, even the LORD, and the weapons of his indignation, to destroy the whole land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 6, E'Howl ye; for the day of the LORD is at hand; it shall come as a destruction from the Almighty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 7, E'Therefore shall all hands be faint, and every manâ€™s heart shall melt:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 8, E'And they shall be afraid: pangs and sorrows shall take hold of them; they shall be in pain as a woman that travaileth: they shall be amazed one at another; their faces shall be as flames.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 9, E'Behold, the day of the LORD cometh, cruel both with wrath and fierce anger, to lay the land desolate: and he shall destroy the sinners thereof out of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 10, E'For the stars of heaven and the constellations thereof shall not give their light: the sun shall be darkened in his going forth, and the moon shall not cause her light to shine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 11, E'And I will punish the world for their evil, and the wicked for their iniquity; and I will cause the arrogancy of the proud to cease, and will lay low the haughtiness of the terrible.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 12, E'I will make a man more precious than fine gold; even a man than the golden wedge of Ophir.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 13, E'Therefore I will shake the heavens, and the earth shall remove out of her place, in the wrath of the LORD of hosts, and in the day of his fierce anger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 14, E'And it shall be as the chased roe, and as a sheep that no man taketh up: they shall every man turn to his own people, and flee every one into his own land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 15, E'Every one that is found shall be thrust through; and every one that is joined unto them shall fall by the sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 16, E'Their children also shall be dashed to pieces before their eyes; their houses shall be spoiled, and their wives ravished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 17, E'Behold, I will stir up the Medes against them, which shall not regard silver; and as for gold, they shall not delight in it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 18, E'Their bows also shall dash the young men to pieces; and they shall have no pity on the fruit of the womb; their eye shall not spare children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 19, E'And Babylon, the glory of kingdoms, the beauty of the Chaldeesâ€™ excellency, shall be as when God overthrew Sodom and Gomorrah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 20, E'It shall never be inhabited, neither shall it be dwelt in from generation to generation: neither shall the Arabian pitch tent there; neither shall the shepherds make their fold there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 21, E'But wild beasts of the desert shall lie there; and their houses shall be full of doleful creatures; and owls shall dwell there, and satyrs shall dance there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 13, 22, E'And the wild beasts of the islands shall cry in their desolate houses, and dragons in their pleasant palaces: and her time is near to come, and her days shall not be prolonged.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 1, E'For the LORD will have mercy on Jacob, and will yet choose Israel, and set them in their own land: and the strangers shall be joined with them, and they shall cleave to the house of Jacob.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 2, E'And the people shall take them, and bring them to their place: and the house of Israel shall possess them in the land of the LORD for servants and handmaids: and they shall take them captives, whose captives they were; and they shall rule over their oppressors.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 3, E'And it shall come to pass in the day that the LORD shall give thee rest from thy sorrow, and from thy fear, and from the hard bondage wherein thou wast made to serve,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 4, E'That thou shalt take up this proverb against the king of Babylon, and say, How hath the oppressor ceased! the golden city ceased!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 5, E'The LORD hath broken the staff of the wicked, and the sceptre of the rulers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 6, E'He who smote the people in wrath with a continual stroke, he that ruled the nations in anger, is persecuted, and none hindereth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 7, E'The whole earth is at rest, and is quiet: they break forth into singing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 8, E'Yea, the fir trees rejoice at thee, and the cedars of Lebanon, saying, Since thou art laid down, no feller is come up against us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 9, E'Hell from beneath is moved for thee to meet thee at thy coming: it stirreth up the dead for thee, even all the chief ones of the earth; it hath raised up from their thrones all the kings of the nations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 10, E'All they shall speak and say unto thee, Art thou also become weak as we? art thou become like unto us?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 11, E'Thy pomp is brought down to the grave, and the noise of thy viols: the worm is spread under thee, and the worms cover thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 12, E'How art thou fallen from heaven, O Lucifer, son of the morning! how art thou cut down to the ground, which didst weaken the nations!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 13, E'For thou hast said in thine heart, I will ascend into heaven, I will exalt my throne above the stars of God: I will sit also upon the mount of the congregation, in the sides of the north:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 14, E'I will ascend above the heights of the clouds; I will be like the most High.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 15, E'Yet thou shalt be brought down to hell, to the sides of the pit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 16, E'They that see thee shall narrowly look upon thee, and consider thee, saying, Is this the man that made the earth to tremble, that did shake kingdoms;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 17, E'That made the world as a wilderness, and destroyed the cities thereof; that opened not the house of his prisoners?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 18, E'All the kings of the nations, even all of them, lie in glory, every one in his own house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 19, E'But thou art cast out of thy grave like an abominable branch, and as the raiment of those that are slain, thrust through with a sword, that go down to the stones of the pit; as a carcase trodden under feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 20, E'Thou shalt not be joined with them in burial, because thou hast destroyed thy land, and slain thy people: the seed of evildoers shall never be renowned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 21, E'Prepare slaughter for his children for the iniquity of their fathers; that they do not rise, nor possess the land, nor fill the face of the world with cities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 22, E'For I will rise up against them, saith the LORD of hosts, and cut off from Babylon the name, and remnant, and son, and nephew, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 23, E'I will also make it a possession for the bittern, and pools of water: and I will sweep it with the besom of destruction, saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 24, E'The LORD of hosts hath sworn, saying, Surely as I have thought, so shall it come to pass; and as I have purposed, so shall it stand:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 25, E'That I will break the Assyrian in my land, and upon my mountains tread him under foot: then shall his yoke depart from off them, and his burden depart from off their shoulders.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 26, E'This is the purpose that is purposed upon the whole earth: and this is the hand that is stretched out upon all the nations.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Isaiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 27, E'For the LORD of hosts hath purposed, and who shall disannul it? and his hand is stretched out, and who shall turn it back?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 28, E'In the year that king Ahaz died was this burden.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 29, E'Rejoice not thou, whole Palestina, because the rod of him that smote thee is broken: for out of the serpentâ€™s root shall come forth a cockatrice, and his fruit shall be a fiery flying serpent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 30, E'And the firstborn of the poor shall feed, and the needy shall lie down in safety: and I will kill thy root with famine, and he shall slay thy remnant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 31, E'Howl, O gate; cry, O city; thou, whole Palestina, art dissolved: for there shall come from the north a smoke, and none shall be alone in his appointed times.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 14, 32, E'What shall one then answer the messengers of the nation? That the LORD hath founded Zion, and the poor of his people shall trust in it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 15, 1, E'The burden of Moab. Because in the night Ar of Moab is laid waste, and brought to silence; because in the night Kir of Moab is laid waste, and brought to silence;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 15, 2, E'He is gone up to Bajith, and to Dibon, the high places, to weep: Moab shall howl over Nebo, and over Medeba: on all their heads shall be baldness, and every beard cut off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 15, 3, E'In their streets they shall gird themselves with sackcloth: on the tops of their houses, and in their streets, every one shall howl, weeping abundantly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 15, 4, E'And Heshbon shall cry, and Elealeh: their voice shall be heard even unto Jahaz: therefore the armed soldiers of Moab shall cry out; his life shall be grievous unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 15, 5, E'My heart shall cry out for Moab; his fugitives shall flee unto Zoar, an heifer of three years old: for by the mounting up of Luhith with weeping shall they go it up; for in the way of Horonaim they shall raise up a cry of destruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 15, 6, E'For the waters of Nimrim shall be desolate: for the hay is withered away, the grass faileth, there is no green thing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 15, 7, E'Therefore the abundance they have gotten, and that which they have laid up, shall they carry away to the brook of the willows.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 15, 8, E'For the cry is gone round about the borders of Moab; the howling thereof unto Eglaim, and the howling thereof unto Beerelim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 15, 9, E'For the waters of Dimon shall be full of blood: for I will bring more upon Dimon, lions upon him that escapeth of Moab, and upon the remnant of the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 1, E'Send ye the lamb to the ruler of the land from Sela to the wilderness, unto the mount of the daughter of Zion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 2, E'For it shall be, that, as a wandering bird cast out of the nest, so the daughters of Moab shall be at the fords of Arnon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 3, E'Take counsel, execute judgment; make thy shadow as the night in the midst of the noonday; hide the outcasts; bewray not him that wandereth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 4, E'Let mine outcasts dwell with thee, Moab; be thou a covert to them from the face of the spoiler: for the extortioner is at an end, the spoiler ceaseth, the oppressors are consumed out of the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 5, E'And in mercy shall the throne be established: and he shall sit upon it in truth in the tabernacle of David, judging, and seeking judgment, and hasting righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 6, E'We have heard of the pride of Moab; he is very proud: even of his haughtiness, and his pride, and his wrath: but his lies shall not be so.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 7, E'Therefore shall Moab howl for Moab, every one shall howl: for the foundations of Kirhareseth shall ye mourn; surely they are stricken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 8, E'For the fields of Heshbon languish, and the vine of Sibmah: the lords of the heathen have broken down the principal plants thereof, they are come even unto Jazer, they wandered through the wilderness: her branches are stretched out, they are gone over the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 9, E'Therefore I will bewail with the weeping of Jazer the vine of Sibmah: I will water thee with my tears, O Heshbon, and Elealeh: for the shouting for thy summer fruits and for thy harvest is fallen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 10, E'And gladness is taken away, and joy out of the plentiful field; and in the vineyards there shall be no singing, neither shall there be shouting: the treaders shall tread out no wine in their presses; I have made their vintage shouting to cease.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 11, E'Wherefore my bowels shall sound like an harp for Moab, and mine inward parts for Kirharesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 12, E'And it shall come to pass, when it is seen that Moab is weary on the high place, that he shall come to his sanctuary to pray; but he shall not prevail.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 13, E'This is the word that the LORD hath spoken concerning Moab since that time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 16, 14, E'But now the LORD hath spoken, saying, Within three years, as the years of an hireling, and the glory of Moab shall be contemned, with all that great multitude; and the remnant shall be very small and feeble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 1, E'The burden of Damascus. Behold, Damascus is taken away from being a city, and it shall be a ruinous heap.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 2, E'The cities of Aroer are forsaken: they shall be for flocks, which shall lie down, and none shall make them afraid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 3, E'The fortress also shall cease from Ephraim, and the kingdom from Damascus, and the remnant of Syria: they shall be as the glory of the children of Israel, saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 4, E'And in that day it shall come to pass, that the glory of Jacob shall be made thin, and the fatness of his flesh shall wax lean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 5, E'And it shall be as when the harvestman gathereth the corn, and reapeth the ears with his arm; and it shall be as he that gathereth ears in the valley of Rephaim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 6, E'Yet gleaning grapes shall be left in it, as the shaking of an olive tree, two or three berries in the top of the uppermost bough, four or five in the outmost fruitful branches thereof, saith the LORD God of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 7, E'At that day shall a man look to his Maker, and his eyes shall have respect to the Holy One of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 8, E'And he shall not look to the altars, the work of his hands, neither shall respect that which his fingers have made, either the groves, or the images.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 9, E'In that day shall his strong cities be as a forsaken bough, and an uppermost branch, which they left because of the children of Israel: and there shall be desolation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 10, E'Because thou hast forgotten the God of thy salvation, and hast not been mindful of the rock of thy strength, therefore shalt thou plant pleasant plants, and shalt set it with strange slips:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 11, E'In the day shalt thou make thy plant to grow, and in the morning shalt thou make thy seed to flourish: but the harvest shall be a heap in the day of grief and of desperate sorrow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 12, E'Woe to the multitude of many people, which make a noise like the noise of the seas; and to the rushing of nations, that make a rushing like the rushing of mighty waters!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 13, E'The nations shall rush like the rushing of many waters: but God shall rebuke them, and they shall flee far off, and shall be chased as the chaff of the mountains before the wind, and like a rolling thing before the whirlwind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 17, 14, E'And behold at eveningtide trouble; and before the morning he is not. This is the portion of them that spoil us, and the lot of them that rob us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 18, 1, E'Woe to the land shadowing with wings, which is beyond the rivers of Ethiopia:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 18, 2, E'That sendeth ambassadors by the sea, even in vessels of bulrushes upon the waters, saying, Go, ye swift messengers, to a nation scattered and peeled, to a people terrible from their beginning hitherto; a nation meted out and trodden down, whose land the rivers have spoiled!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 18, 3, E'All ye inhabitants of the world, and dwellers on the earth, see ye, when he lifteth up an ensign on the mountains; and when he bloweth a trumpet, hear ye.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 18, 4, E'For so the LORD said unto me, I will take my rest, and I will consider in my dwelling place like a clear heat upon herbs, and like a cloud of dew in the heat of harvest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 18, 5, E'For afore the harvest, when the bud is perfect, and the sour grape is ripening in the flower, he shall both cut off the sprigs with pruning hooks, and take away and cut down the branches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 18, 6, E'They shall be left together unto the fowls of the mountains, and to the beasts of the earth: and the fowls shall summer upon them, and all the beasts of the earth shall winter upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 18, 7, E'In that time shall the present be brought unto the LORD of hosts of a people scattered and peeled, and from a people terrible from their beginning hitherto; a nation meted out and trodden under foot, whose land the rivers have spoiled, to the place of the name of the LORD of hosts, the mount Zion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 1, E'The burden of Egypt. Behold, the LORD rideth upon a swift cloud, and shall come into Egypt: and the idols of Egypt shall be moved at his presence, and the heart of Egypt shall melt in the midst of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 2, E'And I will set the Egyptians against the Egyptians: and they shall fight every one against his brother, and every one against his neighbour; city against city, and kingdom against kingdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 3, E'And the spirit of Egypt shall fail in the midst thereof; and I will destroy the counsel thereof: and they shall seek to the idols, and to the charmers, and to them that have familiar spirits, and to the wizards.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 4, E'And the Egyptians will I give over into the hand of a cruel lord; and a fierce king shall rule over them, saith the Lord, the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 5, E'And the waters shall fail from the sea, and the river shall be wasted and dried up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 6, E'And they shall turn the rivers far away; and the brooks of defence shall be emptied and dried up: the reeds and flags shall wither.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 7, E'The paper reeds by the brooks, by the mouth of the brooks, and every thing sown by the brooks, shall wither, be driven away, and be no more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 8, E'The fishers also shall mourn, and all they that cast angle into the brooks shall lament, and they that spread nets upon the waters shall languish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 9, E'Moreover they that work in fine flax, and they that weave networks, shall be confounded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 10, E'And they shall be broken in the purposes thereof, all that make sluices and ponds for fish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 11, E'Surely the princes of Zoan are fools, the counsel of the wise counsellors of Pharaoh is become brutish: how say ye unto Pharaoh, I am the son of the wise, the son of ancient kings?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 12, E'Where are they? where are thy wise men? and let them tell thee now, and let them know what the LORD of hosts hath purposed upon Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 13, E'The princes of Zoan are become fools, the princes of Noph are deceived; they have also seduced Egypt, even they that are the stay of the tribes thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 14, E'The LORD hath mingled a perverse spirit in the midst thereof: and they have caused Egypt to err in every work thereof, as a drunken man staggereth in his vomit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 15, E'Neither shall there be any work for Egypt, which the head or tail, branch or rush, may do.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 16, E'In that day shall Egypt be like unto women: and it shall be afraid and fear because of the shaking of the hand of the LORD of hosts, which he shaketh over it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 17, E'And the land of Judah shall be a terror unto Egypt, every one that maketh mention thereof shall be afraid in himself, because of the counsel of the LORD of hosts, which he hath determined against it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 18, E'In that day shall five cities in the land of Egypt speak the language of Canaan, and swear to the LORD of hosts; one shall be called, The city of destruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 19, E'In that day shall there be an altar to the LORD in the midst of the land of Egypt, and a pillar at the border thereof to the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 20, E'And it shall be for a sign and for a witness unto the LORD of hosts in the land of Egypt: for they shall cry unto the LORD because of the oppressors, and he shall send them a saviour, and a great one, and he shall deliver them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 21, E'And the LORD shall be known to Egypt, and the Egyptians shall know the LORD in that day, and shall do sacrifice and oblation; yea, they shall vow a vow unto the LORD, and perform it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 22, E'And the LORD shall smite Egypt: he shall smite and heal it: and they shall return even to the LORD, and he shall be intreated of them, and shall heal them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 23, E'In that day shall there be a highway out of Egypt to Assyria, and the Assyrian shall come into Egypt, and the Egyptian into Assyria, and the Egyptians shall serve with the Assyrians.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 24, E'In that day shall Israel be the third with Egypt and with Assyria, even a blessing in the midst of the land:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 19, 25, E'Whom the LORD of hosts shall bless, saying, Blessed be Egypt my people, and Assyria the work of my hands, and Israel mine inheritance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 20, 1, E'In the year that Tartan came unto Ashdod, (when Sargon the king of Assyria sent him,) and fought against Ashdod, and took it;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 20, 2, E'At the same time spake the LORD by Isaiah the son of Amoz, saying, Go and loose the sackcloth from off thy loins, and put off thy shoe from thy foot. And he did so, walking naked and barefoot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 20, 3, E'And the LORD said, Like as my servant Isaiah hath walked naked and barefoot three years for a sign and wonder upon Egypt and upon Ethiopia;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 20, 4, E'So shall the king of Assyria lead away the Egyptians prisoners, and the Ethiopians captives, young and old, naked and barefoot, even with their buttocks uncovered, to the shame of Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 20, 5, E'And they shall be afraid and ashamed of Ethiopia their expectation, and of Egypt their glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 20, 6, E'And the inhabitant of this isle shall say in that day, Behold, such is our expectation, whither we flee for help to be delivered from the king of Assyria: and how shall we escape?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 1, E'The burden of the desert of the sea. As whirlwinds in the south pass through; so it cometh from the desert, from a terrible land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 2, E'A grievous vision is declared unto me; the treacherous dealer dealeth treacherously, and the spoiler spoileth. Go up, O Elam: besiege, O Media; all the sighing thereof have I made to cease.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 3, E'Therefore are my loins filled with pain: pangs have taken hold upon me, as the pangs of a woman that travaileth: I was bowed down at the hearing of it; I was dismayed at the seeing of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 4, E'My heart panted, fearfulness affrighted me: the night of my pleasure hath he turned into fear unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 5, E'Prepare the table, watch in the watchtower, eat, drink: arise, ye princes, and anoint the shield.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 6, E'For thus hath the LORD said unto me, Go, set a watchman, let him declare what he seeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 7, E'And he saw a chariot with a couple of horsemen, a chariot of asses, and a chariot of camels; and he hearkened diligently with much heed:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 8, E'And he cried, A lion: My lord, I stand continually upon the watchtower in the daytime, and I am set in my ward whole nights:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 9, E'And, behold, here cometh a chariot of men, with a couple of horsemen. And he answered and said, Babylon is fallen, is fallen; and all the graven images of her gods he hath broken unto the ground.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 10, E'O my threshing, and the corn of my floor: that which I have heard of the LORD of hosts, the God of Israel, have I declared unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 11, E'The burden of Dumah. He calleth to me out of Seir, Watchman, what of the night? Watchman, what of the night?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 12, E'The watchman said, The morning cometh, and also the night: if ye will enquire, enquire ye: return, come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 13, E'The burden upon Arabia. In the forest in Arabia shall ye lodge, O ye travelling companies of Dedanim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 14, E'The inhabitants of the land of Tema brought water to him that was thirsty, they prevented with their bread him that fled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 15, E'For they fled from the swords, from the drawn sword, and from the bent bow, and from the grievousness of war.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 16, E'For thus hath the LORD said unto me, Within a year, according to the years of an hireling, and all the glory of Kedar shall fail:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 21, 17, E'And the residue of the number of archers, the mighty men of the children of Kedar, shall be diminished: for the LORD God of Israel hath spoken it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 1, E'The burden of the valley of vision. What aileth thee now, that thou art wholly gone up to the housetops?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 2, E'Thou that art full of stirs, a tumultuous city, a joyous city: thy slain men are not slain with the sword, nor dead in battle.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Isaiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 3, E'All thy rulers are fled together, they are bound by the archers: all that are found in thee are bound together, which have fled from far.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 4, E'Therefore said I, Look away from me; I will weep bitterly, labour not to comfort me, because of the spoiling of the daughter of my people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 5, E'For it is a day of trouble, and of treading down, and of perplexity by the Lord GOD of hosts in the valley of vision, breaking down the walls, and of crying to the mountains.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 6, E'And Elam bare the quiver with chariots of men and horsemen, and Kir uncovered the shield.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 7, E'And it shall come to pass, that thy choicest valleys shall be full of chariots, and the horsemen shall set themselves in array at the gate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 8, E'And he discovered the covering of Judah, and thou didst look in that day to the armour of the house of the forest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 9, E'Ye have seen also the breaches of the city of David, that they are many: and ye gathered together the waters of the lower pool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 10, E'And ye have numbered the houses of Jerusalem, and the houses have ye broken down to fortify the wall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 11, E'Ye made also a ditch between the two walls for the water of the old pool: but ye have not looked unto the maker thereof, neither had respect unto him that fashioned it long ago.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 12, E'And in that day did the Lord GOD of hosts call to weeping, and to mourning, and to baldness, and to girding with sackcloth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 13, E'And behold joy and gladness, slaying oxen, and killing sheep, eating flesh, and drinking wine: let us eat and drink; for to morrow we shall die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 14, E'And it was revealed in mine ears by the LORD of hosts, Surely this iniquity shall not be purged from you till ye die, saith the Lord GOD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 15, E'Thus saith the Lord GOD of hosts, Go, get thee unto this treasurer, even unto Shebna, which is over the house, and say,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 16, E'What hast thou here? and whom hast thou here, that thou hast hewed thee out a sepulchre here, as he that heweth him out a sepulchre on high, and that graveth an habitation for himself in a rock?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 17, E'Behold, the LORD will carry thee away with a mighty captivity, and will surely cover thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 18, E'He will surely violently turn and toss thee like a ball into a large country: there shalt thou die, and there the chariots of thy glory shall be the shame of thy lordâ€™s house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 19, E'And I will drive thee from thy station, and from thy state shall he pull thee down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 20, E'And it shall come to pass in that day, that I will call my servant Eliakim the son of Hilkiah:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 21, E'And I will clothe him with thy robe, and strengthen him with thy girdle, and I will commit thy government into his hand: and he shall be a father to the inhabitants of Jerusalem, and to the house of Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 22, E'And the key of the house of David will I lay upon his shoulder; so he shall open, and none shall shut; and he shall shut, and none shall open.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 23, E'And I will fasten him as a nail in a sure place; and he shall be for a glorious throne to his fatherâ€™s house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 24, E'And they shall hang upon him all the glory of his fatherâ€™s house, the offspring and the issue, all vessels of small quantity, from the vessels of cups, even to all the vessels of flagons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 22, 25, E'In that day, saith the LORD of hosts, shall the nail that is fastened in the sure place be removed, and be cut down, and fall; and the burden that was upon it shall be cut off: for the LORD hath spoken it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 1, E'The burden of Tyre. Howl, ye ships of Tarshish; for it is laid waste, so that there is no house, no entering in: from the land of Chittim it is revealed to them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 2, E'Be still, ye inhabitants of the isle; thou whom the merchants of Zidon, that pass over the sea, have replenished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 3, E'And by great waters the seed of Sihor, the harvest of the river, is her revenue; and she is a mart of nations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 4, E'Be thou ashamed, O Zidon: for the sea hath spoken, even the strength of the sea, saying, I travail not, nor bring forth children, neither do I nourish up young men, nor bring up virgins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 5, E'As at the report concerning Egypt, so shall they be sorely pained at the report of Tyre.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 6, E'Pass ye over to Tarshish; howl, ye inhabitants of the isle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 7, E'Is this your joyous city, whose antiquity is of ancient days? her own feet shall carry her afar off to sojourn.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 8, E'Who hath taken this counsel against Tyre, the crowning city, whose merchants are princes, whose traffickers are the honourable of the earth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 9, E'The LORD of hosts hath purposed it, to stain the pride of all glory, and to bring into contempt all the honourable of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 10, E'Pass through thy land as a river, O daughter of Tarshish: there is no more strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 11, E'He stretched out his hand over the sea, he shook the kingdoms: the LORD hath given a commandment against the merchant city, to destroy the strong holds thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 12, E'And he said, Thou shalt no more rejoice, O thou oppressed virgin, daughter of Zidon: arise, pass over to Chittim; there also shalt thou have no rest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 13, E'Behold the land of the Chaldeans; this people was not, till the Assyrian founded it for them that dwell in the wilderness: they set up the towers thereof, they raised up the palaces thereof; and he brought it to ruin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 14, E'Howl, ye ships of Tarshish: for your strength is laid waste.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 15, E'And it shall come to pass in that day, that Tyre shall be forgotten seventy years, according to the days of one king: after the end of seventy years shall Tyre sing as an harlot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 16, E'Take an harp, go about the city, thou harlot that hast been forgotten; make sweet melody, sing many songs, that thou mayest be remembered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 17, E'And it shall come to pass after the end of seventy years, that the LORD will visit Tyre, and she shall turn to her hire, and shall commit fornication with all the kingdoms of the world upon the face of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 23, 18, E'And her merchandise and her hire shall be holiness to the LORD: it shall not be treasured nor laid up; for her merchandise shall be for them that dwell before the LORD, to eat sufficiently, and for durable clothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 1, E'Behold, the LORD maketh the earth empty, and maketh it waste, and turneth it upside down, and scattereth abroad the inhabitants thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 2, E'And it shall be, as with the people, so with the priest; as with the servant, so with his master; as with the maid, so with her mistress; as with the buyer, so with the seller; as with the lender, so with the borrower; as with the taker of usury, so with the giver of usury to him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 3, E'The land shall be utterly emptied, and utterly spoiled: for the LORD hath spoken this word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 4, E'The earth mourneth and fadeth away, the world languisheth and fadeth away, the haughty people of the earth do languish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 5, E'The earth also is defiled under the inhabitants thereof; because they have transgressed the laws, changed the ordinance, broken the everlasting covenant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 6, E'Therefore hath the curse devoured the earth, and they that dwell therein are desolate: therefore the inhabitants of the earth are burned, and few men left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 7, E'The new wine mourneth, the vine languisheth, all the merryhearted do sigh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 8, E'The mirth of tabrets ceaseth, the noise of them that rejoice endeth, the joy of the harp ceaseth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 9, E'They shall not drink wine with a song; strong drink shall be bitter to them that drink it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 10, E'The city of confusion is broken down: every house is shut up, that no man may come in.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 11, E'There is a crying for wine in the streets; all joy is darkened, the mirth of the land is gone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 12, E'In the city is left desolation, and the gate is smitten with destruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 13, E'When thus it shall be in the midst of the land among the people, there shall be as the shaking of an olive tree, and as the gleaning grapes when the vintage is done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 14, E'They shall lift up their voice, they shall sing for the majesty of the LORD, they shall cry aloud from the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 15, E'Wherefore glorify ye the LORD in the fires, even the name of the LORD God of Israel in the isles of the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 16, E'From the uttermost part of the earth have we heard songs, even glory to the righteous. But I said, My leanness, my leanness, woe unto me! the treacherous dealers have dealt treacherously; yea, the treacherous dealers have dealt very treacherously.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 17, E'Fear, and the pit, and the snare, are upon thee, O inhabitant of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 18, E'And it shall come to pass, that he who fleeth from the noise of the fear shall fall into the pit; and he that cometh up out of the midst of the pit shall be taken in the snare: for the windows from on high are open, and the foundations of the earth do shake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 19, E'The earth is utterly broken down, the earth is clean dissolved, the earth is moved exceedingly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 20, E'The earth shall reel to and fro like a drunkard, and shall be removed like a cottage; and the transgression thereof shall be heavy upon it; and it shall fall, and not rise again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 21, E'And it shall come to pass in that day, that the LORD shall punish the host of the high ones that are on high, and the kings of the earth upon the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 22, E'And they shall be gathered together, as prisoners are gathered in the pit, and shall be shut up in the prison, and after many days shall they be visited.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 24, 23, E'Then the moon shall be confounded, and the sun ashamed, when the LORD of hosts shall reign in mount Zion, and in Jerusalem, and before his ancients gloriously.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 25, 1, E'O Lord, thou art my God; I will exalt thee, I will praise thy name; for thou hast done wonderful things; thy counsels of old are faithfulness and truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 25, 2, E'For thou hast made of a city an heap; of a defenced city a ruin: a palace of strangers to be no city; it shall never be built.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 25, 3, E'Therefore shall the strong people glorify thee, the city of the terrible nations shall fear thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 25, 4, E'For thou hast been a strength to the poor, a strength to the needy in his distress, a refuge from the storm, a shadow from the heat, when the blast of the terrible ones is as a storm against the wall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 25, 5, E'Thou shalt bring down the noise of strangers, as the heat in a dry place; even the heat with the shadow of a cloud: the branch of the terrible ones shall be brought low.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 25, 6, E'And in this mountain shall the LORD of hosts make unto all people a feast of fat things, a feast of wines on the lees, of fat things full of marrow, of wines on the lees well refined.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 25, 7, E'And he will destroy in this mountain the face of the covering cast over all people, and the vail that is spread over all nations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 25, 8, E'He will swallow up death in victory; and the Lord GOD will wipe away tears from off all faces; and the rebuke of his people shall he take away from off all the earth: for the LORD hath spoken it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 25, 9, E'And it shall be said in that day, Lo, this is our God; we have waited for him, and he will save us: this is the LORD; we have waited for him, we will be glad and rejoice in his salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 25, 10, E'For in this mountain shall the hand of the LORD rest, and Moab shall be trodden down under him, even as straw is trodden down for the dunghill.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 25, 11, E'And he shall spread forth his hands in the midst of them, as he that swimmeth spreadeth forth his hands to swim: and he shall bring down their pride together with the spoils of their hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 25, 12, E'And the fortress of the high fort of thy walls shall he bring down, lay low, and bring to the ground, even to the dust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 1, E'In that day shall this song be sung in the land of Judah; We have a strong city; salvation will God appoint for walls and bulwarks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 2, E'Open ye the gates, that the righteous nation which keepeth the truth may enter in.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 3, E'Thou wilt keep him in perfect peace, whose mind is stayed on thee: because he trusteth in thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 4, E'Trust ye in the LORD for ever: for in the LORD JEHOVAH is everlasting strength:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 5, E'For he bringeth down them that dwell on high; the lofty city, he layeth it low; he layeth it low, even to the ground; he bringeth it even to the dust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 6, E'The foot shall tread it down, even the feet of the poor, and the steps of the needy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 7, E'The way of the just is uprightness: thou, most upright, dost weigh the path of the just.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 8, E'Yea, in the way of thy judgments, O LORD, have we waited for thee; the desire of our soul is to thy name, and to the remembrance of thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 9, E'With my soul have I desired thee in the night; yea, with my spirit within me will I seek thee early: for when thy judgments are in the earth, the inhabitants of the world will learn righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 10, E'Let favour be shewed to the wicked, yet will he not learn righteousness: in the land of uprightness will he deal unjustly, and will not behold the majesty of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 11, E'LORD, when thy hand is lifted up, they will not see: but they shall see, and be ashamed for their envy at the people; yea, the fire of thine enemies shall devour them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 12, E'LORD, thou wilt ordain peace for us: for thou also hast wrought all our works in us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 13, E'O LORD our God, other lords beside thee have had dominion over us: but by thee only will we make mention of thy name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 14, E'They are dead, they shall not live; they are deceased, they shall not rise: therefore hast thou visited and destroyed them, and made all their memory to perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 15, E'Thou hast increased the nation, O LORD, thou hast increased the nation: thou art glorified: thou hadst removed it far unto all the ends of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 16, E'LORD, in trouble have they visited thee, they poured out a prayer when thy chastening was upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 17, E'Like as a woman with child, that draweth near the time of her delivery, is in pain, and crieth out in her pangs; so have we been in thy sight, O LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 18, E'We have been with child, we have been in pain, we have as it were brought forth wind; we have not wrought any deliverance in the earth; neither have the inhabitants of the world fallen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 19, E'Thy dead men shall live, together with my dead body shall they arise. Awake and sing, ye that dwell in dust: for thy dew is as the dew of herbs, and the earth shall cast out the dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 20, E'Come, my people, enter thou into thy chambers, and shut thy doors about thee: hide thyself as it were for a little moment, until the indignation be overpast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 26, 21, E'For, behold, the LORD cometh out of his place to punish the inhabitants of the earth for their iniquity: the earth also shall disclose her blood, and shall no more cover her slain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 1, E'In that day the LORD with his sore and great and strong sword shall punish leviathan the piercing serpent, even leviathan that crooked serpent; and he shall slay the dragon that is in the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 2, E'In that day sing ye unto her, A vineyard of red wine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 3, E'I the LORD do keep it; I will water it every moment: lest any hurt it, I will keep it night and day.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Isaiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 4, E'Fury is not in me: who would set the briers and thorns against me in battle? I would go through them, I would burn them together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 5, E'Or let him take hold of my strength, that he may make peace with me; and he shall make peace with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 6, E'He shall cause them that come of Jacob to take root: Israel shall blossom and bud, and fill the face of the world with fruit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 7, E'Hath he smitten him, as he smote those that smote him? or is he slain according to the slaughter of them that are slain by him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 8, E'In measure, when it shooteth forth, thou wilt debate with it: he stayeth his rough wind in the day of the east wind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 9, E'By this therefore shall the iniquity of Jacob be purged; and this is all the fruit to take away his sin; when he maketh all the stones of the altar as chalkstones that are beaten in sunder, the groves and images shall not stand up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 10, E'Yet the defenced city shall be desolate, and the habitation forsaken, and left like a wilderness: there shall the calf feed, and there shall he lie down, and consume the branches thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 11, E'When the boughs thereof are withered, they shall be broken off: the women come, and set them on fire: for it is a people of no understanding: therefore he that made them will not have mercy on them, and he that formed them will shew them no favour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 12, E'And it shall come to pass in that day, that the LORD shall beat off from the channel of the river unto the stream of Egypt, and ye shall be gathered one by one, O ye children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 27, 13, E'And it shall come to pass in that day, that the great trumpet shall be blown, and they shall come which were ready to perish in the land of Assyria, and the outcasts in the land of Egypt, and shall worship the LORD in the holy mount at Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 1, E'Woe to the crown of pride, to the drunkards of Ephraim, whose glorious beauty is a fading flower, which are on the head of the fat valleys of them that are overcome with wine!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 2, E'Behold, the Lord hath a mighty and strong one, which as a tempest of hail and a destroying storm, as a flood of mighty waters overflowing, shall cast down to the earth with the hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 3, E'The crown of pride, the drunkards of Ephraim, shall be trodden under feet:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 4, E'And the glorious beauty, which is on the head of the fat valley, shall be a fading flower, and as the hasty fruit before the summer; which when he that looketh upon it seeth, while it is yet in his hand he eateth it up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 5, E'In that day shall the LORD of hosts be for a crown of glory, and for a diadem of beauty, unto the residue of his people,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 6, E'And for a spirit of judgment to him that sitteth in judgment, and for strength to them that turn the battle to the gate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 7, E'But they also have erred through wine, and through strong drink are out of the way; the priest and the prophet have erred through strong drink, they are swallowed up of wine, they are out of the way through strong drink; they err in vision, they stumble in judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 8, E'For all tables are full of vomit and filthiness, so that there is no place clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 9, E'Whom shall he teach knowledge? and whom shall he make to understand doctrine? them that are weaned from the milk, and drawn from the breasts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 10, E'For precept must be upon precept, precept upon precept; line upon line, line upon line; here a little, and there a little:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 11, E'For with stammering lips and another tongue will he speak to this people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 12, E'To whom he said, This is the rest wherewith ye may cause the weary to rest; and this is the refreshing: yet they would not hear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 13, E'But the word of the LORD was unto them precept upon precept, precept upon precept; line upon line, line upon line; here a little, and there a little; that they might go, and fall backward, and be broken, and snared, and taken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 14, E'Wherefore hear the word of the LORD, ye scornful men, that rule this people which is in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 15, E'Because ye have said, We have made a covenant with death, and with hell are we at agreement; when the overflowing scourge shall pass through, it shall not come unto us: for we have made lies our refuge, and under falsehood have we hid ourselves:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 16, E'Therefore thus saith the Lord GOD, Behold, I lay in Zion for a foundation a stone, a tried stone, a precious corner stone, a sure foundation: he that believeth shall not make haste.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 17, E'Judgment also will I lay to the line, and righteousness to the plummet: and the hail shall sweep away the refuge of lies, and the waters shall overflow the hiding place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 18, E'And your covenant with death shall be disannulled, and your agreement with hell shall not stand; when the overflowing scourge shall pass through, then ye shall be trodden down by it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 19, E'From the time that it goeth forth it shall take you: for morning by morning shall it pass over, by day and by night: and it shall be a vexation only to understand the report.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 20, E'For the bed is shorter than that a man can stretch himself on it: and the covering narrower than that he can wrap himself in it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 21, E'For the LORD shall rise up as in mount Perazim, he shall be wroth as in the valley of Gibeon, that he may do his work, his strange work; and bring to pass his act, his strange act.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 22, E'Now therefore be ye not mockers, lest your bands be made strong: for I have heard from the Lord GOD of hosts a consumption, even determined upon the whole earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 23, E'Give ye ear, and hear my voice; hearken, and hear my speech.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 24, E'Doth the plowman plow all day to sow? doth he open and break the clods of his ground?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 25, E'When he hath made plain the face thereof, doth he not cast abroad the fitches, and scatter the cummin, and cast in the principal wheat and the appointed barley and the rie in their place?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 26, E'For his God doth instruct him to discretion, and doth teach him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 27, E'For the fitches are not threshed with a threshing instrument, neither is a cart wheel turned about upon the cummin; but the fitches are beaten out with a staff, and the cummin with a rod.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 28, E'Bread corn is bruised; because he will not ever be threshing it, nor break it with the wheel of his cart, nor bruise it with his horsemen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 28, 29, E'This also cometh forth from the LORD of hosts, which is wonderful in counsel, and excellent in working.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 1, E'Woe to Ariel, to Ariel, the city where David dwelt! add ye year to year; let them kill sacrifices.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 2, E'Yet I will distress Ariel, and there shall be heaviness and sorrow: and it shall be unto me as Ariel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 3, E'And I will camp against thee round about, and will lay siege against thee with a mount, and I will raise forts against thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 4, E'And thou shalt be brought down, and shalt speak out of the ground, and thy speech shall be low out of the dust, and thy voice shall be, as of one that hath a familiar spirit, out of the ground, and thy speech shall whisper out of the dust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 5, E'Moreover the multitude of thy strangers shall be like small dust, and the multitude of the terrible ones shall be as chaff that passeth away: yea, it shall be at an instant suddenly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 6, E'Thou shalt be visited of the LORD of hosts with thunder, and with earthquake, and great noise, with storm and tempest, and the flame of devouring fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 7, E'And the multitude of all the nations that fight against Ariel, even all that fight against her and her munition, and that distress her, shall be as a dream of a night vision.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 8, E'It shall even be as when an hungry man dreameth, and, behold, he eateth; but he awaketh, and his soul is empty: or as when a thirsty man dreameth, and, behold, he drinketh; but he awaketh, and, behold, he is faint, and his soul hath appetite: so shall the multitude of all the nations be, that fight against mount Zion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 9, E'Stay yourselves, and wonder; cry ye out, and cry: they are drunken, but not with wine; they stagger, but not with strong drink.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 10, E'For the LORD hath poured out upon you the spirit of deep sleep, and hath closed your eyes: the prophets and your rulers, the seers hath he covered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 11, E'And the vision of all is become unto you as the words of a book that is sealed, which men deliver to one that is learned, saying, Read this, I pray thee: and he saith, I cannot; for it is sealed:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 12, E'And the book is delivered to him that is not learned, saying, Read this, I pray thee: and he saith, I am not learned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 13, E'Wherefore the Lord said, Forasmuch as this people draw near me with their mouth, and with their lips do honour me, but have removed their heart far from me, and their fear toward me is taught by the precept of men:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 14, E'Therefore, behold, I will proceed to do a marvellous work among this people, even a marvellous work and a wonder: for the wisdom of their wise men shall perish, and the understanding of their prudent men shall be hid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 15, E'Woe unto them that seek deep to hide their counsel from the LORD, and their works are in the dark, and they say, Who seeth us? and who knoweth us?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 16, E'Surely your turning of things upside down shall be esteemed as the potterâ€™s clay: for shall the work say of him that made it, He made me not? or shall the thing framed say of him that framed it, He had no understanding?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 17, E'Is it not yet a very little while, and Lebanon shall be turned into a fruitful field, and the fruitful field shall be esteemed as a forest?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 18, E'And in that day shall the deaf hear the words of the book, and the eyes of the blind shall see out of obscurity, and out of darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 19, E'The meek also shall increase their joy in the LORD, and the poor among men shall rejoice in the Holy One of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 20, E'For the terrible one is brought to nought, and the scorner is consumed, and all that watch for iniquity are cut off:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 21, E'That make a man an offender for a word, and lay a snare for him that reproveth in the gate, and turn aside the just for a thing of nought.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 22, E'Therefore thus saith the LORD, who redeemed Abraham, concerning the house of Jacob, Jacob shall not now be ashamed, neither shall his face now wax pale.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 23, E'But when he seeth his children, the work of mine hands, in the midst of him, they shall sanctify my name, and sanctify the Holy One of Jacob, and shall fear the God of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 29, 24, E'They also that erred in spirit shall come to understanding, and they that murmured shall learn doctrine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 1, E'Woe to the rebellious children, saith the LORD, that take counsel, but not of me; and that cover with a covering, but not of my spirit, that they may add sin to sin:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 2, E'That walk to go down into Egypt, and have not asked at my mouth; to strengthen themselves in the strength of Pharaoh, and to trust in the shadow of Egypt!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 3, E'Therefore shall the strength of Pharaoh be your shame, and the trust in the shadow of Egypt your confusion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 4, E'For his princes were at Zoan, and his ambassadors came to Hanes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 5, E'They were all ashamed of a people that could not profit them, nor be an help nor profit, but a shame, and also a reproach.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 6, E'The burden of the beasts of the south: into the land of trouble and anguish, from whence come the young and old lion, the viper and fiery flying serpent, they will carry their riches upon the shoulders of young asses, and their treasures upon the bunches of camels, to a people that shall not profit them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 7, E'For the Egyptians shall help in vain, and to no purpose: therefore have I cried concerning this, Their strength is to sit still.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 8, E'Now go, write it before them in a table, and note it in a book, that it may be for the time to come for ever and ever:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 9, E'That this is a rebellious people, lying children, children that will not hear the law of the LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 10, E'Which say to the seers, See not; and to the prophets, Prophesy not unto us right things, speak unto us smooth things, prophesy deceits:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 11, E'Get you out of the way, turn aside out of the path, cause the Holy One of Israel to cease from before us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 12, E'Wherefore thus saith the Holy One of Israel, Because ye despise this word, and trust in oppression and perverseness, and stay thereon:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 13, E'Therefore this iniquity shall be to you as a breach ready to fall, swelling out in a high wall, whose breaking cometh suddenly at an instant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 14, E'And he shall break it as the breaking of the pottersâ€™ vessel that is broken in pieces; he shall not spare: so that there shall not be found in the bursting of it a sherd to take fire from the hearth, or to take water withal out of the pit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 15, E'For thus saith the Lord GOD, the Holy One of Israel; In returning and rest shall ye be saved; in quietness and in confidence shall be your strength: and ye would not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 16, E'But ye said, No; for we will flee upon horses; therefore shall ye flee: and, We will ride upon the swift; therefore shall they that pursue you be swift.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 17, E'One thousand shall flee at the rebuke of one; at the rebuke of five shall ye flee: till ye be left as a beacon upon the top of a mountain, and as an ensign on an hill.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 18, E'And therefore will the LORD wait, that he may be gracious unto you, and therefore will he be exalted, that he may have mercy upon you: for the LORD is a God of judgment: blessed are all they that wait for him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 19, E'For the people shall dwell in Zion at Jerusalem: thou shalt weep no more: he will be very gracious unto thee at the voice of thy cry; when he shall hear it, he will answer thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 20, E'And though the Lord give you the bread of adversity, and the water of affliction, yet shall not thy teachers be removed into a corner any more, but thine eyes shall see thy teachers:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 21, E'And thine ears shall hear a word behind thee, saying, This is the way, walk ye in it, when ye turn to the right hand, and when ye turn to the left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 22, E'Ye shall defile also the covering of thy graven images of silver, and the ornament of thy molten images of gold: thou shalt cast them away as a menstruous cloth; thou shalt say unto it, Get thee hence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 23, E'Then shall he give the rain of thy seed, that thou shalt sow the ground withal; and bread of the increase of the earth, and it shall be fat and plenteous: in that day shall thy cattle feed in large pastures.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 24, E'The oxen likewise and the young asses that ear the ground shall eat clean provender, which hath been winnowed with the shovel and with the fan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 25, E'And there shall be upon every high mountain, and upon every high hill, rivers and streams of waters in the day of the great slaughter, when the towers fall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 26, E'Moreover the light of the moon shall be as the light of the sun, and the light of the sun shall be sevenfold, as the light of seven days, in the day that the LORD bindeth up the breach of his people, and healeth the stroke of their wound.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 27, E'Behold, the name of the LORD cometh from far, burning with his anger, and the burden thereof is heavy: his lips are full of indignation, and his tongue as a devouring fire:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 28, E'And his breath, as an overflowing stream, shall reach to the midst of the neck, to sift the nations with the sieve of vanity: and there shall be a bridle in the jaws of the people, causing them to err.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 29, E'Ye shall have a song, as in the night when a holy solemnity is kept; and gladness of heart, as when one goeth with a pipe to come into the mountain of the LORD, to the mighty One of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 30, E'And the LORD shall cause his glorious voice to be heard, and shall shew the lighting down of his arm, with the indignation of his anger, and with the flame of a devouring fire, with scattering, and tempest, and hailstones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 31, E'For through the voice of the LORD shall the Assyrian be beaten down, which smote with a rod.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 32, E'And in every place where the grounded staff shall pass, which the LORD shall lay upon him, it shall be with tabrets and harps: and in battles of shaking will he fight with it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 30, 33, E'For Tophet is ordained of old; yea, for the king it is prepared; he hath made it deep and large: the pile thereof is fire and much wood; the breath of the LORD, like a stream of brimstone, doth kindle it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 31, 1, E'Woe to them that go down to Egypt for help; and stay on horses, and trust in chariots, because they are many; and in horsemen, because they are very strong; but they look not unto the Holy One of Israel, neither seek the LORD!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 31, 2, E'Yet he also is wise, and will bring evil, and will not call back his words: but will arise against the house of the evildoers, and against the help of them that work iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 31, 3, E'Now the Egyptians are men, and not God; and their horses flesh, and not spirit. When the LORD shall stretch out his hand, both he that helpeth shall fall, and he that is holpen shall fall down, and they all shall fail together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 31, 4, E'For thus hath the LORD spoken unto me, Like as the lion and the young lion roaring on his prey, when a multitude of shepherds is called forth against him, he will not be afraid of their voice, nor abase himself for the noise of them: so shall the LORD of hosts come down to fight for mount Zion, and for the hill thereof.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Isaiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 31, 5, E'As birds flying, so will the LORD of hosts defend Jerusalem; defending also he will deliver it; and passing over he will preserve it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 31, 6, E'Turn ye unto him from whom the children of Israel have deeply revolted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 31, 7, E'For in that day every man shall cast away his idols of silver, and his idols of gold, which your own hands have made unto you for a sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 31, 8, E'Then shall the Assyrian fall with the sword, not of a mighty man; and the sword, not of a mean man, shall devour him: but he shall flee from the sword, and his young men shall be discomfited.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 31, 9, E'And he shall pass over to his strong hold for fear, and his princes shall be afraid of the ensign, saith the LORD, whose fire is in Zion, and his furnace in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 1, E'Behold, a king shall reign in righteousness, and princes shall rule in judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 2, E'And a man shall be as an hiding place from the wind, and a covert from the tempest; as rivers of water in a dry place, as the shadow of a great rock in a weary land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 3, E'And the eyes of them that see shall not be dim, and the ears of them that hear shall hearken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 4, E'The heart also of the rash shall understand knowledge, and the tongue of the stammerers shall be ready to speak plainly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 5, E'The vile person shall be no more called liberal, nor the churl said to be bountiful.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 6, E'For the vile person will speak villany, and his heart will work iniquity, to practise hypocrisy, and to utter error against the LORD, to make empty the soul of the hungry, and he will cause the drink of the thirsty to fail.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 7, E'The instruments also of the churl are evil: he deviseth wicked devices to destroy the poor with lying words, even when the needy speaketh right.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 8, E'But the liberal deviseth liberal things; and by liberal things shall he stand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 9, E'Rise up, ye women that are at ease; hear my voice, ye careless daughters; give ear unto my speech.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 10, E'Many days and years shall ye be troubled, ye careless women: for the vintage shall fail, the gathering shall not come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 11, E'Tremble, ye women that are at ease; be troubled, ye careless ones: strip you, and make you bare, and gird sackcloth upon your loins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 12, E'They shall lament for the teats, for the pleasant fields, for the fruitful vine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 13, E'Upon the land of my people shall come up thorns and briers; yea, upon all the houses of joy in the joyous city:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 14, E'Because the palaces shall be forsaken; the multitude of the city shall be left; the forts and towers shall be for dens for ever, a joy of wild asses, a pasture of flocks;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 15, E'Until the spirit be poured upon us from on high, and the wilderness be a fruitful field, and the fruitful field be counted for a forest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 16, E'Then judgment shall dwell in the wilderness, and righteousness remain in the fruitful field.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 17, E'And the work of righteousness shall be peace; and the effect of righteousness quietness and assurance for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 18, E'And my people shall dwell in a peaceable habitation, and in sure dwellings, and in quiet resting places;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 19, E'When it shall hail, coming down on the forest; and the city shall be low in a low place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 32, 20, E'Blessed are ye that sow beside all waters, that send forth thither the feet of the ox and the ass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 1, E'Woe to thee that spoilest, and thou wast not spoiled; and dealest treacherously, and they dealt not treacherously with thee! when thou shalt cease to spoil, thou shalt be spoiled; and when thou shalt make an end to deal treacherously, they shall deal treacherously with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 2, E'O LORD, be gracious unto us; we have waited for thee: be thou their arm every morning, our salvation also in the time of trouble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 3, E'At the noise of the tumult the people fled; at the lifting up of thyself the nations were scattered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 4, E'And your spoil shall be gathered like the gathering of the caterpiller: as the running to and fro of locusts shall he run upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 5, E'The LORD is exalted; for he dwelleth on high: he hath filled Zion with judgment and righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 6, E'And wisdom and knowledge shall be the stability of thy times, and strength of salvation: the fear of the LORD is his treasure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 7, E'Behold, their valiant ones shall cry without: the ambassadors of peace shall weep bitterly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 8, E'The highways lie waste, the wayfaring man ceaseth: he hath broken the covenant, he hath despised the cities, he regardeth no man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 9, E'The earth mourneth and languisheth: Lebanon is ashamed and hewn down: Sharon is like a wilderness; and Bashan and Carmel shake off their fruits.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 10, E'Now will I rise, saith the LORD; now will I be exalted; now will I lift up myself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 11, E'Ye shall conceive chaff, ye shall bring forth stubble: your breath, as fire, shall devour you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 12, E'And the people shall be as the burnings of lime: as thorns cut up shall they be burned in the fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 13, E'Hear, ye that are far off, what I have done; and, ye that are near, acknowledge my might.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 14, E'The sinners in Zion are afraid; fearfulness hath surprised the hypocrites. Who among us shall dwell with the devouring fire? who among us shall dwell with everlasting burnings?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 15, E'He that walketh righteously, and speaketh uprightly; he that despiseth the gain of oppressions, that shaketh his hands from holding of bribes, that stoppeth his ears from hearing of blood, and shutteth his eyes from seeing evil;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 16, E'He shall dwell on high: his place of defence shall be the munitions of rocks: bread shall be given him; his waters shall be sure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 17, E'Thine eyes shall see the king in his beauty: they shall behold the land that is very far off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 18, E'Thine heart shall meditate terror. Where is the scribe? where is the receiver? where is he that counted the towers?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 19, E'Thou shalt not see a fierce people, a people of a deeper speech than thou canst perceive; of a stammering tongue, that thou canst not understand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 20, E'Look upon Zion, the city of our solemnities: thine eyes shall see Jerusalem a quiet habitation, a tabernacle that shall not be taken down; not one of the stakes thereof shall ever be removed, neither shall any of the cords thereof be broken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 21, E'But there the glorious LORD will be unto us a place of broad rivers and streams; wherein shall go no galley with oars, neither shall gallant ship pass thereby.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 22, E'For the LORD is our judge, the LORD is our lawgiver, the LORD is our king; he will save us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 23, E'Thy tacklings are loosed; they could not well strengthen their mast, they could not spread the sail: then is the prey of a great spoil divided; the lame take the prey.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 33, 24, E'And the inhabitant shall not say, I am sick: the people that dwell therein shall be forgiven their iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 1, E'Come near, ye nations, to hear; and hearken, ye people: let the earth hear, and all that is therein; the world, and all things that come forth of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 2, E'For the indignation of the LORD is upon all nations, and his fury upon all their armies: he hath utterly destroyed them, he hath delivered them to the slaughter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 3, E'Their slain also shall be cast out, and their stink shall come up out of their carcases, and the mountains shall be melted with their blood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 4, E'And all the host of heaven shall be dissolved, and the heavens shall be rolled together as a scroll: and all their host shall fall down, as the leaf falleth off from the vine, and as a falling fig from the fig tree.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 5, E'For my sword shall be bathed in heaven: behold, it shall come down upon Idumea, and upon the people of my curse, to judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 6, E'The sword of the LORD is filled with blood, it is made fat with fatness, and with the blood of lambs and goats, with the fat of the kidneys of rams: for the LORD hath a sacrifice in Bozrah, and a great slaughter in the land of Idumea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 7, E'And the unicorns shall come down with them, and the bullocks with the bulls; and their land shall be soaked with blood, and their dust made fat with fatness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 8, E'For it is the day of the LORDâ€™s vengeance, and the year of recompences for the controversy of Zion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 9, E'And the streams thereof shall be turned into pitch, and the dust thereof into brimstone, and the land thereof shall become burning pitch.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 10, E'It shall not be quenched night nor day; the smoke thereof shall go up for ever: from generation to generation it shall lie waste; none shall pass through it for ever and ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 11, E'But the cormorant and the bittern shall possess it; the owl also and the raven shall dwell in it: and he shall stretch out upon it the line of confusion, and the stones of emptiness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 12, E'They shall call the nobles thereof to the kingdom, but none shall be there, and all her princes shall be nothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 13, E'And thorns shall come up in her palaces, nettles and brambles in the fortresses thereof: and it shall be an habitation of dragons, and a court for owls.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 14, E'The wild beasts of the desert shall also meet with the wild beasts of the island, and the satyr shall cry to his fellow; the screech owl also shall rest there, and find for herself a place of rest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 15, E'There shall the great owl make her nest, and lay, and hatch, and gather under her shadow: there shall the vultures also be gathered, every one with her mate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 16, E'Seek ye out of the book of the LORD, and read: no one of these shall fail, none shall want her mate: for my mouth it hath commanded, and his spirit it hath gathered them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 34, 17, E'And he hath cast the lot for them, and his hand hath divided it unto them by line: they shall possess it for ever, from generation to generation shall they dwell therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 35, 1, E'The wilderness and the solitary place shall be glad for them; and the desert shall rejoice, and blossom as the rose.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 35, 2, E'It shall blossom abundantly, and rejoice even with joy and singing: the glory of Lebanon shall be given unto it, the excellency of Carmel and Sharon, they shall see the glory of the LORD, and the excellency of our God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 35, 3, E'Strengthen ye the weak hands, and confirm the feeble knees.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 35, 4, E'Say to them that are of a fearful heart, Be strong, fear not: behold, your God will come with vengeance, even God with a recompence; he will come and save you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 35, 5, E'Then the eyes of the blind shall be opened, and the ears of the deaf shall be unstopped.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 35, 6, E'Then shall the lame man leap as an hart, and the tongue of the dumb sing: for in the wilderness shall waters break out, and streams in the desert.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 35, 7, E'And the parched ground shall become a pool, and the thirsty land springs of water: in the habitation of dragons, where each lay, shall be grass with reeds and rushes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 35, 8, E'And an highway shall be there, and a way, and it shall be called The way of holiness; the unclean shall not pass over it; but it shall be for those: the wayfaring men, though fools, shall not err therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 35, 9, E'No lion shall be there, nor any ravenous beast shall go up thereon, it shall not be found there; but the redeemed shall walk there:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 35, 10, E'And the ransomed of the LORD shall return, and come to Zion with songs and everlasting joy upon their heads: they shall obtain joy and gladness, and sorrow and sighing shall flee away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 1, E'Now it came to pass in the fourteenth year of king Hezekiah, that Sennacherib king of Assyria came up against all the defenced cities of Judah, and took them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 2, E'And the king of Assyria sent Rabshakeh from Lachish to Jerusalem unto king Hezekiah with a great army. And he stood by the conduit of the upper pool in the highway of the fullerâ€™s field.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 3, E'Then came forth unto him Eliakim, Hilkiahâ€™s son, which was over the house, and Shebna the scribe, and Joah, Asaphâ€™s son, the recorder.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 4, E'And Rabshakeh said unto them, Say ye now to Hezekiah, Thus saith the great king, the king of Assyria, What confidence is this wherein thou trustest?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 5, E'I say, sayest thou, (but they are but vain words) I have counsel and strength for war: now on whom dost thou trust, that thou rebellest against me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 6, E'Lo, thou trustest in the staff of this broken reed, on Egypt; whereon if a man lean, it will go into his hand, and pierce it: so is Pharaoh king of Egypt to all that trust in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 7, E'But if thou say to me, We trust in the LORD our God: is it not he, whose high places and whose altars Hezekiah hath taken away, and said to Judah and to Jerusalem, Ye shall worship before this altar?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 8, E'Now therefore give pledges, I pray thee, to my master the king of Assyria, and I will give thee two thousand horses, if thou be able on thy part to set riders upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 9, E'How then wilt thou turn away the face of one captain of the least of my masterâ€™s servants, and put thy trust on Egypt for chariots and for horsemen?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 10, E'And am I now come up without the LORD against this land to destroy it? the LORD said unto me, Go up against this land, and destroy it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 11, E'Then said Eliakim and Shebna and Joah unto Rabshakeh, Speak, I pray thee, unto thy servants in the Syrian language; for we understand it: and speak not to us in the Jewsâ€™ language, in the ears of the people that are on the wall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 12, E'But Rabshakeh said, Hath my master sent me to thy master and to thee to speak these words? hath he not sent me to the men that sit upon the wall, that they may eat their own dung, and drink their own piss with you?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 13, E'Then Rabshakeh stood, and cried with a loud voice in the Jewsâ€™ language, and said, Hear ye the words of the great king, the king of Assyria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 14, E'Thus saith the king, Let not Hezekiah deceive you: for he shall not be able to deliver you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 15, E'Neither let Hezekiah make you trust in the LORD, saying, The LORD will surely deliver us: this city shall not be delivered into the hand of the king of Assyria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 16, E'Hearken not to Hezekiah: for thus saith the king of Assyria, Make an agreement with me by a present, and come out to me: and eat ye every one of his vine, and every one of his fig tree, and drink ye every one the waters of his own cistern;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 17, E'Until I come and take you away to a land like your own land, a land of corn and wine, a land of bread and vineyards.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 18, E'Beware lest Hezekiah persuade you, saying, The LORD will deliver us. Hath any of the gods of the nations delivered his land out of the hand of the king of Assyria?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 19, E'Where are the gods of Hamath and Arphad? where are the gods of Sepharvaim? and have they delivered Samaria out of my hand?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 20, E'Who are they among all the gods of these lands, that have delivered their land out of my hand, that the LORD should deliver Jerusalem out of my hand?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 21, E'But they held their peace, and answered him not a word: for the kingâ€™s commandment was, saying, Answer him not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 36, 22, E'Then came Eliakim, the son of Hilkiah, that was over the household, and Shebna the scribe, and Joah, the son of Asaph, the recorder, to Hezekiah with their clothes rent, and told him the words of Rabshakeh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 1, E'And it came to pass, when king Hezekiah heard it, that he rent his clothes, and covered himself with sackcloth, and went into the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 2, E'And he sent Eliakim, who was over the household, and Shebna the scribe, and the elders of the priests covered with sackcloth, unto Isaiah the prophet the son of Amoz.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Isaiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 3, E'And they said unto him, Thus saith Hezekiah, This day is a day of trouble, and of rebuke, and of blasphemy: for the children are come to the birth, and there is not strength to bring forth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 4, E'It may be the LORD thy God will hear the words of Rabshakeh, whom the king of Assyria his master hath sent to reproach the living God, and will reprove the words which the LORD thy God hath heard: wherefore lift up thy prayer for the remnant that is left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 5, E'So the servants of king Hezekiah came to Isaiah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 6, E'And Isaiah said unto them, Thus shall ye say unto your master, Thus saith the LORD, Be not afraid of the words that thou hast heard, wherewith the servants of the king of Assyria have blasphemed me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 7, E'Behold, I will send a blast upon him, and he shall hear a rumour, and return to his own land; and I will cause him to fall by the sword in his own land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 8, E'So Rabshakeh returned, and found the king of Assyria warring against Libnah: for he had heard that he was departed from Lachish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 9, E'And he heard say concerning Tirhakah king of Ethiopia, He is come forth to make war with thee. And when he heard it, he sent messengers to Hezekiah, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 10, E'Thus shall ye speak to Hezekiah king of Judah, saying, Let not thy God, in whom thou trustest, deceive thee, saying, Jerusalem shall not be given into the hand of the king of Assyria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 11, E'Behold, thou hast heard what the kings of Assyria have done to all lands by destroying them utterly; and shalt thou be delivered?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 12, E'Have the gods of the nations delivered them which my fathers have destroyed, as Gozan, and Haran, and Rezeph, and the children of Eden which were in Telassar?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 13, E'Where is the king of Hamath, and the king of Arphad, and the king of the city of Sepharvaim, Hena, and Ivah?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 14, E'And Hezekiah received the letter from the hand of the messengers, and read it: and Hezekiah went up unto the house of the LORD, and spread it before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 15, E'And Hezekiah prayed unto the LORD, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 16, E'O LORD of hosts, God of Israel, that dwellest between the cherubims, thou art the God, even thou alone, of all the kingdoms of the earth: thou hast made heaven and earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 17, E'Incline thine ear, O LORD, and hear; open thine eyes, O LORD, and see: and hear all the words of Sennacherib, which hath sent to reproach the living God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 18, E'Of a truth, LORD, the kings of Assyria have laid waste all the nations, and their countries,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 19, E'And have cast their gods into the fire: for they were no gods, but the work of menâ€™s hands, wood and stone: therefore they have destroyed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 20, E'Now therefore, O LORD our God, save us from his hand, that all the kingdoms of the earth may know that thou art the LORD, even thou only.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 21, E'Then Isaiah the son of Amoz sent unto Hezekiah, saying, Thus saith the LORD God of Israel, Whereas thou hast prayed to me against Sennacherib king of Assyria:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 22, E'This is the word which the LORD hath spoken concerning him; The virgin, the daughter of Zion, hath despised thee, and laughed thee to scorn; the daughter of Jerusalem hath shaken her head at thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 23, E'Whom hast thou reproached and blasphemed? and against whom hast thou exalted thy voice, and lifted up thine eyes on high? even against the Holy One of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 24, E'By thy servants hast thou reproached the Lord, and hast said, By the multitude of my chariots am I come up to the height of the mountains, to the sides of Lebanon; and I will cut down the tall cedars thereof, and the choice fir trees thereof: and I will enter into the height of his border, and the forest of his Carmel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 25, E'I have digged, and drunk water; and with the sole of my feet have I dried up all the rivers of the besieged places.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 26, E'Hast thou not heard long ago, how I have done it; and of ancient times, that I have formed it? now have I brought it to pass, that thou shouldest be to lay waste defenced cities into ruinous heaps.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 27, E'Therefore their inhabitants were of small power, they were dismayed and confounded: they were as the grass of the field, and as the green herb, as the grass on the housetops, and as corn blasted before it be grown up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 28, E'But I know thy abode, and thy going out, and thy coming in, and thy rage against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 29, E'Because thy rage against me, and thy tumult, is come up into mine ears, therefore will I put my hook in thy nose, and my bridle in thy lips, and I will turn thee back by the way by which thou camest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 30, E'And this shall be a sign unto thee, Ye shall eat this year such as groweth of itself; and the second year that which springeth of the same: and in the third year sow ye, and reap, and plant vineyards, and eat the fruit thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 31, E'And the remnant that is escaped of the house of Judah shall again take root downward, and bear fruit upward:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 32, E'For out of Jerusalem shall go forth a remnant, and they that escape out of mount Zion: the zeal of the LORD of hosts shall do this.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 33, E'Therefore thus saith the LORD concerning the king of Assyria, He shall not come into this city, nor shoot an arrow there, nor come before it with shields, nor cast a bank against it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 34, E'By the way that he came, by the same shall he return, and shall not come into this city, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 35, E'For I will defend this city to save it for mine own sake, and for my servant Davidâ€™s sake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 36, E'Then the angel of the LORD went forth, and smote in the camp of the Assyrians a hundred and fourscore and five thousand: and when they arose early in the morning, behold, they were all dead corpses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 37, E'So Sennacherib king of Assyria departed, and went and returned, and dwelt at Nineveh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 37, 38, E'And it came to pass, as he was worshipping in the house of Nisroch his god, that Adrammelech and Sharezer his sons smote him with the sword; and they escaped into the land of Armenia: and Esarhaddon his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 1, E'In those days was Hezekiah sick unto death. And Isaiah the prophet the son of Amoz came unto him, and said unto him, Thus saith the LORD, Set thine house in order: for thou shalt die, and not live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 2, E'Then Hezekiah turned his face toward the wall, and prayed unto the LORD,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 3, E'And said, Remember now, O LORD, I beseech thee, how I have walked before thee in truth and with a perfect heart, and have done that which is good in thy sight. And Hezekiah wept sore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 4, E'Then came the word of the LORD to Isaiah, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 5, E'Go, and say to Hezekiah, Thus saith the LORD, the God of David thy father, I have heard thy prayer, I have seen thy tears: behold, I will add unto thy days fifteen years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 6, E'And I will deliver thee and this city out of the hand of the king of Assyria: and I will defend this city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 7, E'And this shall be a sign unto thee from the LORD, that the LORD will do this thing that he hath spoken;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 8, E'Behold, I will bring again the shadow of the degrees, which is gone down in the sun dial of Ahaz, ten degrees backward. So the sun returned ten degrees, by which degrees it was gone down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 9, E'The writing of Hezekiah king of Judah, when he had been sick, and was recovered of his sickness:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 10, E'I said in the cutting off of my days, I shall go to the gates of the grave: I am deprived of the residue of my years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 11, E'I said, I shall not see the LORD, even the LORD, in the land of the living: I shall behold man no more with the inhabitants of the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 12, E'Mine age is departed, and is removed from me as a shepherdâ€™s tent: I have cut off like a weaver my life: he will cut me off with pining sickness: from day even to night wilt thou make an end of me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 13, E'I reckoned till morning, that, as a lion, so will he break all my bones: from day even to night wilt thou make an end of me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 14, E'Like a crane or a swallow, so did I chatter: I did mourn as a dove: mine eyes fail with looking upward: O LORD, I am oppressed; undertake for me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 15, E'What shall I say? he hath both spoken unto me, and himself hath done it: I shall go softly all my years in the bitterness of my soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 16, E'O LORD, by these things men live, and in all these things is the life of my spirit: so wilt thou recover me, and make me to live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 17, E'Behold, for peace I had great bitterness: but thou hast in love to my soul delivered it from the pit of corruption: for thou hast cast all my sins behind thy back.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 18, E'For the grave cannot praise thee, death can not celebrate thee: they that go down into the pit cannot hope for thy truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 19, E'The living, the living, he shall praise thee, as I do this day: the father to the children shall make known thy truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 20, E'The LORD was ready to save me: therefore we will sing my songs to the stringed instruments all the days of our life in the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 21, E'For Isaiah had said, Let them take a lump of figs, and lay it for a plaister upon the boil, and he shall recover.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 38, 22, E'Hezekiah also had said, What is the sign that I shall go up to the house of the LORD?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 39, 1, E'At that time Merodachbaladan, the son of Baladan, king of Babylon, sent letters and a present to Hezekiah: for he had heard that he had been sick, and was recovered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 39, 2, E'And Hezekiah was glad of them, and shewed them the house of his precious things, the silver, and the gold, and the spices, and the precious ointment, and all the house of his armour, and all that was found in his treasures: there was nothing in his house, nor in all his dominion, that Hezekiah shewed them not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 39, 3, E'Then came Isaiah the prophet unto king Hezekiah, and said unto him, What said these men? and from whence came they unto thee? And Hezekiah said, They are come from a far country unto me, even from Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 39, 4, E'Then said he, What have they seen in thine house? And Hezekiah answered, All that is in mine house have they seen: there is nothing among my treasures that I have not shewed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 39, 5, E'Then said Isaiah to Hezekiah, Hear the word of the LORD of hosts:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 39, 6, E'Behold, the days come, that all that is in thine house, and that which thy fathers have laid up in store until this day, shall be carried to Babylon: nothing shall be left, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 39, 7, E'And of thy sons that shall issue from thee, which thou shalt beget, shall they take away; and they shall be eunuchs in the palace of the king of Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 39, 8, E'Then said Hezekiah to Isaiah, Good is the word of the LORD which thou hast spoken. He said moreover, For there shall be peace and truth in my days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 1, E'Comfort ye, comfort ye my people, saith your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 2, E'Speak ye comfortably to Jerusalem, and cry unto her, that her warfare is accomplished, that her iniquity is pardoned: for she hath received of the LORDâ€™s hand double for all her sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 3, E'The voice of him that crieth in the wilderness, Prepare ye the way of the LORD, make straight in the desert a highway for our God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 4, E'Every valley shall be exalted, and every mountain and hill shall be made low: and the crooked shall be made straight, and the rough places plain:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 5, E'And the glory of the LORD shall be revealed, and all flesh shall see it together: for the mouth of the LORD hath spoken it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 6, E'The voice said, Cry. And he said, What shall I cry? All flesh is grass, and all the goodliness thereof is as the flower of the field:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 7, E'The grass withereth, the flower fadeth: because the spirit of the LORD bloweth upon it: surely the people is grass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 8, E'The grass withereth, the flower fadeth: but the word of our God shall stand for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 9, E'O Zion, that bringest good tidings, get thee up into the high mountain; O Jerusalem, that bringest good tidings, lift up thy voice with strength; lift it up, be not afraid; say unto the cities of Judah, Behold your God!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 10, E'Behold, the Lord GOD will come with strong hand, and his arm shall rule for him: behold, his reward is with him, and his work before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 11, E'He shall feed his flock like a shepherd: he shall gather the lambs with his arm, and carry them in his bosom, and shall gently lead those that are with young.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 12, E'Who hath measured the waters in the hollow of his hand, and meted out heaven with the span, and comprehended the dust of the earth in a measure, and weighed the mountains in scales, and the hills in a balance?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 13, E'Who hath directed the Spirit of the LORD, or being his counsellor hath taught him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 14, E'With whom took he counsel, and who instructed him, and taught him in the path of judgment, and taught him knowledge, and shewed to him the way of understanding?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 15, E'Behold, the nations are as a drop of a bucket, and are counted as the small dust of the balance: behold, he taketh up the isles as a very little thing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 16, E'And Lebanon is not sufficient to burn, nor the beasts thereof sufficient for a burnt offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 17, E'All nations before him are as nothing; and they are counted to him less than nothing, and vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 18, E'To whom then will ye liken God? or what likeness will ye compare unto him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 19, E'The workman melteth a graven image, and the goldsmith spreadeth it over with gold, and casteth silver chains.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 20, E'He that is so impoverished that he hath no oblation chooseth a tree that will not rot; he seeketh unto him a cunning workman to prepare a graven image, that shall not be moved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 21, E'Have ye not known? have ye not heard? hath it not been told you from the beginning? have ye not understood from the foundations of the earth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 22, E'It is he that sitteth upon the circle of the earth, and the inhabitants thereof are as grasshoppers; that stretcheth out the heavens as a curtain, and spreadeth them out as a tent to dwell in:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 23, E'That bringeth the princes to nothing; he maketh the judges of the earth as vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 24, E'Yea, they shall not be planted; yea, they shall not be sown: yea, their stock shall not take root in the earth: and he shall also blow upon them, and they shall wither, and the whirlwind shall take them away as stubble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 25, E'To whom then will ye liken me, or shall I be equal? saith the Holy One.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 26, E'Lift up your eyes on high, and behold who hath created these things, that bringeth out their host by number: he calleth them all by names by the greatness of his might, for that he is strong in power; not one faileth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 27, E'Why sayest thou, O Jacob, and speakest, O Israel, My way is hid from the LORD, and my judgment is passed over from my God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 28, E'Hast thou not known? hast thou not heard, that the everlasting God, the LORD, the Creator of the ends of the earth, fainteth not, neither is weary? there is no searching of his understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 29, E'He giveth power to the faint; and to them that have no might he increaseth strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 30, E'Even the youths shall faint and be weary, and the young men shall utterly fall:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 40, 31, E'But they that wait upon the LORD shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 1, E'Keep silence before me, O islands; and let the people renew their strength: let them come near; then let them speak: let us come near together to judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 2, E'Who raised up the righteous man from the east, called him to his foot, gave the nations before him, and made him rule over kings? he gave them as the dust to his sword, and as driven stubble to his bow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 3, E'He pursued them, and passed safely; even by the way that he had not gone with his feet.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Isaiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 4, E'Who hath wrought and done it, calling the generations from the beginning? I the LORD, the first, and with the last; I am he.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 5, E'The isles saw it, and feared; the ends of the earth were afraid, drew near, and came.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 6, E'They helped every one his neighbour; and every one said to his brother, Be of good courage.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 7, E'So the carpenter encouraged the goldsmith, and he that smootheth with the hammer him that smote the anvil, saying, It is ready for the sodering: and he fastened it with nails, that it should not be moved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 8, E'But thou, Israel, art my servant, Jacob whom I have chosen, the seed of Abraham my friend.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 9, E'Thou whom I have taken from the ends of the earth, and called thee from the chief men thereof, and said unto thee, Thou art my servant; I have chosen thee, and not cast thee away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 10, E'Fear thou not; for I am with thee: be not dismayed; for I am thy God: I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 11, E'Behold, all they that were incensed against thee shall be ashamed and confounded: they shall be as nothing; and they that strive with thee shall perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 12, E'Thou shalt seek them, and shalt not find them, even them that contended with thee: they that war against thee shall be as nothing, and as a thing of nought.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 13, E'For I the LORD thy God will hold thy right hand, saying unto thee, Fear not; I will help thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 14, E'Fear not, thou worm Jacob, and ye men of Israel; I will help thee, saith the LORD, and thy redeemer, the Holy One of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 15, E'Behold, I will make thee a new sharp threshing instrument having teeth: thou shalt thresh the mountains, and beat them small, and shalt make the hills as chaff.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 16, E'Thou shalt fan them, and the wind shall carry them away, and the whirlwind shall scatter them: and thou shalt rejoice in the LORD, and shalt glory in the Holy One of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 17, E'When the poor and needy seek water, and there is none, and their tongue faileth for thirst, I the LORD will hear them, I the God of Israel will not forsake them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 18, E'I will open rivers in high places, and fountains in the midst of the valleys: I will make the wilderness a pool of water, and the dry land springs of water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 19, E'I will plant in the wilderness the cedar, the shittah tree, and the myrtle, and the oil tree; I will set in the desert the fir tree, and the pine, and the box tree together:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 20, E'That they may see, and know, and consider, and understand together, that the hand of the LORD hath done this, and the Holy One of Israel hath created it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 21, E'Produce your cause, saith the LORD; bring forth your strong reasons, saith the King of Jacob.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 22, E'Let them bring them forth, and shew us what shall happen: let them shew the former things, what they be, that we may consider them, and know the latter end of them; or declare us things for to come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 23, E'Shew the things that are to come hereafter, that we may know that ye are gods: yea, do good, or do evil, that we may be dismayed, and behold it together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 24, E'Behold, ye are of nothing, and your work of nought: an abomination is he that chooseth you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 25, E'I have raised up one from the north, and he shall come: from the rising of the sun shall he call upon my name: and he shall come upon princes as upon morter, and as the potter treadeth clay.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 26, E'Who hath declared from the beginning, that we may know? and beforetime, that we may say, He is righteous? yea, there is none that sheweth, yea, there is none that declareth, yea, there is none that heareth your words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 27, E'The first shall say to Zion, Behold, behold them: and I will give to Jerusalem one that bringeth good tidings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 28, E'For I beheld, and there was no man; even among them, and there was no counsellor, that, when I asked of them, could answer a word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 41, 29, E'Behold, they are all vanity; their works are nothing: their molten images are wind and confusion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 1, E'Behold my servant, whom I uphold; mine elect, in whom my soul delighteth; I have put my spirit upon him: he shall bring forth judgment to the Gentiles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 2, E'He shall not cry, nor lift up, nor cause his voice to be heard in the street.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 3, E'A bruised reed shall he not break, and the smoking flax shall he not quench: he shall bring forth judgment unto truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 4, E'He shall not fail nor be discouraged, till he have set judgment in the earth: and the isles shall wait for his law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 5, E'Thus saith God the LORD, he that created the heavens, and stretched them out; he that spread forth the earth, and that which cometh out of it; he that giveth breath unto the people upon it, and spirit to them that walk therein:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 6, E'I the LORD have called thee in righteousness, and will hold thine hand, and will keep thee, and give thee for a covenant of the people, for a light of the Gentiles;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 7, E'To open the blind eyes, to bring out the prisoners from the prison, and them that sit in darkness out of the prison house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 8, E'I am the LORD: that is my name: and my glory will I not give to another, neither my praise to graven images.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 9, E'Behold, the former things are come to pass, and new things do I declare: before they spring forth I tell you of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 10, E'Sing unto the LORD a new song, and his praise from the end of the earth, ye that go down to the sea, and all that is therein; the isles, and the inhabitants thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 11, E'Let the wilderness and the cities thereof lift up their voice, the villages that Kedar doth inhabit: let the inhabitants of the rock sing, let them shout from the top of the mountains.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 12, E'Let them give glory unto the LORD, and declare his praise in the islands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 13, E'The LORD shall go forth as a mighty man, he shall stir up jealousy like a man of war: he shall cry, yea, roar; he shall prevail against his enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 14, E'I have long time holden my peace; I have been still, and refrained myself: now will I cry like a travailing woman; I will destroy and devour at once.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 15, E'I will make waste mountains and hills, and dry up all their herbs; and I will make the rivers islands, and I will dry up the pools.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 16, E'And I will bring the blind by a way that they knew not; I will lead them in paths that they have not known: I will make darkness light before them, and crooked things straight. These things will I do unto them, and not forsake them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 17, E'They shall be turned back, they shall be greatly ashamed, that trust in graven images, that say to the molten images, Ye are our gods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 18, E'Hear, ye deaf; and look, ye blind, that ye may see.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 19, E'Who is blind, but my servant? or deaf, as my messenger that I sent? who is blind as he that is perfect, and blind as the LORDâ€™s servant?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 20, E'Seeing many things, but thou observest not; opening the ears, but he heareth not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 21, E'The LORD is well pleased for his righteousnessâ€™ sake; he will magnify the law, and make it honourable.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 22, E'But this is a people robbed and spoiled; they are all of them snared in holes, and they are hid in prison houses: they are for a prey, and none delivereth; for a spoil, and none saith, Restore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 23, E'Who among you will give ear to this? who will hearken and hear for the time to come?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 24, E'Who gave Jacob for a spoil, and Israel to the robbers? did not the LORD, he against whom we have sinned? for they would not walk in his ways, neither were they obedient unto his law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 42, 25, E'Therefore he hath poured upon him the fury of his anger, and the strength of battle: and it hath set him on fire round about, yet he knew not; and it burned him, yet he laid it not to heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 1, E'But now thus saith the LORD that created thee, O Jacob, and he that formed thee, O Israel, Fear not: for I have redeemed thee, I have called thee by thy name; thou art mine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 2, E'When thou passest through the waters, I will be with thee; and through the rivers, they shall not overflow thee: when thou walkest through the fire, thou shalt not be burned; neither shall the flame kindle upon thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 3, E'For I am the LORD thy God, the Holy One of Israel, thy Saviour: I gave Egypt for thy ransom, Ethiopia and Seba for thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 4, E'Since thou wast precious in my sight, thou hast been honourable, and I have loved thee: therefore will I give men for thee, and people for thy life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 5, E'Fear not: for I am with thee: I will bring thy seed from the east, and gather thee from the west;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 6, E'I will say to the north, Give up; and to the south, Keep not back: bring my sons from far, and my daughters from the ends of the earth;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 7, E'Even every one that is called by my name: for I have created him for my glory, I have formed him; yea, I have made him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 8, E'Bring forth the blind people that have eyes, and the deaf that have ears.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 9, E'Let all the nations be gathered together, and let the people be assembled: who among them can declare this, and shew us former things? let them bring forth their witnesses, that they may be justified: or let them hear, and say, It is truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 10, E'Ye are my witnesses, saith the LORD, and my servant whom I have chosen: that ye may know and believe me, and understand that I am he: before me there was no God formed, neither shall there be after me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 11, E'I, even I, am the LORD; and beside me there is no saviour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 12, E'I have declared, and have saved, and I have shewed, when there was no strange god among you: therefore ye are my witnesses, saith the LORD, that I am God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 13, E'Yea, before the day was I am he; and there is none that can deliver out of my hand: I will work, and who shall let it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 14, E'Thus saith the LORD, your redeemer, the Holy One of Israel; For your sake I have sent to Babylon, and have brought down all their nobles, and the Chaldeans, whose cry is in the ships.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 15, E'I am the LORD, your Holy One, the creator of Israel, your King.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 16, E'Thus saith the LORD, which maketh a way in the sea, and a path in the mighty waters;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 17, E'Which bringeth forth the chariot and horse, the army and the power; they shall lie down together, they shall not rise: they are extinct, they are quenched as tow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 18, E'Remember ye not the former things, neither consider the things of old.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 19, E'Behold, I will do a new thing; now it shall spring forth; shall ye not know it? I will even make a way in the wilderness, and rivers in the desert.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 20, E'The beast of the field shall honour me, the dragons and the owls: because I give waters in the wilderness, and rivers in the desert, to give drink to my people, my chosen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 21, E'This people have I formed for myself; they shall shew forth my praise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 22, E'But thou hast not called upon me, O Jacob; but thou hast been weary of me, O Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 23, E'Thou hast not brought me the small cattle of thy burnt offerings; neither hast thou honoured me with thy sacrifices. I have not caused thee to serve with an offering, nor wearied thee with incense.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 24, E'Thou hast bought me no sweet cane with money, neither hast thou filled me with the fat of thy sacrifices: but thou hast made me to serve with thy sins, thou hast wearied me with thine iniquities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 25, E'I, even I, am he that blotteth out thy transgressions for mine own sake, and will not remember thy sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 26, E'Put me in remembrance: let us plead together: declare thou, that thou mayest be justified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 27, E'Thy first father hath sinned, and thy teachers have transgressed against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 43, 28, E'Therefore I have profaned the princes of the sanctuary, and have given Jacob to the curse, and Israel to reproaches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 1, E'Yet now hear, O Jacob my servant; and Israel, whom I have chosen:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 2, E'Thus saith the LORD that made thee, and formed thee from the womb, which will help thee; Fear not, O Jacob, my servant; and thou, Jesurun, whom I have chosen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 3, E'For I will pour water upon him that is thirsty, and floods upon the dry ground: I will pour my spirit upon thy seed, and my blessing upon thine offspring:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 4, E'And they shall spring up as among the grass, as willows by the water courses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 5, E'One shall say, I am the LORDâ€™s; and another shall call himself by the name of Jacob; and another shall subscribe with his hand unto the LORD, and surname himself by the name of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 6, E'Thus saith the LORD the King of Israel, and his redeemer the LORD of hosts; I am the first, and I am the last; and beside me there is no God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 7, E'And who, as I, shall call, and shall declare it, and set it in order for me, since I appointed the ancient people? and the things that are coming, and shall come, let them shew unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 8, E'Fear ye not, neither be afraid: have not I told thee from that time, and have declared it? ye are even my witnesses. Is there a God beside me? yea, there is no God; I know not any.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 9, E'They that make a graven image are all of them vanity; and their delectable things shall not profit; and they are their own witnesses; they see not, nor know; that they may be ashamed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 10, E'Who hath formed a god, or molten a graven image that is profitable for nothing?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 11, E'Behold, all his fellows shall be ashamed: and the workmen, they are of men: let them all be gathered together, let them stand up; yet they shall fear, and they shall be ashamed together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 12, E'The smith with the tongs both worketh in the coals, and fashioneth it with hammers, and worketh it with the strength of his arms: yea, he is hungry, and his strength faileth: he drinketh no water, and is faint.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 13, E'The carpenter stretcheth out his rule; he marketh it out with a line; he fitteth it with planes, and he marketh it out with the compass, and maketh it after the figure of a man, according to the beauty of a man; that it may remain in the house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 14, E'He heweth him down cedars, and taketh the cypress and the oak, which he strengtheneth for himself among the trees of the forest: he planteth an ash, and the rain doth nourish it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 15, E'Then shall it be for a man to burn: for he will take thereof, and warm himself; yea, he kindleth it, and baketh bread; yea, he maketh a god, and worshippeth it; he maketh it a graven image, and falleth down thereto.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 16, E'He burneth part thereof in the fire; with part thereof he eateth flesh; he roasteth roast, and is satisfied: yea, he warmeth himself, and saith, Aha, I am warm, I have seen the fire:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 17, E'And the residue thereof he maketh a god, even his graven image: he falleth down unto it, and worshippeth it, and prayeth unto it, and saith, Deliver me; for thou art my god.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 18, E'They have not known nor understood: for he hath shut their eyes, that they cannot see; and their hearts, that they cannot understand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 19, E'And none considereth in his heart, neither is there knowledge nor understanding to say, I have burned part of it in the fire; yea, also I have baked bread upon the coals thereof; I have roasted flesh, and eaten it: and shall I make the residue thereof an abomination? shall I fall down to the stock of a tree?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 20, E'He feedeth on ashes: a deceived heart hath turned him aside, that he cannot deliver his soul, nor say, Is there not a lie in my right hand?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 21, E'Remember these, O Jacob and Israel; for thou art my servant: I have formed thee; thou art my servant: O Israel, thou shalt not be forgotten of me.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Isaiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 22, E'I have blotted out, as a thick cloud, thy transgressions, and, as a cloud, thy sins: return unto me; for I have redeemed thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 23, E'Sing, O ye heavens; for the LORD hath done it: shout, ye lower parts of the earth: break forth into singing, ye mountains, O forest, and every tree therein: for the LORD hath redeemed Jacob, and glorified himself in Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 24, E'Thus saith the LORD, thy redeemer, and he that formed thee from the womb, I am the LORD that maketh all things; that stretcheth forth the heavens alone; that spreadeth abroad the earth by myself;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 25, E'That frustrateth the tokens of the liars, and maketh diviners mad; that turneth wise men backward, and maketh their knowledge foolish;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 26, E'That confirmeth the word of his servant, and performeth the counsel of his messengers; that saith to Jerusalem, Thou shalt be inhabited; and to the cities of Judah, Ye shall be built, and I will raise up the decayed places thereof:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 27, E'That saith to the deep, Be dry, and I will dry up thy rivers:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 44, 28, E'That saith of Cyrus, He is my shepherd, and shall perform all my pleasure: even saying to Jerusalem, Thou shalt be built; and to the temple, Thy foundation shall be laid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 1, E'Thus saith the LORD to his anointed, to Cyrus, whose right hand I have holden, to subdue nations before him; and I will loose the loins of kings, to open before him the two leaved gates; and the gates shall not be shut;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 2, E'I will go before thee, and make the crooked places straight: I will break in pieces the gates of brass, and cut in sunder the bars of iron:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 3, E'And I will give thee the treasures of darkness, and hidden riches of secret places, that thou mayest know that I, the LORD, which call thee by thy name, am the God of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 4, E'For Jacob my servantâ€™s sake, and Israel mine elect, I have even called thee by thy name: I have surnamed thee, though thou hast not known me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 5, E'I am the LORD, and there is none else, there is no God beside me: I girded thee, though thou hast not known me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 6, E'That they may know from the rising of the sun, and from the west, that there is none beside me. I am the LORD, and there is none else.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 7, E'I form the light, and create darkness: I make peace, and create evil: I the LORD do all these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 8, E'Drop down, ye heavens, from above, and let the skies pour down righteousness: let the earth open, and let them bring forth salvation, and let righteousness spring up together; I the LORD have created it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 9, E'Woe unto him that striveth with his Maker! Let the potsherd strive with the potsherds of the earth. Shall the clay say to him that fashioneth it, What makest thou? or thy work, He hath no hands?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 10, E'Woe unto him that saith unto his father, What begettest thou? or to the woman, What hast thou brought forth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 11, E'Thus saith the LORD, the Holy One of Israel, and his Maker, Ask me of things to come concerning my sons, and concerning the work of my hands command ye me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 12, E'I have made the earth, and created man upon it: I, even my hands, have stretched out the heavens, and all their host have I commanded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 13, E'I have raised him up in righteousness, and I will direct all his ways: he shall build my city, and he shall let go my captives, not for price nor reward, saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 14, E'Thus saith the LORD, The labour of Egypt, and merchandise of Ethiopia and of the Sabeans, men of stature, shall come over unto thee, and they shall be thine: they shall come after thee; in chains they shall come over, and they shall fall down unto thee, they shall make supplication unto thee, saying, Surely God is in thee; and there is none else, there is no God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 15, E'Verily thou art a God that hidest thyself, O God of Israel, the Saviour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 16, E'They shall be ashamed, and also confounded, all of them: they shall go to confusion together that are makers of idols.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 17, E'But Israel shall be saved in the LORD with an everlasting salvation: ye shall not be ashamed nor confounded world without end.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 18, E'For thus saith the LORD that created the heavens; God himself that formed the earth and made it; he hath established it, he created it not in vain, he formed it to be inhabited: I am the LORD; and there is none else.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 19, E'I have not spoken in secret, in a dark place of the earth: I said not unto the seed of Jacob, Seek ye me in vain: I the LORD speak righteousness, I declare things that are right.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 20, E'Assemble yourselves and come; draw near together, ye that are escaped of the nations: they have no knowledge that set up the wood of their graven image, and pray unto a god that cannot save.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 21, E'Tell ye, and bring them near; yea, let them take counsel together: who hath declared this from ancient time? who hath told it from that time? have not I the LORD? and there is no God else beside me; a just God and a Saviour; there is none beside me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 22, E'Look unto me, and be ye saved, all the ends of the earth: for I am God, and there is none else.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 23, E'I have sworn by myself, the word is gone out of my mouth in righteousness, and shall not return, That unto me every knee shall bow, every tongue shall swear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 24, E'Surely, shall one say, in the LORD have I righteousness and strength: even to him shall men come; and all that are incensed against him shall be ashamed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 45, 25, E'In the LORD shall all the seed of Israel be justified, and shall glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 1, E'Bel boweth down, Nebo stoopeth, their idols were upon the beasts, and upon the cattle: your carriages were heavy loaden; they are a burden to the weary beast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 2, E'They stoop, they bow down together; they could not deliver the burden, but themselves are gone into captivity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 3, E'Hearken unto me, O house of Jacob, and all the remnant of the house of Israel, which are borne by me from the belly, which are carried from the womb:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 4, E'And even to your old age I am he; and even to hoar hairs will I carry you: I have made, and I will bear; even I will carry, and will deliver you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 5, E'To whom will ye liken me, and make me equal, and compare me, that we may be like?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 6, E'They lavish gold out of the bag, and weigh silver in the balance, and hire a goldsmith; and he maketh it a god: they fall down, yea, they worship.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 7, E'They bear him upon the shoulder, they carry him, and set him in his place, and he standeth; from his place shall he not remove: yea, one shall cry unto him, yet can he not answer, nor save him out of his trouble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 8, E'Remember this, and shew yourselves men: bring it again to mind, O ye transgressors.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 9, E'Remember the former things of old: for I am God, and there is none else; I am God, and there is none like me,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 10, E'Declaring the end from the beginning, and from ancient times the things that are not yet done, saying, My counsel shall stand, and I will do all my pleasure:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 11, E'Calling a ravenous bird from the east, the man that executeth my counsel from a far country: yea, I have spoken it, I will also bring it to pass; I have purposed it, I will also do it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 12, E'Hearken unto me, ye stouthearted, that are far from righteousness:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 46, 13, E'I bring near my righteousness; it shall not be far off, and my salvation shall not tarry: and I will place salvation in Zion for Israel my glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 1, E'Come down, and sit in the dust, O virgin daughter of Babylon, sit on the ground: there is no throne, O daughter of the Chaldeans: for thou shalt no more be called tender and delicate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 2, E'Take the millstones, and grind meal: uncover thy locks, make bare the leg, uncover the thigh, pass over the rivers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 3, E'Thy nakedness shall be uncovered, yea, thy shame shall be seen: I will take vengeance, and I will not meet thee as a man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 4, E'As for our redeemer, the LORD of hosts is his name, the Holy One of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 5, E'Sit thou silent, and get thee into darkness, O daughter of the Chaldeans: for thou shalt no more be called, The lady of kingdoms.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 6, E'I was wroth with my people, I have polluted mine inheritance, and given them into thine hand: thou didst shew them no mercy; upon the ancient hast thou very heavily laid thy yoke.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 7, E'And thou saidst, I shall be a lady for ever: so that thou didst not lay these things to thy heart, neither didst remember the latter end of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 8, E'Therefore hear now this, thou that art given to pleasures, that dwellest carelessly, that sayest in thine heart, I am, and none else beside me; I shall not sit as a widow, neither shall I know the loss of children:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 9, E'But these two things shall come to thee in a moment in one day, the loss of children, and widowhood: they shall come upon thee in their perfection for the multitude of thy sorceries, and for the great abundance of thine enchantments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 10, E'For thou hast trusted in thy wickedness: thou hast said, None seeth me. Thy wisdom and thy knowledge, it hath perverted thee; and thou hast said in thine heart, I am, and none else beside me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 11, E'Therefore shall evil come upon thee; thou shalt not know from whence it riseth: and mischief shall fall upon thee; thou shalt not be able to put it off: and desolation shall come upon thee suddenly, which thou shalt not know.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 12, E'Stand now with thine enchantments, and with the multitude of thy sorceries, wherein thou hast laboured from thy youth; if so be thou shalt be able to profit, if so be thou mayest prevail.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 13, E'Thou art wearied in the multitude of thy counsels. Let now the astrologers, the stargazers, the monthly prognosticators, stand up, and save thee from these things that shall come upon thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 14, E'Behold, they shall be as stubble; the fire shall burn them; they shall not deliver themselves from the power of the flame: there shall not be a coal to warm at, nor fire to sit before it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 47, 15, E'Thus shall they be unto thee with whom thou hast laboured, even thy merchants, from thy youth: they shall wander every one to his quarter; none shall save thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 1, E'Hear ye this, O house of Jacob, which are called by the name of Israel, and are come forth out of the waters of Judah, which swear by the name of the LORD, and make mention of the God of Israel, but not in truth, nor in righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 2, E'For they call themselves of the holy city, and stay themselves upon the God of Israel; The LORD of hosts is his name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 3, E'I have declared the former things from the beginning; and they went forth out of my mouth, and I shewed them; I did them suddenly, and they came to pass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 4, E'Because I knew that thou art obstinate, and thy neck is an iron sinew, and thy brow brass;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 5, E'I have even from the beginning declared it to thee; before it came to pass I shewed it thee: lest thou shouldest say, Mine idol hath done them, and my graven image, and my molten image, hath commanded them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 6, E'Thou hast heard, see all this; and will not ye declare it? I have shewed thee new things from this time, even hidden things, and thou didst not know them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 7, E'They are created now, and not from the beginning; even before the day when thou heardest them not; lest thou shouldest say, Behold, I knew them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 8, E'Yea, thou heardest not; yea, thou knewest not; yea, from that time that thine ear was not opened: for I knew that thou wouldest deal very treacherously, and wast called a transgressor from the womb.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 9, E'For my nameâ€™s sake will I defer mine anger, and for my praise will I refrain for thee, that I cut thee not off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 10, E'Behold, I have refined thee, but not with silver; I have chosen thee in the furnace of affliction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 11, E'For mine own sake, even for mine own sake, will I do it: for how should my name be polluted? and I will not give my glory unto another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 12, E'Hearken unto me, O Jacob and Israel, my called; I am he; I am the first, I also am the last.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 13, E'Mine hand also hath laid the foundation of the earth, and my right hand hath spanned the heavens: when I call unto them, they stand up together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 14, E'All ye, assemble yourselves, and hear; which among them hath declared these things? The LORD hath loved him: he will do his pleasure on Babylon, and his arm shall be on the Chaldeans.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 15, E'I, even I, have spoken; yea, I have called him: I have brought him, and he shall make his way prosperous.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 16, E'Come ye near unto me, hear ye this; I have not spoken in secret from the beginning; from the time that it was, there am I: and now the Lord GOD, and his Spirit, hath sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 17, E'Thus saith the LORD, thy Redeemer, the Holy One of Israel; I am the LORD thy God which teacheth thee to profit, which leadeth thee by the way that thou shouldest go.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 18, E'O that thou hadst hearkened to my commandments! then had thy peace been as a river, and thy righteousness as the waves of the sea:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 19, E'Thy seed also had been as the sand, and the offspring of thy bowels like the gravel thereof; his name should not have been cut off nor destroyed from before me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 20, E'Go ye forth of Babylon, flee ye from the Chaldeans, with a voice of singing declare ye, tell this, utter it even to the end of the earth; say ye, The LORD hath redeemed his servant Jacob.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 21, E'And they thirsted not when he led them through the deserts: he caused the waters to flow out of the rock for them: he clave the rock also, and the waters gushed out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 48, 22, E'There is no peace, saith the LORD, unto the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 1, E'Listen, O isles, unto me; and hearken, ye people, from far; The LORD hath called me from the womb; from the bowels of my mother hath he made mention of my name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 2, E'And he hath made my mouth like a sharp sword; in the shadow of his hand hath he hid me, and made me a polished shaft; in his quiver hath he hid me;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 3, E'And said unto me, Thou art my servant, O Israel, in whom I will be glorified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 4, E'Then I said, I have laboured in vain, I have spent my strength for nought, and in vain: yet surely my judgment is with the LORD, and my work with my God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 5, E'And now, saith the LORD that formed me from the womb to be his servant, to bring Jacob again to him, Though Israel be not gathered, yet shall I be glorious in the eyes of the LORD, and my God shall be my strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 6, E'And he said, It is a light thing that thou shouldest be my servant to raise up the tribes of Jacob, and to restore the preserved of Israel: I will also give thee for a light to the Gentiles, that thou mayest be my salvation unto the end of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 7, E'Thus saith the LORD, the Redeemer of Israel, and his Holy One, to him whom man despiseth, to him whom the nation abhorreth, to a servant of rulers, Kings shall see and arise, princes also shall worship, because of the LORD that is faithful, and the Holy One of Israel, and he shall choose thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 8, E'Thus saith the LORD, In an acceptable time have I heard thee, and in a day of salvation have I helped thee: and I will preserve thee, and give thee for a covenant of the people, to establish the earth, to cause to inherit the desolate heritages;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 9, E'That thou mayest say to the prisoners, Go forth; to them that are in darkness, Shew yourselves. They shall feed in the ways, and their pastures shall be in all high places.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 10, E'They shall not hunger nor thirst; neither shall the heat nor sun smite them: for he that hath mercy on them shall lead them, even by the springs of water shall he guide them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 11, E'And I will make all my mountains a way, and my highways shall be exalted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 12, E'Behold, these shall come from far: and, lo, these from the north and from the west; and these from the land of Sinim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 13, E'Sing, O heavens; and be joyful, O earth; and break forth into singing, O mountains: for the LORD hath comforted his people, and will have mercy upon his afflicted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 14, E'But Zion said, The LORD hath forsaken me, and my Lord hath forgotten me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 15, E'Can a woman forget her sucking child, that she should not have compassion on the son of her womb? yea, they may forget, yet will I not forget thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 16, E'Behold, I have graven thee upon the palms of my hands; thy walls are continually before me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 17, E'Thy children shall make haste; thy destroyers and they that made thee waste shall go forth of thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 18, E'Lift up thine eyes round about, and behold: all these gather themselves together, and come to thee. As I live, saith the LORD, thou shalt surely clothe thee with them all, as with an ornament, and bind them on thee, as a bride doeth.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Isaiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 19, E'For thy waste and thy desolate places, and the land of thy destruction, shall even now be too narrow by reason of the inhabitants, and they that swallowed thee up shall be far away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 20, E'The children which thou shalt have, after thou hast lost the other, shall say again in thine ears, The place is too strait for me: give place to me that I may dwell.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 21, E'Then shalt thou say in thine heart, Who hath begotten me these, seeing I have lost my children, and am desolate, a captive, and removing to and fro? and who hath brought up these? Behold, I was left alone; these, where had they been?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 22, E'Thus saith the Lord GOD, Behold, I will lift up mine hand to the Gentiles, and set up my standard to the people: and they shall bring thy sons in their arms, and thy daughters shall be carried upon their shoulders.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 23, E'And kings shall be thy nursing fathers, and their queens thy nursing mothers: they shall bow down to thee with their face toward the earth, and lick up the dust of thy feet; and thou shalt know that I am the LORD: for they shall not be ashamed that wait for me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 24, E'Shall the prey be taken from the mighty, or the lawful captive delivered?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 25, E'But thus saith the LORD, Even the captives of the mighty shall be taken away, and the prey of the terrible shall be delivered: for I will contend with him that contendeth with thee, and I will save thy children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 49, 26, E'And I will feed them that oppress thee with their own flesh; and they shall be drunken with their own blood, as with sweet wine: and all flesh shall know that I the LORD am thy Saviour and thy Redeemer, the mighty One of Jacob.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 50, 1, E'Thus saith the LORD, Where is the bill of your motherâ€™s divorcement, whom I have put away? or which of my creditors is it to whom I have sold you? Behold, for your iniquities have ye sold yourselves, and for your transgressions is your mother put away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 50, 2, E'Wherefore, when I came, was there no man? when I called, was there none to answer? Is my hand shortened at all, that it cannot redeem? or have I no power to deliver? behold, at my rebuke I dry up the sea, I make the rivers a wilderness: their fish stinketh, because there is no water, and dieth for thirst.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 50, 3, E'I clothe the heavens with blackness, and I make sackcloth their covering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 50, 4, E'The Lord GOD hath given me the tongue of the learned, that I should know how to speak a word in season to him that is weary: he wakeneth morning by morning, he wakeneth mine ear to hear as the learned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 50, 5, E'The Lord GOD hath opened mine ear, and I was not rebellious, neither turned away back.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 50, 6, E'I gave my back to the smiters, and my cheeks to them that plucked off the hair: I hid not my face from shame and spitting.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 50, 7, E'For the Lord GOD will help me; therefore shall I not be confounded: therefore have I set my face like a flint, and I know that I shall not be ashamed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 50, 8, E'He is near that justifieth me; who will contend with me? let us stand together: who is mine adversary? let him come near to me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 50, 9, E'Behold, the Lord GOD will help me; who is he that shall condemn me? lo, they all shall wax old as a garment; the moth shall eat them up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 50, 10, E'Who is among you that feareth the LORD, that obeyeth the voice of his servant, that walketh in darkness, and hath no light? let him trust in the name of the LORD, and stay upon his God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 50, 11, E'Behold, all ye that kindle a fire, that compass yourselves about with sparks: walk in the light of your fire, and in the sparks that ye have kindled. This shall ye have of mine hand; ye shall lie down in sorrow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 51, 1, E'Hearken to me, ye that follow after righteousness, ye that seek the LORD: look unto the rock whence ye are hewn, and to the hole of the pit whence ye are digged.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 51, 2, E'Look unto Abraham your father, and unto Sarah that bare you: for I called him alone, and blessed him, and increased him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 51, 3, E'For the LORD shall comfort Zion: he will comfort all her waste places; and he will make her wilderness like Eden, and her desert like the garden of the LORD; joy and gladness shall be found therein, thanksgiving, and the voice of melody.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 51, 4, E'Hearken unto me, my people; and give ear unto me, O my nation: for a law shall proceed from me, and I will make my judgment to rest for a light of the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 51, 5, E'My righteousness is near; my salvation is gone forth, and mine arms shall judge the people; the isles shall wait upon me, and on mine arm shall they trust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 51, 6, E'Lift up your eyes to the heavens, and look upon the earth beneath: for the heavens shall vanish away like smoke, and the earth shall wax old like a garment, and they that dwell therein shall die in like manner: but my salvation shall be for ever, and my righteousness shall not be abolished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 51, 7, E'Hearken unto me, ye that know righteousness, the people in whose heart is my law; fear ye not the reproach of men, neither be ye afraid of their revilings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 51, 8, E'For the moth shall eat them up like a garment, and the worm shall eat them like wool: but my righteousness shall be for ever, and my salvation from generation to generation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 51, 9, E'Awake, awake, put on strength, O arm of the LORD; awake, as in the ancient days, in the generations of old. Art thou not it that hath cut Rahab, and wounded the dragon?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 51, 10, E'Art thou not it which hath dried the sea, the waters of the great deep; that hath made the depths of the sea a way for the ransomed to pass over?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 51, 11, E'Therefore the redeemed of the LORD shall return, and come with singing unto Zion; and everlasting joy shall be upon their head: they shall obtain gladness and joy; and sorrow and mourning shall flee away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 51, 12, E'I, even I, am he that comforteth you: who art thou, that thou shouldest be afraid of a man that shall die, and of the son of man which shall be made as grass;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 51, 13, E'And forgettest the LORD thy maker, that hath stretched forth the heavens, and laid the foundations of the earth; and hast feared continually every day because of the fury of the oppressor, as if he were ready to destroy? and where is the fury of the oppressor?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 51, 14, E'The captive exile hasteneth that he may be loosed, and that he should not die in the pit, nor that his bread should fail.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 51, 15, E'But I am the LORD thy God, that divided the sea, whose waves roared: The LORD of hosts is his name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 51, 16, E'And I have put my words in thy mouth, and I have covered thee in the shadow of mine hand, that I may plant the heavens, and lay the foundations of the earth, and say unto Zion, Thou art my people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 51, 17, E'Awake, awake, stand up, O Jerusalem, which hast drunk at the hand of the LORD the cup of his fury; thou hast drunken the dregs of the cup of trembling, and wrung them out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 51, 18, E'There is none to guide her among all the sons whom she hath brought forth; neither is there any that taketh her by the hand of all the sons that she hath brought up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 51, 19, E'These two things are come unto thee; who shall be sorry for thee? desolation, and destruction, and the famine, and the sword: by whom shall I comfort thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 51, 20, E'Thy sons have fainted, they lie at the head of all the streets, as a wild bull in a net: they are full of the fury of the LORD, the rebuke of thy God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 51, 21, E'Therefore hear now this, thou afflicted, and drunken, but not with wine:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 51, 22, E'Thus saith thy Lord the LORD, and thy God that pleadeth the cause of his people, Behold, I have taken out of thine hand the cup of trembling, even the dregs of the cup of my fury; thou shalt no more drink it again:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 51, 23, E'But I will put it into the hand of them that afflict thee; which have said to thy soul, Bow down, that we may go over: and thou hast laid thy body as the ground, and as the street, to them that went over.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 52, 1, E'Awake, awake; put on thy strength, O Zion; put on thy beautiful garments, O Jerusalem, the holy city: for henceforth there shall no more come into thee the uncircumcised and the unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 52, 2, E'Shake thyself from the dust; arise, and sit down, O Jerusalem: loose thyself from the bands of thy neck, O captive daughter of Zion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 52, 3, E'For thus saith the LORD, Ye have sold yourselves for nought; and ye shall be redeemed without money.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 52, 4, E'For thus saith the Lord GOD, My people went down aforetime into Egypt to sojourn there; and the Assyrian oppressed them without cause.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 52, 5, E'Now therefore, what have I here, saith the LORD, that my people is taken away for nought? they that rule over them make them to howl, saith the LORD; and my name continually every day is blasphemed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 52, 6, E'Therefore my people shall know my name: therefore they shall know in that day that I am he that doth speak: behold, it is I.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 52, 7, E'How beautiful upon the mountains are the feet of him that bringeth good tidings, that publisheth peace; that bringeth good tidings of good, that publisheth salvation; that saith unto Zion, Thy God reigneth!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 52, 8, E'Thy watchmen shall lift up the voice; with the voice together shall they sing: for they shall see eye to eye, when the LORD shall bring again Zion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 52, 9, E'Break forth into joy, sing together, ye waste places of Jerusalem: for the LORD hath comforted his people, he hath redeemed Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 52, 10, E'The LORD hath made bare his holy arm in the eyes of all the nations; and all the ends of the earth shall see the salvation of our God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 52, 11, E'Depart ye, depart ye, go ye out from thence, touch no unclean thing; go ye out of the midst of her; be ye clean, that bear the vessels of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 52, 12, E'For ye shall not go out with haste, nor go by flight: for the LORD will go before you; and the God of Israel will be your rereward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 52, 13, E'Behold, my servant shall deal prudently, he shall be exalted and extolled, and be very high.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 52, 14, E'As many were astonied at thee; his visage was so marred more than any man, and his form more than the sons of men:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 52, 15, E'So shall he sprinkle many nations; the kings shall shut their mouths at him: for that which had not been told them shall they see; and that which they had not heard shall they consider.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 53, 1, E'Who hath believed our report? and to whom is the arm of the LORD revealed?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 53, 2, E'For he shall grow up before him as a tender plant, and as a root out of a dry ground: he hath no form nor comeliness; and when we shall see him, there is no beauty that we should desire him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 53, 3, E'He is despised and rejected of men; a man of sorrows, and acquainted with grief: and we hid as it were our faces from him; he was despised, and we esteemed him not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 53, 4, E'Surely he hath borne our griefs, and carried our sorrows: yet we did esteem him stricken, smitten of God, and afflicted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 53, 5, E'But he was wounded for our transgressions, he was bruised for our iniquities: the chastisement of our peace was upon him; and with his stripes we are healed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 53, 6, E'All we like sheep have gone astray; we have turned every one to his own way; and the LORD hath laid on him the iniquity of us all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 53, 7, E'He was oppressed, and he was afflicted, yet he opened not his mouth: he is brought as a lamb to the slaughter, and as a sheep before her shearers is dumb, so he openeth not his mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 53, 8, E'He was taken from prison and from judgment: and who shall declare his generation? for he was cut off out of the land of the living: for the transgression of my people was he stricken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 53, 9, E'And he made his grave with the wicked, and with the rich in his death; because he had done no violence, neither was any deceit in his mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 53, 10, E'Yet it pleased the LORD to bruise him; he hath put him to grief: when thou shalt make his soul an offering for sin, he shall see his seed, he shall prolong his days, and the pleasure of the LORD shall prosper in his hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 53, 11, E'He shall see of the travail of his soul, and shall be satisfied: by his knowledge shall my righteous servant justify many; for he shall bear their iniquities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 53, 12, E'Therefore will I divide him a portion with the great, and he shall divide the spoil with the strong; because he hath poured out his soul unto death: and he was numbered with the transgressors; and he bare the sin of many, and made intercession for the transgressors.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 54, 1, E'Sing, O barren, thou that didst not bear; break forth into singing, and cry aloud, thou that didst not travail with child: for more are the children of the desolate than the children of the married wife, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 54, 2, E'Enlarge the place of thy tent, and let them stretch forth the curtains of thine habitations: spare not, lengthen thy cords, and strengthen thy stakes;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 54, 3, E'For thou shalt break forth on the right hand and on the left; and thy seed shall inherit the Gentiles, and make the desolate cities to be inhabited.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 54, 4, E'Fear not; for thou shalt not be ashamed: neither be thou confounded; for thou shalt not be put to shame: for thou shalt forget the shame of thy youth, and shalt not remember the reproach of thy widowhood any more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 54, 5, E'For thy Maker is thine husband; the LORD of hosts is his name; and thy Redeemer the Holy One of Israel; The God of the whole earth shall he be called.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 54, 6, E'For the LORD hath called thee as a woman forsaken and grieved in spirit, and a wife of youth, when thou wast refused, saith thy God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 54, 7, E'For a small moment have I forsaken thee; but with great mercies will I gather thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 54, 8, E'In a little wrath I hid my face from thee for a moment; but with everlasting kindness will I have mercy on thee, saith the LORD thy Redeemer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 54, 9, E'For this is as the waters of Noah unto me: for as I have sworn that the waters of Noah should no more go over the earth; so have I sworn that I would not be wroth with thee, nor rebuke thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 54, 10, E'For the mountains shall depart, and the hills be removed; but my kindness shall not depart from thee, neither shall the covenant of my peace be removed, saith the LORD that hath mercy on thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 54, 11, E'O thou afflicted, tossed with tempest, and not comforted, behold, I will lay thy stones with fair colours, and lay thy foundations with sapphires.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 54, 12, E'And I will make thy windows of agates, and thy gates of carbuncles, and all thy borders of pleasant stones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 54, 13, E'And all thy children shall be taught of the LORD; and great shall be the peace of thy children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 54, 14, E'In righteousness shalt thou be established: thou shalt be far from oppression; for thou shalt not fear: and from terror; for it shall not come near thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 54, 15, E'Behold, they shall surely gather together, but not by me: whosoever shall gather together against thee shall fall for thy sake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 54, 16, E'Behold, I have created the smith that bloweth the coals in the fire, and that bringeth forth an instrument for his work; and I have created the waster to destroy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 54, 17, E'No weapon that is formed against thee shall prosper; and every tongue that shall rise against thee in judgment thou shalt condemn. This is the heritage of the servants of the LORD, and their righteousness is of me, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 55, 1, E'Ho, every one that thirsteth, come ye to the waters, and he that hath no money; come ye, buy, and eat; yea, come, buy wine and milk without money and without price.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 55, 2, E'Wherefore do ye spend money for that which is not bread? and your labour for that which satisfieth not? hearken diligently unto me, and eat ye that which is good, and let your soul delight itself in fatness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 55, 3, E'Incline your ear, and come unto me: hear, and your soul shall live; and I will make an everlasting covenant with you, even the sure mercies of David.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 55, 4, E'Behold, I have given him for a witness to the people, a leader and commander to the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 55, 5, E'Behold, thou shalt call a nation that thou knowest not, and nations that knew not thee shall run unto thee because of the LORD thy God, and for the Holy One of Israel; for he hath glorified thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 55, 6, E'Seek ye the LORD while he may be found, call ye upon him while he is near:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 55, 7, E'Let the wicked forsake his way, and the unrighteous man his thoughts: and let him return unto the LORD, and he will have mercy upon him; and to our God, for he will abundantly pardon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 55, 8, E'For my thoughts are not your thoughts, neither are your ways my ways, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 55, 9, E'For as the heavens are higher than the earth, so are my ways higher than your ways, and my thoughts than your thoughts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 55, 10, E'For as the rain cometh down, and the snow from heaven, and returneth not thither, but watereth the earth, and maketh it bring forth and bud, that it may give seed to the sower, and bread to the eater:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 55, 11, E'So shall my word be that goeth forth out of my mouth: it shall not return unto me void, but it shall accomplish that which I please, and it shall prosper in the thing whereto I sent it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 55, 12, E'For ye shall go out with joy, and be led forth with peace: the mountains and the hills shall break forth before you into singing, and all the trees of the field shall clap their hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 55, 13, E'Instead of the thorn shall come up the fir tree, and instead of the brier shall come up the myrtle tree: and it shall be to the LORD for a name, for an everlasting sign that shall not be cut off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 56, 1, E'Thus saith the LORD, Keep ye judgment, and do justice: for my salvation is near to come, and my righteousness to be revealed.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Isaiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 56, 2, E'Blessed is the man that doeth this, and the son of man that layeth hold on it; that keepeth the sabbath from polluting it, and keepeth his hand from doing any evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 56, 3, E'Neither let the son of the stranger, that hath joined himself to the LORD, speak, saying, The LORD hath utterly separated me from his people: neither let the eunuch say, Behold, I am a dry tree.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 56, 4, E'For thus saith the LORD unto the eunuchs that keep my sabbaths, and choose the things that please me, and take hold of my covenant;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 56, 5, E'Even unto them will I give in mine house and within my walls a place and a name better than of sons and of daughters: I will give them an everlasting name, that shall not be cut off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 56, 6, E'Also the sons of the stranger, that join themselves to the LORD, to serve him, and to love the name of the LORD, to be his servants, every one that keepeth the sabbath from polluting it, and taketh hold of my covenant;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 56, 7, E'Even them will I bring to my holy mountain, and make them joyful in my house of prayer: their burnt offerings and their sacrifices shall be accepted upon mine altar; for mine house shall be called an house of prayer for all people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 56, 8, E'The Lord GOD, which gathereth the outcasts of Israel saith, Yet will I gather others to him, beside those that are gathered unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 56, 9, E'All ye beasts of the field, come to devour, yea, all ye beasts in the forest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 56, 10, E'His watchmen are blind: they are all ignorant, they are all dumb dogs, they cannot bark; sleeping, lying down, loving to slumber.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 56, 11, E'Yea, they are greedy dogs which can never have enough, and they are shepherds that cannot understand: they all look to their own way, every one for his gain, from his quarter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 56, 12, E'Come ye, say they, I will fetch wine, and we will fill ourselves with strong drink; and to morrow shall be as this day, and much more abundant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 57, 1, E'The righteous perisheth, and no man layeth it to heart: and merciful men are taken away, none considering that the righteous is taken away from the evil to come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 57, 2, E'He shall enter into peace: they shall rest in their beds, each one walking in his uprightness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 57, 3, E'But draw near hither, ye sons of the sorceress, the seed of the adulterer and the whore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 57, 4, E'Against whom do ye sport yourselves? against whom make ye a wide mouth, and draw out the tongue? are ye not children of transgression, a seed of falsehood,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 57, 5, E'Enflaming yourselves with idols under every green tree, slaying the children in the valleys under the clifts of the rocks?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 57, 6, E'Among the smooth stones of the stream is thy portion; they, they are thy lot: even to them hast thou poured a drink offering, thou hast offered a meat offering. Should I receive comfort in these?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 57, 7, E'Upon a lofty and high mountain hast thou set thy bed: even thither wentest thou up to offer sacrifice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 57, 8, E'Behind the doors also and the posts hast thou set up thy remembrance: for thou hast discovered thyself to another than me, and art gone up; thou hast enlarged thy bed, and made thee a covenant with them; thou lovedst their bed where thou sawest it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 57, 9, E'And thou wentest to the king with ointment, and didst increase thy perfumes, and didst send thy messengers far off, and didst debase thyself even unto hell.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 57, 10, E'Thou art wearied in the greatness of thy way; yet saidst thou not, There is no hope: thou hast found the life of thine hand; therefore thou wast not grieved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 57, 11, E'And of whom hast thou been afraid or feared, that thou hast lied, and hast not remembered me, nor laid it to thy heart? have not I held my peace even of old, and thou fearest me not?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 57, 12, E'I will declare thy righteousness, and thy works; for they shall not profit thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 57, 13, E'When thou criest, let thy companies deliver thee; but the wind shall carry them all away; vanity shall take them: but he that putteth his trust in me shall possess the land, and shall inherit my holy mountain;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 57, 14, E'And shall say, Cast ye up, cast ye up, prepare the way, take up the stumblingblock out of the way of my people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 57, 15, E'For thus saith the high and lofty One that inhabiteth eternity, whose name is Holy; I dwell in the high and holy place, with him also that is of a contrite and humble spirit, to revive the spirit of the humble, and to revive the heart of the contrite ones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 57, 16, E'For I will not contend for ever, neither will I be always wroth: for the spirit should fail before me, and the souls which I have made.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 57, 17, E'For the iniquity of his covetousness was I wroth, and smote him: I hid me, and was wroth, and he went on frowardly in the way of his heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 57, 18, E'I have seen his ways, and will heal him: I will lead him also, and restore comforts unto him and to his mourners.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 57, 19, E'I create the fruit of the lips; Peace, peace to him that is far off, and to him that is near, saith the LORD; and I will heal him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 57, 20, E'But the wicked are like the troubled sea, when it cannot rest, whose waters cast up mire and dirt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 57, 21, E'There is no peace, saith my God, to the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 58, 1, E'Cry aloud, spare not, lift up thy voice like a trumpet, and shew my people their transgression, and the house of Jacob their sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 58, 2, E'Yet they seek me daily, and delight to know my ways, as a nation that did righteousness, and forsook not the ordinance of their God: they ask of me the ordinances of justice; they take delight in approaching to God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 58, 3, E'Wherefore have we fasted, say they, and thou seest not? wherefore have we afflicted our soul, and thou takest no knowledge? Behold, in the day of your fast ye find pleasure, and exact all your labours.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 58, 4, E'Behold, ye fast for strife and debate, and to smite with the fist of wickedness: ye shall not fast as ye do this day, to make your voice to be heard on high.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 58, 5, E'Is it such a fast that I have chosen? a day for a man to afflict his soul? is it to bow down his head as a bulrush, and to spread sackcloth and ashes under him? wilt thou call this a fast, and an acceptable day to the LORD?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 58, 6, E'Is not this the fast that I have chosen? to loose the bands of wickedness, to undo the heavy burdens, and to let the oppressed go free, and that ye break every yoke?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 58, 7, E'Is it not to deal thy bread to the hungry, and that thou bring the poor that are cast out to thy house? when thou seest the naked, that thou cover him; and that thou hide not thyself from thine own flesh?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 58, 8, E'Then shall thy light break forth as the morning, and thine health shall spring forth speedily: and thy righteousness shall go before thee; the glory of the LORD shall be thy rereward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 58, 9, E'Then shalt thou call, and the LORD shall answer; thou shalt cry, and he shall say, Here I am. If thou take away from the midst of thee the yoke, the putting forth of the finger, and speaking vanity;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 58, 10, E'And if thou draw out thy soul to the hungry, and satisfy the afflicted soul; then shall thy light rise in obscurity, and thy darkness be as the noon day:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 58, 11, E'And the LORD shall guide thee continually, and satisfy thy soul in drought, and make fat thy bones: and thou shalt be like a watered garden, and like a spring of water, whose waters fail not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 58, 12, E'And they that shall be of thee shall build the old waste places: thou shalt raise up the foundations of many generations; and thou shalt be called, The repairer of the breach, The restorer of paths to dwell in.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 58, 13, E'If thou turn away thy foot from the sabbath, from doing thy pleasure on my holy day; and call the sabbath a delight, the holy of the LORD, honourable; and shalt honour him, not doing thine own ways, nor finding thine own pleasure, nor speaking thine own words:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 58, 14, E'Then shalt thou delight thyself in the LORD; and I will cause thee to ride upon the high places of the earth, and feed thee with the heritage of Jacob thy father: for the mouth of the LORD hath spoken it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 59, 1, E'Behold, the LORDâ€™s hand is not shortened, that it cannot save; neither his ear heavy, that it cannot hear:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 59, 2, E'But your iniquities have separated between you and your God, and your sins have hid his face from you, that he will not hear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 59, 3, E'For your hands are defiled with blood, and your fingers with iniquity; your lips have spoken lies, your tongue hath muttered perverseness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 59, 4, E'None calleth for justice, nor any pleadeth for truth: they trust in vanity, and speak lies; they conceive mischief, and bring forth iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 59, 5, E'They hatch cockatriceâ€™ eggs, and weave the spiderâ€™s web: he that eateth of their eggs dieth, and that which is crushed breaketh out into a viper.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 59, 6, E'Their webs shall not become garments, neither shall they cover themselves with their works: their works are works of iniquity, and the act of violence is in their hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 59, 7, E'Their feet run to evil, and they make haste to shed innocent blood: their thoughts are thoughts of iniquity; wasting and destruction are in their paths.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 59, 8, E'The way of peace they know not; and there is no judgment in their goings: they have made them crooked paths: whosoever goeth therein shall not know peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 59, 9, E'Therefore is judgment far from us, neither doth justice overtake us: we wait for light, but behold obscurity; for brightness, but we walk in darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 59, 10, E'We grope for the wall like the blind, and we grope as if we had no eyes: we stumble at noon day as in the night; we are in desolate places as dead men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 59, 11, E'We roar all like bears, and mourn sore like doves: we look for judgment, but there is none; for salvation, but it is far off from us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 59, 12, E'For our transgressions are multiplied before thee, and our sins testify against us: for our transgressions are with us; and as for our iniquities, we know them;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 59, 13, E'In transgressing and lying against the LORD, and departing away from our God, speaking oppression and revolt, conceiving and uttering from the heart words of falsehood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 59, 14, E'And judgment is turned away backward, and justice standeth afar off: for truth is fallen in the street, and equity cannot enter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 59, 15, E'Yea, truth faileth; and he that departeth from evil maketh himself a prey: and the LORD saw it, and it displeased him that there was no judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 59, 16, E'And he saw that there was no man, and wondered that there was no intercessor: therefore his arm brought salvation unto him; and his righteousness, it sustained him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 59, 17, E'For he put on righteousness as a breastplate, and an helmet of salvation upon his head; and he put on the garments of vengeance for clothing, and was clad with zeal as a cloak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 59, 18, E'According to their deeds, accordingly he will repay, fury to his adversaries, recompence to his enemies; to the islands he will repay recompence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 59, 19, E'So shall they fear the name of the LORD from the west, and his glory from the rising of the sun. When the enemy shall come in like a flood, the Spirit of the LORD shall lift up a standard against him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 59, 20, E'And the Redeemer shall come to Zion, and unto them that turn from transgression in Jacob, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 59, 21, E'As for me, this is my covenant with them, saith the LORD; My spirit that is upon thee, and my words which I have put in thy mouth, shall not depart out of thy mouth, nor out of the mouth of thy seed, nor out of the mouth of thy seedâ€™s seed, saith the LORD, from henceforth and for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 60, 1, E'Arise, shine; for thy light is come, and the glory of the LORD is risen upon thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 60, 2, E'For, behold, the darkness shall cover the earth, and gross darkness the people: but the LORD shall arise upon thee, and his glory shall be seen upon thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 60, 3, E'And the Gentiles shall come to thy light, and kings to the brightness of thy rising.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 60, 4, E'Lift up thine eyes round about, and see: all they gather themselves together, they come to thee: thy sons shall come from far, and thy daughters shall be nursed at thy side.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 60, 5, E'Then thou shalt see, and flow together, and thine heart shall fear, and be enlarged; because the abundance of the sea shall be converted unto thee, the forces of the Gentiles shall come unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 60, 6, E'The multitude of camels shall cover thee, the dromedaries of Midian and Ephah; all they from Sheba shall come: they shall bring gold and incense; and they shall shew forth the praises of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 60, 7, E'All the flocks of Kedar shall be gathered together unto thee, the rams of Nebaioth shall minister unto thee: they shall come up with acceptance on mine altar, and I will glorify the house of my glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 60, 8, E'Who are these that fly as a cloud, and as the doves to their windows?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 60, 9, E'Surely the isles shall wait for me, and the ships of Tarshish first, to bring thy sons from far, their silver and their gold with them, unto the name of the LORD thy God, and to the Holy One of Israel, because he hath glorified thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 60, 10, E'And the sons of strangers shall build up thy walls, and their kings shall minister unto thee: for in my wrath I smote thee, but in my favour have I had mercy on thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 60, 11, E'Therefore thy gates shall be open continually; they shall not be shut day nor night; that men may bring unto thee the forces of the Gentiles, and that their kings may be brought.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 60, 12, E'For the nation and kingdom that will not serve thee shall perish; yea, those nations shall be utterly wasted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 60, 13, E'The glory of Lebanon shall come unto thee, the fir tree, the pine tree, and the box together, to beautify the place of my sanctuary; and I will make the place of my feet glorious.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 60, 14, E'The sons also of them that afflicted thee shall come bending unto thee; and all they that despised thee shall bow themselves down at the soles of thy feet; and they shall call thee, The city of the LORD, The Zion of the Holy One of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 60, 15, E'Whereas thou hast been forsaken and hated, so that no man went through thee, I will make thee an eternal excellency, a joy of many generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 60, 16, E'Thou shalt also suck the milk of the Gentiles, and shalt suck the breast of kings: and thou shalt know that I the LORD am thy Saviour and thy Redeemer, the mighty One of Jacob.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 60, 17, E'For brass I will bring gold, and for iron I will bring silver, and for wood brass, and for stones iron: I will also make thy officers peace, and thine exactors righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 60, 18, E'Violence shall no more be heard in thy land, wasting nor destruction within thy borders; but thou shalt call thy walls Salvation, and thy gates Praise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 60, 19, E'The sun shall be no more thy light by day; neither for brightness shall the moon give light unto thee: but the LORD shall be unto thee an everlasting light, and thy God thy glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 60, 20, E'Thy sun shall no more go down; neither shall thy moon withdraw itself: for the LORD shall be thine everlasting light, and the days of thy mourning shall be ended.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 60, 21, E'Thy people also shall be all righteous: they shall inherit the land for ever, the branch of my planting, the work of my hands, that I may be glorified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 60, 22, E'A little one shall become a thousand, and a small one a strong nation: I the LORD will hasten it in his time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 61, 1, E'The Spirit of the Lord GOD is upon me; because the LORD hath anointed me to preach good tidings unto the meek; he hath sent me to bind up the brokenhearted, to proclaim liberty to the captives, and the opening of the prison to them that are bound;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 61, 2, E'To proclaim the acceptable year of the LORD, and the day of vengeance of our God; to comfort all that mourn;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 61, 3, E'To appoint unto them that mourn in Zion, to give unto them beauty for ashes, the oil of joy for mourning, the garment of praise for the spirit of heaviness; that they might be called trees of righteousness, the planting of the LORD, that he might be glorified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 61, 4, E'And they shall build the old wastes, they shall raise up the former desolations, and they shall repair the waste cities, the desolations of many generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 61, 5, E'And strangers shall stand and feed your flocks, and the sons of the alien shall be your plowmen and your vinedressers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 61, 6, E'But ye shall be named the Priests of the LORD: men shall call you the Ministers of our God: ye shall eat the riches of the Gentiles, and in their glory shall ye boast yourselves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 61, 7, E'For your shame ye shall have double; and for confusion they shall rejoice in their portion: therefore in their land they shall possess the double: everlasting joy shall be unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 61, 8, E'For I the LORD love judgment, I hate robbery for burnt offering; and I will direct their work in truth, and I will make an everlasting covenant with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 61, 9, E'And their seed shall be known among the Gentiles, and their offspring among the people: all that see them shall acknowledge them, that they are the seed which the LORD hath blessed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 61, 10, E'I will greatly rejoice in the LORD, my soul shall be joyful in my God; for he hath clothed me with the garments of salvation, he hath covered me with the robe of righteousness, as a bridegroom decketh himself with ornaments, and as a bride adorneth herself with her jewels.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 61, 11, E'For as the earth bringeth forth her bud, and as the garden causeth the things that are sown in it to spring forth; so the Lord GOD will cause righteousness and praise to spring forth before all the nations.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Isaiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 62, 1, E'For Zionâ€™s sake will I not hold my peace, and for Jerusalemâ€™s sake I will not rest, until the righteousness thereof go forth as brightness, and the salvation thereof as a lamp that burneth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 62, 2, E'And the Gentiles shall see thy righteousness, and all kings thy glory: and thou shalt be called by a new name, which the mouth of the LORD shall name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 62, 3, E'Thou shalt also be a crown of glory in the hand of the LORD, and a royal diadem in the hand of thy God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 62, 4, E'Thou shalt no more be termed Forsaken; neither shall thy land any more be termed Desolate: but thou shalt be called Hephzibah, and thy land Beulah: for the LORD delighteth in thee, and thy land shall be married.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 62, 5, E'For as a young man marrieth a virgin, so shall thy sons marry thee: and as the bridegroom rejoiceth over the bride, so shall thy God rejoice over thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 62, 6, E'I have set watchmen upon thy walls, O Jerusalem, which shall never hold their peace day nor night: ye that make mention of the LORD, keep not silence,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 62, 7, E'And give him no rest, till he establish, and till he make Jerusalem a praise in the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 62, 8, E'The LORD hath sworn by his right hand, and by the arm of his strength, Surely I will no more give thy corn to be meat for thine enemies; and the sons of the stranger shall not drink thy wine, for the which thou hast laboured:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 62, 9, E'But they that have gathered it shall eat it, and praise the LORD; and they that have brought it together shall drink it in the courts of my holiness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 62, 10, E'Go through, go through the gates; prepare ye the way of the people; cast up, cast up the highway; gather out the stones; lift up a standard for the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 62, 11, E'Behold, the LORD hath proclaimed unto the end of the world, Say ye to the daughter of Zion, Behold, thy salvation cometh; behold, his reward is with him, and his work before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 62, 12, E'And they shall call them, The holy people, The redeemed of the LORD: and thou shalt be called, Sought out, A city not forsaken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 63, 1, E'Who is this that cometh from Edom, with dyed garments from Bozrah? this that is glorious in his apparel, travelling in the greatness of his strength? I that speak in righteousness, mighty to save.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 63, 2, E'Wherefore art thou red in thine apparel, and thy garments like him that treadeth in the winefat?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 63, 3, E'I have trodden the winepress alone; and of the people there was none with me: for I will tread them in mine anger, and trample them in my fury; and their blood shall be sprinkled upon my garments, and I will stain all my raiment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 63, 4, E'For the day of vengeance is in mine heart, and the year of my redeemed is come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 63, 5, E'And I looked, and there was none to help; and I wondered that there was none to uphold: therefore mine own arm brought salvation unto me; and my fury, it upheld me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 63, 6, E'And I will tread down the people in mine anger, and make them drunk in my fury, and I will bring down their strength to the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 63, 7, E'I will mention the lovingkindnesses of the LORD, and the praises of the LORD, according to all that the LORD hath bestowed on us, and the great goodness toward the house of Israel, which he hath bestowed on them according to his mercies, and according to the multitude of his lovingkindnesses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 63, 8, E'For he said, Surely they are my people, children that will not lie: so he was their Saviour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 63, 9, E'In all their affliction he was afflicted, and the angel of his presence saved them: in his love and in his pity he redeemed them; and he bare them, and carried them all the days of old.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 63, 10, E'But they rebelled, and vexed his holy Spirit: therefore he was turned to be their enemy, and he fought against them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 63, 11, E'Then he remembered the days of old, Moses, and his people, saying, Where is he that brought them up out of the sea with the shepherd of his flock? where is he that put his holy Spirit within him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 63, 12, E'That led them by the right hand of Moses with his glorious arm, dividing the water before them, to make himself an everlasting name?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 63, 13, E'That led them through the deep, as an horse in the wilderness, that they should not stumble?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 63, 14, E'As a beast goeth down into the valley, the Spirit of the LORD caused him to rest: so didst thou lead thy people, to make thyself a glorious name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 63, 15, E'Look down from heaven, and behold from the habitation of thy holiness and of thy glory: where is thy zeal and thy strength, the sounding of thy bowels and of thy mercies toward me? are they restrained?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 63, 16, E'Doubtless thou art our father, though Abraham be ignorant of us, and Israel acknowledge us not: thou, O LORD, art our father, our redeemer; thy name is from everlasting.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 63, 17, E'O LORD, why hast thou made us to err from thy ways, and hardened our heart from thy fear? Return for thy servantsâ€™ sake, the tribes of thine inheritance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 63, 18, E'The people of thy holiness have possessed it but a little while: our adversaries have trodden down thy sanctuary.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 63, 19, E'We are thine: thou never barest rule over them; they were not called by thy name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 64, 1, E'Oh that thou wouldest rend the heavens, that thou wouldest come down, that the mountains might flow down at thy presence,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 64, 2, E'As when the melting fire burneth, the fire causeth the waters to boil, to make thy name known to thine adversaries, that the nations may tremble at thy presence!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 64, 3, E'When thou didst terrible things which we looked not for, thou camest down, the mountains flowed down at thy presence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 64, 4, E'For since the beginning of the world men have not heard, nor perceived by the ear, neither hath the eye seen, O God, beside thee, what he hath prepared for him that waiteth for him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 64, 5, E'Thou meetest him that rejoiceth and worketh righteousness, those that remember thee in thy ways: behold, thou art wroth; for we have sinned: in those is continuance, and we shall be saved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 64, 6, E'But we are all as an unclean thing, and all our righteousnesses are as filthy rags; and we all do fade as a leaf; and our iniquities, like the wind, have taken us away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 64, 7, E'And there is none that calleth upon thy name, that stirreth up himself to take hold of thee: for thou hast hid thy face from us, and hast consumed us, because of our iniquities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 64, 8, E'But now, O LORD, thou art our father; we are the clay, and thou our potter; and we all are the work of thy hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 64, 9, E'Be not wroth very sore, O LORD, neither remember iniquity for ever: behold, see, we beseech thee, we are all thy people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 64, 10, E'Thy holy cities are a wilderness, Zion is a wilderness, Jerusalem a desolation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 64, 11, E'Our holy and our beautiful house, where our fathers praised thee, is burned up with fire: and all our pleasant things are laid waste.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 64, 12, E'Wilt thou refrain thyself for these things, O LORD? wilt thou hold thy peace, and afflict us very sore?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 1, E'I am sought of them that asked not for me; I am found of them that sought me not: I said, Behold me, behold me, unto a nation that was not called by my name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 2, E'I have spread out my hands all the day unto a rebellious people, which walketh in a way that was not good, after their own thoughts;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 3, E'A people that provoketh me to anger continually to my face; that sacrificeth in gardens, and burneth incense upon altars of brick;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 4, E'Which remain among the graves, and lodge in the monuments, which eat swineâ€™s flesh, and broth of abominable things is in their vessels;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 5, E'Which say, Stand by thyself, come not near to me; for I am holier than thou. These are a smoke in my nose, a fire that burneth all the day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 6, E'Behold, it is written before me: I will not keep silence, but will recompense, even recompense into their bosom,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 7, E'Your iniquities, and the iniquities of your fathers together, saith the LORD, which have burned incense upon the mountains, and blasphemed me upon the hills: therefore will I measure their former work into their bosom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 8, E'Thus saith the LORD, As the new wine is found in the cluster, and one saith, Destroy it not; for a blessing is in it: so will I do for my servantsâ€™ sakes, that I may not destroy them all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 9, E'And I will bring forth a seed out of Jacob, and out of Judah an inheritor of my mountains: and mine elect shall inherit it, and my servants shall dwell there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 10, E'And Sharon shall be a fold of flocks, and the valley of Achor a place for the herds to lie down in, for my people that have sought me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 11, E'But ye are they that forsake the LORD, that forget my holy mountain, that prepare a table for that troop, and that furnish the drink offering unto that number.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 12, E'Therefore will I number you to the sword, and ye shall all bow down to the slaughter: because when I called, ye did not answer; when I spake, ye did not hear; but did evil before mine eyes, and did choose that wherein I delighted not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 13, E'Therefore thus saith the Lord GOD, Behold, my servants shall eat, but ye shall be hungry: behold, my servants shall drink, but ye shall be thirsty: behold, my servants shall rejoice, but ye shall be ashamed:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 14, E'Behold, my servants shall sing for joy of heart, but ye shall cry for sorrow of heart, and shall howl for vexation of spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 15, E'And ye shall leave your name for a curse unto my chosen: for the Lord GOD shall slay thee, and call his servants by another name:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 16, E'That he who blesseth himself in the earth shall bless himself in the God of truth; and he that sweareth in the earth shall swear by the God of truth; because the former troubles are forgotten, and because they are hid from mine eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 17, E'For, behold, I create new heavens and a new earth: and the former shall not be remembered, nor come into mind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 18, E'But be ye glad and rejoice for ever in that which I create: for, behold, I create Jerusalem a rejoicing, and her people a joy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 19, E'And I will rejoice in Jerusalem, and joy in my people: and the voice of weeping shall be no more heard in her, nor the voice of crying.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 20, E'There shall be no more thence an infant of days, nor an old man that hath not filled his days: for the child shall die an hundred years old; but the sinner being an hundred years old shall be accursed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 21, E'And they shall build houses, and inhabit them; and they shall plant vineyards, and eat the fruit of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 22, E'They shall not build, and another inhabit; they shall not plant, and another eat: for as the days of a tree are the days of my people, and mine elect shall long enjoy the work of their hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 23, E'They shall not labour in vain, nor bring forth for trouble; for they are the seed of the blessed of the LORD, and their offspring with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 24, E'And it shall come to pass, that before they call, I will answer; and while they are yet speaking, I will hear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 65, 25, E'The wolf and the lamb shall feed together, and the lion shall eat straw like the bullock: and dust shall be the serpentâ€™s meat. They shall not hurt nor destroy in all my holy mountain, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 66, 1, E'Thus saith the LORD, The heaven is my throne, and the earth is my footstool: where is the house that ye build unto me? and where is the place of my rest?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 66, 2, E'For all those things hath mine hand made, and all those things have been, saith the LORD: but to this man will I look, even to him that is poor and of a contrite spirit, and trembleth at my word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 66, 3, E'He that killeth an ox is as if he slew a man; he that sacrificeth a lamb, as if he cut off a dogâ€™s neck; he that offereth an oblation, as if he offered swineâ€™s blood; he that burneth incense, as if he blessed an idol. Yea, they have chosen their own ways, and their soul delighteth in their abominations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 66, 4, E'I also will choose their delusions, and will bring their fears upon them; because when I called, none did answer; when I spake, they did not hear: but they did evil before mine eyes, and chose that in which I delighted not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 66, 5, E'Hear the word of the LORD, ye that tremble at his word; Your brethren that hated you, that cast you out for my nameâ€™s sake, said, Let the LORD be glorified: but he shall appear to your joy, and they shall be ashamed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 66, 6, E'A voice of noise from the city, a voice from the temple, a voice of the LORD that rendereth recompence to his enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 66, 7, E'Before she travailed, she brought forth; before her pain came, she was delivered of a man child.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 66, 8, E'Who hath heard such a thing? who hath seen such things? Shall the earth be made to bring forth in one day? or shall a nation be born at once? for as soon as Zion travailed, she brought forth her children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 66, 9, E'Shall I bring to the birth, and not cause to bring forth? saith the LORD: shall I cause to bring forth, and shut the womb? saith thy God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 66, 10, E'Rejoice ye with Jerusalem, and be glad with her, all ye that love her: rejoice for joy with her, all ye that mourn for her:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 66, 11, E'That ye may suck, and be satisfied with the breasts of her consolations; that ye may milk out, and be delighted with the abundance of her glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 66, 12, E'For thus saith the LORD, Behold, I will extend peace to her like a river, and the glory of the Gentiles like a flowing stream: then shall ye suck, ye shall be borne upon her sides, and be dandled upon her knees.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 66, 13, E'As one whom his mother comforteth, so will I comfort you; and ye shall be comforted in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 66, 14, E'And when ye see this, your heart shall rejoice, and your bones shall flourish like an herb: and the hand of the LORD shall be known toward his servants, and his indignation toward his enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 66, 15, E'For, behold, the LORD will come with fire, and with his chariots like a whirlwind, to render his anger with fury, and his rebuke with flames of fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 66, 16, E'For by fire and by his sword will the LORD plead with all flesh: and the slain of the LORD shall be many.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 66, 17, E'They that sanctify themselves, and purify themselves in the gardens behind one tree in the midst, eating swineâ€™s flesh, and the abomination, and the mouse, shall be consumed together, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 66, 18, E'For I know their works and their thoughts: it shall come, that I will gather all nations and tongues; and they shall come, and see my glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 66, 19, E'And I will set a sign among them, and I will send those that escape of them unto the nations, to Tarshish, Pul, and Lud, that draw the bow, to Tubal, and Javan, to the isles afar off, that have not heard my fame, neither have seen my glory; and they shall declare my glory among the Gentiles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 66, 20, E'And they shall bring all your brethren for an offering unto the LORD out of all nations upon horses, and in chariots, and in litters, and upon mules, and upon swift beasts, to my holy mountain Jerusalem, saith the LORD, as the children of Israel bring an offering in a clean vessel into the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 66, 21, E'And I will also take of them for priests and for Levites, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 66, 22, E'For as the new heavens and the new earth, which I will make, shall remain before me, saith the LORD, so shall your seed and your name remain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 66, 23, E'And it shall come to pass, that from one new moon to another, and from one sabbath to another, shall all flesh come to worship before me, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '031154a8-3fff-4e6b-bcaf-f5b0c5cbae9b', 66, 24, E'And they shall go forth, and look upon the carcases of the men that have transgressed against me: for their worm shall not die, neither shall their fire be quenched; and they shall be an abhorring unto all flesh.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Isaiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 1, 1, E'The words of Jeremiah the son of Hilkiah, of the priests that were in Anathoth in the land of Benjamin:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 1, 2, E'To whom the word of the LORD came in the days of Josiah the son of Amon king of Judah, in the thirteenth year of his reign.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 1, 3, E'It came also in the days of Jehoiakim the son of Josiah king of Judah, unto the end of the eleventh year of Zedekiah the son of Josiah king of Judah, unto the carrying away of Jerusalem captive in the fifth month.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 1, 4, E'Then the word of the LORD came unto me, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 1, 5, E'Before I formed thee in the belly I knew thee; and before thou camest forth out of the womb I sanctified thee, and I ordained thee a prophet unto the nations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 1, 6, E'Then said I, Ah, Lord GOD! behold, I cannot speak: for I am a child.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 1, 7, E'But the LORD said unto me, Say not, I am a child: for thou shalt go to all that I shall send thee, and whatsoever I command thee thou shalt speak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 1, 8, E'Be not afraid of their faces: for I am with thee to deliver thee, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 1, 9, E'Then the LORD put forth his hand, and touched my mouth. And the LORD said unto me, Behold, I have put my words in thy mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 1, 10, E'See, I have this day set thee over the nations and over the kingdoms, to root out, and to pull down, and to destroy, and to throw down, to build, and to plant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 1, 11, E'Moreover the word of the LORD came unto me, saying, Jeremiah, what seest thou? And I said, I see a rod of an almond tree.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 1, 12, E'Then said the LORD unto me, Thou hast well seen: for I will hasten my word to perform it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 1, 13, E'And the word of the LORD came unto me the second time, saying, What seest thou? And I said, I see a seething pot; and the face thereof is toward the north.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 1, 14, E'Then the LORD said unto me, Out of the north an evil shall break forth upon all the inhabitants of the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 1, 15, E'For, lo, I will call all the families of the kingdoms of the north, saith the LORD; and they shall come, and they shall set every one his throne at the entering of the gates of Jerusalem, and against all the walls thereof round about, and against all the cities of Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 1, 16, E'And I will utter my judgments against them touching all their wickedness, who have forsaken me, and have burned incense unto other gods, and worshipped the works of their own hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 1, 17, E'Thou therefore gird up thy loins, and arise, and speak unto them all that I command thee: be not dismayed at their faces, lest I confound thee before them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 1, 18, E'For, behold, I have made thee this day a defenced city, and an iron pillar, and brasen walls against the whole land, against the kings of Judah, against the princes thereof, against the priests thereof, and against the people of the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 1, 19, E'And they shall fight against thee; but they shall not prevail against thee; for I am with thee, saith the LORD, to deliver thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 1, E'Moreover the word of the LORD came to me, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 2, E'Go and cry in the ears of Jerusalem, saying, Thus saith the LORD; I remember thee, the kindness of thy youth, the love of thine espousals, when thou wentest after me in the wilderness, in a land that was not sown.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 3, E'Israel was holiness unto the LORD, and the firstfruits of his increase: all that devour him shall offend; evil shall come upon them, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 4, E'Hear ye the word of the LORD, O house of Jacob, and all the families of the house of Israel:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 5, E'Thus saith the LORD, What iniquity have your fathers found in me, that they are gone far from me, and have walked after vanity, and are become vain?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 6, E'Neither said they, Where is the LORD that brought us up out of the land of Egypt, that led us through the wilderness, through a land of deserts and of pits, through a land of drought, and of the shadow of death, through a land that no man passed through, and where no man dwelt?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 7, E'And I brought you into a plentiful country, to eat the fruit thereof and the goodness thereof; but when ye entered, ye defiled my land, and made mine heritage an abomination.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 8, E'The priests said not, Where is the LORD? and they that handle the law knew me not: the pastors also transgressed against me, and the prophets prophesied by Baal, and walked after things that do not profit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 9, E'Wherefore I will yet plead with you, saith the LORD, and with your childrenâ€™s children will I plead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 10, E'For pass over the isles of Chittim, and see; and send unto Kedar, and consider diligently, and see if there be such a thing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 11, E'Hath a nation changed their gods, which are yet no gods? but my people have changed their glory for that which doth not profit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 12, E'Be astonished, O ye heavens, at this, and be horribly afraid, be ye very desolate, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 13, E'For my people have committed two evils; they have forsaken me the fountain of living waters, and hewed them out cisterns, broken cisterns, that can hold no water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 14, E'Is Israel a servant? is he a homeborn slave? why is he spoiled?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 15, E'The young lions roared upon him, and yelled, and they made his land waste: his cities are burned without inhabitant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 16, E'Also the children of Noph and Tahapanes have broken the crown of thy head.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 17, E'Hast thou not procured this unto thyself, in that thou hast forsaken the LORD thy God, when he led thee by the way?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 18, E'And now what hast thou to do in the way of Egypt, to drink the waters of Sihor? or what hast thou to do in the way of Assyria, to drink the waters of the river?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 19, E'Thine own wickedness shall correct thee, and thy backslidings shall reprove thee: know therefore and see that it is an evil thing and bitter, that thou hast forsaken the LORD thy God, and that my fear is not in thee, saith the Lord GOD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 20, E'For of old time I have broken thy yoke, and burst thy bands; and thou saidst, I will not transgress; when upon every high hill and under every green tree thou wanderest, playing the harlot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 21, E'Yet I had planted thee a noble vine, wholly a right seed: how then art thou turned into the degenerate plant of a strange vine unto me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 22, E'For though thou wash thee with nitre, and take thee much soap, yet thine iniquity is marked before me, saith the Lord GOD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 23, E'How canst thou say, I am not polluted, I have not gone after Baalim? see thy way in the valley, know what thou hast done: thou art a swift dromedary traversing her ways;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 24, E'A wild ass used to the wilderness, that snuffeth up the wind at her pleasure; in her occasion who can turn her away? all they that seek her will not weary themselves; in her month they shall find her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 25, E'Withhold thy foot from being unshod, and thy throat from thirst: but thou saidst, There is no hope: no; for I have loved strangers, and after them will I go.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 26, E'As the thief is ashamed when he is found, so is the house of Israel ashamed; they, their kings, their princes, and their priests, and their prophets,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 27, E'Saying to a stock, Thou art my father; and to a stone, Thou hast brought me forth: for they have turned their back unto me, and not their face: but in the time of their trouble they will say, Arise, and save us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 28, E'But where are thy gods that thou hast made thee? let them arise, if they can save thee in the time of thy trouble: for according to the number of thy cities are thy gods, O Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 29, E'Wherefore will ye plead with me? ye all have transgressed against me, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 30, E'In vain have I smitten your children; they received no correction: your own sword hath devoured your prophets, like a destroying lion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 31, E'O generation, see ye the word of the LORD. Have I been a wilderness unto Israel? a land of darkness? wherefore say my people, We are lords; we will come no more unto thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 32, E'Can a maid forget her ornaments, or a bride her attire? yet my people have forgotten me days without number.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 33, E'Why trimmest thou thy way to seek love? therefore hast thou also taught the wicked ones thy ways.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 34, E'Also in thy skirts is found the blood of the souls of the poor innocents: I have not found it by secret search, but upon all these.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 35, E'Yet thou sayest, Because I am innocent, surely his anger shall turn from me. Behold, I will plead with thee, because thou sayest, I have not sinned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 36, E'Why gaddest thou about so much to change thy way? thou also shalt be ashamed of Egypt, as thou wast ashamed of Assyria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 2, 37, E'Yea, thou shalt go forth from him, and thine hands upon thine head: for the LORD hath rejected thy confidences, and thou shalt not prosper in them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 1, E'They say, If a man put away his wife, and she go from him, and become another manâ€™s, shall he return unto her again? shall not that land be greatly polluted? but thou hast played the harlot with many lovers; yet return again to me, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 2, E'Lift up thine eyes unto the high places, and see where thou hast not been lien with. In the ways hast thou sat for them, as the Arabian in the wilderness; and thou hast polluted the land with thy whoredoms and with thy wickedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 3, E'Therefore the showers have been withholden, and there hath been no latter rain; and thou hadst a whoreâ€™s forehead, thou refusedst to be ashamed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 4, E'Wilt thou not from this time cry unto me, My father, thou art the guide of my youth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 5, E'Will he reserve his anger for ever? will he keep it to the end? Behold, thou hast spoken and done evil things as thou couldest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 6, E'The LORD said also unto me in the days of Josiah the king, Hast thou seen that which backsliding Israel hath done? she is gone up upon every high mountain and under every green tree, and there hath played the harlot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 7, E'And I said after she had done all these things, Turn thou unto me. But she returned not. And her treacherous sister Judah saw it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 8, E'And I saw, when for all the causes whereby backsliding Israel committed adultery I had put her away, and given her a bill of divorce; yet her treacherous sister Judah feared not, but went and played the harlot also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 9, E'And it came to pass through the lightness of her whoredom, that she defiled the land, and committed adultery with stones and with stocks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 10, E'And yet for all this her treacherous sister Judah hath not turned unto me with her whole heart, but feignedly, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 11, E'And the LORD said unto me, The backsliding Israel hath justified herself more than treacherous Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 12, E'Go and proclaim these words toward the north, and say, Return, thou backsliding Israel, saith the LORD; and I will not cause mine anger to fall upon you: for I am merciful, saith the LORD, and I will not keep anger for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 13, E'Only acknowledge thine iniquity, that thou hast transgressed against the LORD thy God, and hast scattered thy ways to the strangers under every green tree, and ye have not obeyed my voice, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 14, E'Turn, O backsliding children, saith the LORD; for I am married unto you: and I will take you one of a city, and two of a family, and I will bring you to Zion:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 15, E'And I will give you pastors according to mine heart, which shall feed you with knowledge and understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 16, E'And it shall come to pass, when ye be multiplied and increased in the land, in those days, saith the LORD, they shall say no more, The ark of the covenant of the LORD: neither shall it come to mind: neither shall they remember it; neither shall they visit it; neither shall that be done any more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 17, E'At that time they shall call Jerusalem the throne of the LORD; and all the nations shall be gathered unto it, to the name of the LORD, to Jerusalem: neither shall they walk any more after the imagination of their evil heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 18, E'In those days the house of Judah shall walk with the house of Israel, and they shall come together out of the land of the north to the land that I have given for an inheritance unto your fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 19, E'But I said, How shall I put thee among the children, and give thee a pleasant land, a goodly heritage of the hosts of nations? and I said, Thou shalt call me, My father; and shalt not turn away from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 20, E'Surely as a wife treacherously departeth from her husband, so have ye dealt treacherously with me, O house of Israel, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 21, E'A voice was heard upon the high places, weeping and supplications of the children of Israel: for they have perverted their way, and they have forgotten the LORD their God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 22, E'Return, ye backsliding children, and I will heal your backslidings. Behold, we come unto thee; for thou art the LORD our God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 23, E'Truly in vain is salvation hoped for from the hills, and from the multitude of mountains: truly in the LORD our God is the salvation of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 24, E'For shame hath devoured the labour of our fathers from our youth; their flocks and their herds, their sons and their daughters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 3, 25, E'We lie down in our shame, and our confusion covereth us: for we have sinned against the LORD our God, we and our fathers, from our youth even unto this day, and have not obeyed the voice of the LORD our God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 1, E'If thou wilt return, O Israel, saith the LORD, return unto me: and if thou wilt put away thine abominations out of my sight, then shalt thou not remove.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 2, E'And thou shalt swear, The LORD liveth, in truth, in judgment, and in righteousness; and the nations shall bless themselves in him, and in him shall they glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 3, E'For thus saith the LORD to the men of Judah and Jerusalem, Break up your fallow ground, and sow not among thorns.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 4, E'Circumcise yourselves to the LORD, and take away the foreskins of your heart, ye men of Judah and inhabitants of Jerusalem: lest my fury come forth like fire, and burn that none can quench it, because of the evil of your doings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 5, E'Declare ye in Judah, and publish in Jerusalem; and say, Blow ye the trumpet in the land: cry, gather together, and say, Assemble yourselves, and let us go into the defenced cities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 6, E'Set up the standard toward Zion: retire, stay not: for I will bring evil from the north, and a great destruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 7, E'The lion is come up from his thicket, and the destroyer of the Gentiles is on his way; he is gone forth from his place to make thy land desolate; and thy cities shall be laid waste, without an inhabitant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 8, E'For this gird you with sackcloth, lament and howl: for the fierce anger of the LORD is not turned back from us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 9, E'And it shall come to pass at that day, saith the LORD, that the heart of the king shall perish, and the heart of the princes; and the priests shall be astonished, and the prophets shall wonder.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 10, E'Then said I, Ah, Lord GOD! surely thou hast greatly deceived this people and Jerusalem, saying, Ye shall have peace; whereas the sword reacheth unto the soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 11, E'At that time shall it be said to this people and to Jerusalem, A dry wind of the high places in the wilderness toward the daughter of my people, not to fan, nor to cleanse,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 12, E'Even a full wind from those places shall come unto me: now also will I give sentence against them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 13, E'Behold, he shall come up as clouds, and his chariots shall be as a whirlwind: his horses are swifter than eagles. Woe unto us! for we are spoiled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 14, E'O Jerusalem, wash thine heart from wickedness, that thou mayest be saved. How long shall thy vain thoughts lodge within thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 15, E'For a voice declareth from Dan, and publisheth affliction from mount Ephraim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 16, E'Make ye mention to the nations; behold, publish against Jerusalem, that watchers come from a far country, and give out their voice against the cities of Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 17, E'As keepers of a field, are they against her round about; because she hath been rebellious against me, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 18, E'Thy way and thy doings have procured these things unto thee; this is thy wickedness, because it is bitter, because it reacheth unto thine heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 19, E'My bowels, my bowels! I am pained at my very heart; my heart maketh a noise in me; I cannot hold my peace, because thou hast heard, O my soul, the sound of the trumpet, the alarm of war.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Jeremiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 20, E'Destruction upon destruction is cried; for the whole land is spoiled: suddenly are my tents spoiled, and my curtains in a moment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 21, E'How long shall I see the standard, and hear the sound of the trumpet?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 22, E'For my people is foolish, they have not known me; they are sottish children, and they have none understanding: they are wise to do evil, but to do good they have no knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 23, E'I beheld the earth, and, lo, it was without form, and void; and the heavens, and they had no light.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 24, E'I beheld the mountains, and, lo, they trembled, and all the hills moved lightly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 25, E'I beheld, and, lo, there was no man, and all the birds of the heavens were fled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 26, E'I beheld, and, lo, the fruitful place was a wilderness, and all the cities thereof were broken down at the presence of the LORD, and by his fierce anger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 27, E'For thus hath the LORD said, The whole land shall be desolate; yet will I not make a full end.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 28, E'For this shall the earth mourn, and the heavens above be black: because I have spoken it, I have purposed it, and will not repent, neither will I turn back from it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 29, E'The whole city shall flee for the noise of the horsemen and bowmen; they shall go into thickets, and climb up upon the rocks: every city shall be forsaken, and not a man dwell therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 30, E'And when thou art spoiled, what wilt thou do? Though thou clothest thyself with crimson, though thou deckest thee with ornaments of gold, though thou rentest thy face with painting, in vain shalt thou make thyself fair; thy lovers will despise thee, they will seek thy life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 4, 31, E'For I have heard a voice as of a woman in travail, and the anguish as of her that bringeth forth her first child, the voice of the daughter of Zion, that bewaileth herself, that spreadeth her hands, saying, Woe is me now! for my soul is wearied because of murderers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 1, E'Run ye to and fro through the streets of Jerusalem, and see now, and know, and seek in the broad places thereof, if ye can find a man, if there be any that executeth judgment, that seeketh the truth; and I will pardon it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 2, E'And though they say, The LORD liveth; surely they swear falsely.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 3, E'O LORD, are not thine eyes upon the truth? thou hast stricken them, but they have not grieved; thou hast consumed them, but they have refused to receive correction: they have made their faces harder than a rock; they have refused to return.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 4, E'Therefore I said, Surely these are poor; they are foolish: for they know not the way of the LORD, nor the judgment of their God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 5, E'I will get me unto the great men, and will speak unto them; for they have known the way of the LORD, and the judgment of their God: but these have altogether broken the yoke, and burst the bonds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 6, E'Wherefore a lion out of the forest shall slay them, and a wolf of the evenings shall spoil them, a leopard shall watch over their cities: every one that goeth out thence shall be torn in pieces: because their transgressions are many, and their backslidings are increased.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 7, E'How shall I pardon thee for this? thy children have forsaken me, and sworn by them that are no gods: when I had fed them to the full, they then committed adultery, and assembled themselves by troops in the harlotsâ€™ houses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 8, E'They were as fed horses in the morning: every one neighed after his neighbourâ€™s wife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 9, E'Shall I not visit for these things? saith the LORD: and shall not my soul be avenged on such a nation as this?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 10, E'Go ye up upon her walls, and destroy; but make not a full end: take away her battlements; for they are not the LORDâ€™s.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 11, E'For the house of Israel and the house of Judah have dealt very treacherously against me, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 12, E'They have belied the LORD, and said, It is not he; neither shall evil come upon us; neither shall we see sword nor famine:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 13, E'And the prophets shall become wind, and the word is not in them: thus shall it be done unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 14, E'Wherefore thus saith the LORD God of hosts, Because ye speak this word, behold, I will make my words in thy mouth fire, and this people wood, and it shall devour them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 15, E'Lo, I will bring a nation upon you from far, O house of Israel, saith the LORD: it is a mighty nation, it is an ancient nation, a nation whose language thou knowest not, neither understandest what they say.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 16, E'Their quiver is as an open sepulchre, they are all mighty men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 17, E'And they shall eat up thine harvest, and thy bread, which thy sons and thy daughters should eat: they shall eat up thy flocks and thine herds: they shall eat up thy vines and thy fig trees: they shall impoverish thy fenced cities, wherein thou trustedst, with the sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 18, E'Nevertheless in those days, saith the LORD, I will not make a full end with you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 19, E'And it shall come to pass, when ye shall say, Wherefore doeth the LORD our God all these things unto us? then shalt thou answer them, Like as ye have forsaken me, and served strange gods in your land, so shall ye serve strangers in a land that is not yours.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 20, E'Declare this in the house of Jacob, and publish it in Judah, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 21, E'Hear now this, O foolish people, and without understanding; which have eyes, and see not; which have ears, and hear not:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 22, E'Fear ye not me? saith the LORD: will ye not tremble at my presence, which have placed the sand for the bound of the sea by a perpetual decree, that it cannot pass it: and though the waves thereof toss themselves, yet can they not prevail; though they roar, yet can they not pass over it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 23, E'But this people hath a revolting and a rebellious heart; they are revolted and gone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 24, E'Neither say they in their heart, Let us now fear the LORD our God, that giveth rain, both the former and the latter, in his season: he reserveth unto us the appointed weeks of the harvest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 25, E'Your iniquities have turned away these things, and your sins have withholden good things from you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 26, E'For among my people are found wicked men: they lay wait, as he that setteth snares; they set a trap, they catch men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 27, E'As a cage is full of birds, so are their houses full of deceit: therefore they are become great, and waxen rich.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 28, E'They are waxen fat, they shine: yea, they overpass the deeds of the wicked: they judge not the cause, the cause of the fatherless, yet they prosper; and the right of the needy do they not judge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 29, E'Shall I not visit for these things? saith the LORD: shall not my soul be avenged on such a nation as this?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 30, E'A wonderful and horrible thing is committed in the land;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 5, 31, E'The prophets prophesy falsely, and the priests bear rule by their means; and my people love to have it so: and what will ye do in the end thereof?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 1, E'O ye children of Benjamin, gather yourselves to flee out of the midst of Jerusalem, and blow the trumpet in Tekoa, and set up a sign of fire in Bethhaccerem: for evil appeareth out of the north, and great destruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 2, E'I have likened the daughter of Zion to a comely and delicate woman.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 3, E'The shepherds with their flocks shall come unto her; they shall pitch their tents against her round about; they shall feed every one in his place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 4, E'Prepare ye war against her; arise, and let us go up at noon. Woe unto us! for the day goeth away, for the shadows of the evening are stretched out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 5, E'Arise, and let us go by night, and let us destroy her palaces.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 6, E'For thus hath the LORD of hosts said, Hew ye down trees, and cast a mount against Jerusalem: this is the city to be visited; she is wholly oppression in the midst of her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 7, E'As a fountain casteth out her waters, so she casteth out her wickedness: violence and spoil is heard in her; before me continually is grief and wounds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 8, E'Be thou instructed, O Jerusalem, lest my soul depart from thee; lest I make thee desolate, a land not inhabited.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 9, E'Thus saith the LORD of hosts, They shall throughly glean the remnant of Israel as a vine: turn back thine hand as a grapegatherer into the baskets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 10, E'To whom shall I speak, and give warning, that they may hear? behold, their ear is uncircumcised, and they cannot hearken: behold, the word of the LORD is unto them a reproach; they have no delight in it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 11, E'Therefore I am full of the fury of the LORD; I am weary with holding in: I will pour it out upon the children abroad, and upon the assembly of young men together: for even the husband with the wife shall be taken, the aged with him that is full of days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 12, E'And their houses shall be turned unto others, with their fields and wives together: for I will stretch out my hand upon the inhabitants of the land, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 13, E'For from the least of them even unto the greatest of them every one is given to covetousness; and from the prophet even unto the priest every one dealeth falsely.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 14, E'They have healed also the hurt of the daughter of my people slightly, saying, Peace, peace; when there is no peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 15, E'Were they ashamed when they had committed abomination? nay, they were not at all ashamed, neither could they blush: therefore they shall fall among them that fall: at the time that I visit them they shall be cast down, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 16, E'Thus saith the LORD, Stand ye in the ways, and see, and ask for the old paths, where is the good way, and walk therein, and ye shall find rest for your souls. But they said, We will not walk therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 17, E'Also I set watchmen over you, saying, Hearken to the sound of the trumpet. But they said, We will not hearken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 18, E'Therefore hear, ye nations, and know, O congregation, what is among them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 19, E'Hear, O earth: behold, I will bring evil upon this people, even the fruit of their thoughts, because they have not hearkened unto my words, nor to my law, but rejected it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 20, E'To what purpose cometh there to me incense from Sheba, and the sweet cane from a far country? your burnt offerings are not acceptable, nor your sacrifices sweet unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 21, E'Therefore thus saith the LORD, Behold, I will lay stumblingblocks before this people, and the fathers and the sons together shall fall upon them; the neighbour and his friend shall perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 22, E'Thus saith the LORD, Behold, a people cometh from the north country, and a great nation shall be raised from the sides of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 23, E'They shall lay hold on bow and spear; they are cruel, and have no mercy; their voice roareth like the sea; and they ride upon horses, set in array as men for war against thee, O daughter of Zion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 24, E'We have heard the fame thereof: our hands wax feeble: anguish hath taken hold of us, and pain, as of a woman in travail.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 25, E'Go not forth into the field, nor walk by the way; for the sword of the enemy and fear is on every side.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 26, E'O daughter of my people, gird thee with sackcloth, and wallow thyself in ashes: make thee mourning, as for an only son, most bitter lamentation: for the spoiler shall suddenly come upon us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 27, E'I have set thee for a tower and a fortress among my people, that thou mayest know and try their way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 28, E'They are all grievous revolters, walking with slanders: they are brass and iron; they are all corrupters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 29, E'The bellows are burned, the lead is consumed of the fire; the founder melteth in vain: for the wicked are not plucked away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 6, 30, E'Reprobate silver shall men call them, because the LORD hath rejected them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 1, E'The word that came to Jeremiah from the LORD, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 2, E'Stand in the gate of the LORDâ€™s house, and proclaim there this word, and say, Hear the word of the LORD, all ye of Judah, that enter in at these gates to worship the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 3, E'Thus saith the LORD of hosts, the God of Israel, Amend your ways and your doings, and I will cause you to dwell in this place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 4, E'Trust ye not in lying words, saying, The temple of the LORD, The temple of the LORD, The temple of the LORD, are these.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 5, E'For if ye throughly amend your ways and your doings; if ye throughly execute judgment between a man and his neighbour;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 6, E'If ye oppress not the stranger, the fatherless, and the widow, and shed not innocent blood in this place, neither walk after other gods to your hurt:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 7, E'Then will I cause you to dwell in this place, in the land that I gave to your fathers, for ever and ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 8, E'Behold, ye trust in lying words, that cannot profit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 9, E'Will ye steal, murder, and commit adultery, and swear falsely, and burn incense unto Baal, and walk after other gods whom ye know not;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 10, E'And come and stand before me in this house, which is called by my name, and say, We are delivered to do all these abominations?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 11, E'Is this house, which is called by my name, become a den of robbers in your eyes? Behold, even I have seen it, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 12, E'But go ye now unto my place which was in Shiloh, where I set my name at the first, and see what I did to it for the wickedness of my people Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 13, E'And now, because ye have done all these works, saith the LORD, and I spake unto you, rising up early and speaking, but ye heard not; and I called you, but ye answered not;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 14, E'Therefore will I do unto this house, which is called by my name, wherein ye trust, and unto the place which I gave to you and to your fathers, as I have done to Shiloh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 15, E'And I will cast you out of my sight, as I have cast out all your brethren, even the whole seed of Ephraim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 16, E'Therefore pray not thou for this people, neither lift up cry nor prayer for them, neither make intercession to me: for I will not hear thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 17, E'Seest thou not what they do in the cities of Judah and in the streets of Jerusalem?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 18, E'The children gather wood, and the fathers kindle the fire, and the women knead their dough, to make cakes to the queen of heaven, and to pour out drink offerings unto other gods, that they may provoke me to anger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 19, E'Do they provoke me to anger? saith the LORD: do they not provoke themselves to the confusion of their own faces?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 20, E'Therefore thus saith the Lord GOD; Behold, mine anger and my fury shall be poured out upon this place, upon man, and upon beast, and upon the trees of the field, and upon the fruit of the ground; and it shall burn, and shall not be quenched.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 21, E'Thus saith the LORD of hosts, the God of Israel; Put your burnt offerings unto your sacrifices, and eat flesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 22, E'For I spake not unto your fathers, nor commanded them in the day that I brought them out of the land of Egypt, concerning burnt offerings or sacrifices:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 23, E'But this thing commanded I them, saying, Obey my voice, and I will be your God, and ye shall be my people: and walk ye in all the ways that I have commanded you, that it may be well unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 24, E'But they hearkened not, nor inclined their ear, but walked in the counsels and in the imagination of their evil heart, and went backward, and not forward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 25, E'Since the day that your fathers came forth out of the land of Egypt unto this day I have even sent unto you all my servants the prophets, daily rising up early and sending them:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 26, E'Yet they hearkened not unto me, nor inclined their ear, but hardened their neck: they did worse than their fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 27, E'Therefore thou shalt speak all these words unto them; but they will not hearken to thee: thou shalt also call unto them; but they will not answer thee.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Jeremiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 28, E'But thou shalt say unto them, This is a nation that obeyeth not the voice of the LORD their God, nor receiveth correction: truth is perished, and is cut off from their mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 29, E'Cut off thine hair, O Jerusalem, and cast it away, and take up a lamentation on high places; for the LORD hath rejected and forsaken the generation of his wrath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 30, E'For the children of Judah have done evil in my sight, saith the LORD: they have set their abominations in the house which is called by my name, to pollute it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 31, E'And they have built the high places of Tophet, which is in the valley of the son of Hinnom, to burn their sons and their daughters in the fire; which I commanded them not, neither came it into my heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 32, E'Therefore, behold, the days come, saith the LORD, that it shall no more be called Tophet, nor the valley of the son of Hinnom, but the valley of slaughter: for they shall bury in Tophet, till there be no place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 33, E'And the carcases of this people shall be meat for the fowls of the heaven, and for the beasts of the earth; and none shall fray them away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 7, 34, E'Then will I cause to cease from the cities of Judah, and from the streets of Jerusalem, the voice of mirth, and the voice of gladness, the voice of the bridegroom, and the voice of the bride: for the land shall be desolate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 8, 1, E'At that time, saith the LORD, they shall bring out the bones of the kings of Judah, and the bones of his princes, and the bones of the priests, and the bones of the prophets, and the bones of the inhabitants of Jerusalem, out of their graves:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 8, 2, E'And they shall spread them before the sun, and the moon, and all the host of heaven, whom they have loved, and whom they have served, and after whom they have walked, and whom they have sought, and whom they have worshipped: they shall not be gathered, nor be buried; they shall be for dung upon the face of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 8, 3, E'And death shall be chosen rather than life by all the residue of them that remain of this evil family, which remain in all the places whither I have driven them, saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 8, 4, E'Moreover thou shalt say unto them, Thus saith the LORD; Shall they fall, and not arise? shall he turn away, and not return?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 8, 5, E'Why then is this people of Jerusalem slidden back by a perpetual backsliding? they hold fast deceit, they refuse to return.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 8, 6, E'I hearkened and heard, but they spake not aright: no man repented him of his wickedness, saying, What have I done? every one turned to his course, as the horse rusheth into the battle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 8, 7, E'Yea, the stork in the heaven knoweth her appointed times; and the turtle and the crane and the swallow observe the time of their coming; but my people know not the judgment of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 8, 8, E'How do ye say, We are wise, and the law of the LORD is with us? Lo, certainly in vain made he it; the pen of the scribes is in vain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 8, 9, E'The wise men are ashamed, they are dismayed and taken: lo, they have rejected the word of the LORD; and what wisdom is in them?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 8, 10, E'Therefore will I give their wives unto others, and their fields to them that shall inherit them: for every one from the least even unto the greatest is given to covetousness, from the prophet even unto the priest every one dealeth falsely.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 8, 11, E'For they have healed the hurt of the daughter of my people slightly, saying, Peace, peace; when there is no peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 8, 12, E'Were they ashamed when they had committed abomination? nay, they were not at all ashamed, neither could they blush: therefore shall they fall among them that fall: in the time of their visitation they shall be cast down, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 8, 13, E'I will surely consume them, saith the LORD: there shall be no grapes on the vine, nor figs on the fig tree, and the leaf shall fade; and the things that I have given them shall pass away from them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 8, 14, E'Why do we sit still? assemble yourselves, and let us enter into the defenced cities, and let us be silent there: for the LORD our God hath put us to silence, and given us water of gall to drink, because we have sinned against the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 8, 15, E'We looked for peace, but no good came; and for a time of health, and behold trouble!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 8, 16, E'The snorting of his horses was heard from Dan: the whole land trembled at the sound of the neighing of his strong ones; for they are come, and have devoured the land, and all that is in it; the city, and those that dwell therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 8, 17, E'For, behold, I will send serpents, cockatrices, among you, which will not be charmed, and they shall bite you, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 8, 18, E'When I would comfort myself against sorrow, my heart is faint in me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 8, 19, E'Behold the voice of the cry of the daughter of my people because of them that dwell in a far country: Is not the LORD in Zion? is not her king in her? Why have they provoked me to anger with their graven images, and with strange vanities?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 8, 20, E'The harvest is past, the summer is ended, and we are not saved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 8, 21, E'For the hurt of the daughter of my people am I hurt; I am black; astonishment hath taken hold on me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 8, 22, E'Is there no balm in Gilead; is there no physician there? why then is not the health of the daughter of my people recovered?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 1, E'Oh that my head were waters, and mine eyes a fountain of tears, that I might weep day and night for the slain of the daughter of my people!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 2, E'Oh that I had in the wilderness a lodging place of wayfaring men; that I might leave my people, and go from them! for they be all adulterers, an assembly of treacherous men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 3, E'And they bend their tongues like their bow for lies: but they are not valiant for the truth upon the earth; for they proceed from evil to evil, and they know not me, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 4, E'Take ye heed every one of his neighbour, and trust ye not in any brother: for every brother will utterly supplant, and every neighbour will walk with slanders.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 5, E'And they will deceive every one his neighbour, and will not speak the truth: they have taught their tongue to speak lies, and weary themselves to commit iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 6, E'Thine habitation is in the midst of deceit; through deceit they refuse to know me, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 7, E'Therefore thus saith the LORD of hosts, Behold, I will melt them, and try them; for how shall I do for the daughter of my people?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 8, E'Their tongue is as an arrow shot out; it speaketh deceit: one speaketh peaceably to his neighbour with his mouth, but in heart he layeth his wait.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 9, E'Shall I not visit them for these things? saith the LORD: shall not my soul be avenged on such a nation as this?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 10, E'For the mountains will I take up a weeping and wailing, and for the habitations of the wilderness a lamentation, because they are burned up, so that none can pass through them; neither can men hear the voice of the cattle; both the fowl of the heavens and the beast are fled; they are gone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 11, E'And I will make Jerusalem heaps, and a den of dragons; and I will make the cities of Judah desolate, without an inhabitant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 12, E'Who is the wise man, that may understand this? and who is he to whom the mouth of the LORD hath spoken, that he may declare it, for what the land perisheth and is burned up like a wilderness, that none passeth through?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 13, E'And the LORD saith, Because they have forsaken my law which I set before them, and have not obeyed my voice, neither walked therein;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 14, E'But have walked after the imagination of their own heart, and after Baalim, which their fathers taught them:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 15, E'Therefore thus saith the LORD of hosts, the God of Israel; Behold, I will feed them, even this people, with wormwood, and give them water of gall to drink.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 16, E'I will scatter them also among the heathen, whom neither they nor their fathers have known: and I will send a sword after them, till I have consumed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 17, E'Thus saith the LORD of hosts, Consider ye, and call for the mourning women, that they may come; and send for cunning women, that they may come:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 18, E'And let them make haste, and take up a wailing for us, that our eyes may run down with tears, and our eyelids gush out with waters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 19, E'For a voice of wailing is heard out of Zion, How are we spoiled! we are greatly confounded, because we have forsaken the land, because our dwellings have cast us out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 20, E'Yet hear the word of the LORD, O ye women, and let your ear receive the word of his mouth, and teach your daughters wailing, and every one her neighbour lamentation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 21, E'For death is come up into our windows, and is entered into our palaces, to cut off the children from without, and the young men from the streets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 22, E'Speak, Thus saith the LORD, Even the carcases of men shall fall as dung upon the open field, and as the handful after the harvestman, and none shall gather them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 23, E'Thus saith the LORD, Let not the wise man glory in his wisdom, neither let the mighty man glory in his might, let not the rich man glory in his riches:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 24, E'But let him that glorieth glory in this, that he understandeth and knoweth me, that I am the LORD which exercise lovingkindness, judgment, and righteousness, in the earth: for in these things I delight, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 25, E'Behold, the days come, saith the LORD, that I will punish all them which are circumcised with the uncircumcised;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 9, 26, E'Egypt, and Judah, and Edom, and the children of Ammon, and Moab, and all that are in the utmost corners, that dwell in the wilderness: for all these nations are uncircumcised, and all the house of Israel are uncircumcised in the heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 1, E'Hear ye the word which the LORD speaketh unto you, O house of Israel:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 2, E'Thus saith the LORD, Learn not the way of the heathen, and be not dismayed at the signs of heaven; for the heathen are dismayed at them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 3, E'For the customs of the people are vain: for one cutteth a tree out of the forest, the work of the hands of the workman, with the axe.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 4, E'They deck it with silver and with gold; they fasten it with nails and with hammers, that it move not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 5, E'They are upright as the palm tree, but speak not: they must needs be borne, because they cannot go. Be not afraid of them; for they cannot do evil, neither also is it in them to do good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 6, E'Forasmuch as there is none like unto thee, O LORD; thou art great, and thy name is great in might.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 7, E'Who would not fear thee, O King of nations? for to thee doth it appertain: forasmuch as among all the wise men of the nations, and in all their kingdoms, there is none like unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 8, E'But they are altogether brutish and foolish: the stock is a doctrine of vanities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 9, E'Silver spread into plates is brought from Tarshish, and gold from Uphaz, the work of the workman, and of the hands of the founder: blue and purple is their clothing: they are all the work of cunning men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 10, E'But the LORD is the true God, he is the living God, and an everlasting king: at his wrath the earth shall tremble, and the nations shall not be able to abide his indignation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 11, E'Thus shall ye say unto them, The gods that have not made the heavens and the earth, even they shall perish from the earth, and from under these heavens.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 12, E'He hath made the earth by his power, he hath established the world by his wisdom, and hath stretched out the heavens by his discretion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 13, E'When he uttereth his voice, there is a multitude of waters in the heavens, and he causeth the vapours to ascend from the ends of the earth; he maketh lightnings with rain, and bringeth forth the wind out of his treasures.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 14, E'Every man is brutish in his knowledge: every founder is confounded by the graven image: for his molten image is falsehood, and there is no breath in them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 15, E'They are vanity, and the work of errors: in the time of their visitation they shall perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 16, E'The portion of Jacob is not like them: for he is the former of all things; and Israel is the rod of his inheritance: The LORD of hosts is his name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 17, E'Gather up thy wares out of the land, O inhabitant of the fortress.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 18, E'For thus saith the LORD, Behold, I will sling out the inhabitants of the land at this once, and will distress them, that they may find it so.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 19, E'Woe is me for my hurt! my wound is grievous: but I said, Truly this is a grief, and I must bear it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 20, E'My tabernacle is spoiled, and all my cords are broken: my children are gone forth of me, and they are not: there is none to stretch forth my tent any more, and to set up my curtains.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 21, E'For the pastors are become brutish, and have not sought the LORD: therefore they shall not prosper, and all their flocks shall be scattered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 22, E'Behold, the noise of the bruit is come, and a great commotion out of the north country, to make the cities of Judah desolate, and a den of dragons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 23, E'O LORD, I know that the way of man is not in himself: it is not in man that walketh to direct his steps.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 24, E'O LORD, correct me, but with judgment; not in thine anger, lest thou bring me to nothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 10, 25, E'Pour out thy fury upon the heathen that know thee not, and upon the families that call not on thy name: for they have eaten up Jacob, and devoured him, and consumed him, and have made his habitation desolate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 11, 1, E'The word that came to Jeremiah from the LORD, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 11, 2, E'Hear ye the words of this covenant, and speak unto the men of Judah, and to the inhabitants of Jerusalem;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 11, 3, E'And say thou unto them, Thus saith the LORD God of Israel; Cursed be the man that obeyeth not the words of this covenant,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 11, 4, E'Which I commanded your fathers in the day that I brought them forth out of the land of Egypt, from the iron furnace, saying, Obey my voice, and do them, according to all which I command you: so shall ye be my people, and I will be your God:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 11, 5, E'That I may perform the oath which I have sworn unto your fathers, to give them a land flowing with milk and honey, as it is this day. Then answered I, and said, So be it, O LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 11, 6, E'Then the LORD said unto me, Proclaim all these words in the cities of Judah, and in the streets of Jerusalem, saying, Hear ye the words of this covenant, and do them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 11, 7, E'For I earnestly protested unto your fathers in the day that I brought them up out of the land of Egypt, even unto this day, rising early and protesting, saying, Obey my voice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 11, 8, E'Yet they obeyed not, nor inclined their ear, but walked every one in the imagination of their evil heart: therefore I will bring upon them all the words of this covenant, which I commanded them to do: but they did them not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 11, 9, E'And the LORD said unto me, A conspiracy is found among the men of Judah, and among the inhabitants of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 11, 10, E'They are turned back to the iniquities of their forefathers, which refused to hear my words; and they went after other gods to serve them: the house of Israel and the house of Judah have broken my covenant which I made with their fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 11, 11, E'Therefore thus saith the LORD, Behold, I will bring evil upon them, which they shall not be able to escape; and though they shall cry unto me, I will not hearken unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 11, 12, E'Then shall the cities of Judah and inhabitants of Jerusalem go, and cry unto the gods unto whom they offer incense: but they shall not save them at all in the time of their trouble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 11, 13, E'For according to the number of thy cities were thy gods, O Judah; and according to the number of the streets of Jerusalem have ye set up altars to that shameful thing, even altars to burn incense unto Baal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 11, 14, E'Therefore pray not thou for this people, neither lift up a cry or prayer for them: for I will not hear them in the time that they cry unto me for their trouble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 11, 15, E'What hath my beloved to do in mine house, seeing she hath wrought lewdness with many, and the holy flesh is passed from thee? when thou doest evil, then thou rejoicest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 11, 16, E'The LORD called thy name, A green olive tree, fair, and of goodly fruit: with the noise of a great tumult he hath kindled fire upon it, and the branches of it are broken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 11, 17, E'For the LORD of hosts, that planted thee, hath pronounced evil against thee, for the evil of the house of Israel and of the house of Judah, which they have done against themselves to provoke me to anger in offering incense unto Baal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 11, 18, E'And the LORD hath given me knowledge of it, and I know it: then thou shewedst me their doings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 11, 19, E'But I was like a lamb or an ox that is brought to the slaughter; and I knew not that they had devised devices against me, saying, Let us destroy the tree with the fruit thereof, and let us cut him off from the land of the living, that his name may be no more remembered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 11, 20, E'But, O LORD of hosts, that judgest righteously, that triest the reins and the heart, let me see thy vengeance on them: for unto thee have I revealed my cause.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Jeremiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 11, 21, E'Therefore thus saith the LORD of the men of Anathoth, that seek thy life, saying, Prophesy not in the name of the LORD, that thou die not by our hand:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 11, 22, E'Therefore thus saith the LORD of hosts, Behold, I will punish them: the young men shall die by the sword; their sons and their daughters shall die by famine:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 11, 23, E'And there shall be no remnant of them: for I will bring evil upon the men of Anathoth, even the year of their visitation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 12, 1, E'Righteous art thou, O LORD, when I plead with thee: yet let me talk with thee of thy judgments: Wherefore doth the way of the wicked prosper? wherefore are all they happy that deal very treacherously?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 12, 2, E'Thou hast planted them, yea, they have taken root: they grow, yea, they bring forth fruit: thou art near in their mouth, and far from their reins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 12, 3, E'But thou, O LORD, knowest me: thou hast seen me, and tried mine heart toward thee: pull them out like sheep for the slaughter, and prepare them for the day of slaughter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 12, 4, E'How long shall the land mourn, and the herbs of every field wither, for the wickedness of them that dwell therein? the beasts are consumed, and the birds; because they said, He shall not see our last end.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 12, 5, E'If thou hast run with the footmen, and they have wearied thee, then how canst thou contend with horses? and if in the land of peace, wherein thou trustedst, they wearied thee, then how wilt thou do in the swelling of Jordan?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 12, 6, E'For even thy brethren, and the house of thy father, even they have dealt treacherously with thee; yea, they have called a multitude after thee: believe them not, though they speak fair words unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 12, 7, E'I have forsaken mine house, I have left mine heritage; I have given the dearly beloved of my soul into the hand of her enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 12, 8, E'Mine heritage is unto me as a lion in the forest; it crieth out against me: therefore have I hated it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 12, 9, E'Mine heritage is unto me as a speckled bird, the birds round about are against her; come ye, assemble all the beasts of the field, come to devour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 12, 10, E'Many pastors have destroyed my vineyard, they have trodden my portion under foot, they have made my pleasant portion a desolate wilderness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 12, 11, E'They have made it desolate, and being desolate it mourneth unto me; the whole land is made desolate, because no man layeth it to heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 12, 12, E'The spoilers are come upon all high places through the wilderness: for the sword of the LORD shall devour from the one end of the land even to the other end of the land: no flesh shall have peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 12, 13, E'They have sown wheat, but shall reap thorns: they have put themselves to pain, but shall not profit: and they shall be ashamed of your revenues because of the fierce anger of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 12, 14, E'Thus saith the LORD against all mine evil neighbours, that touch the inheritance which I have caused my people Israel to inherit; Behold, I will pluck them out of their land, and pluck out the house of Judah from among them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 12, 15, E'And it shall come to pass, after that I have plucked them out I will return, and have compassion on them, and will bring them again, every man to his heritage, and every man to his land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 12, 16, E'And it shall come to pass, if they will diligently learn the ways of my people, to swear by my name, The LORD liveth; as they taught my people to swear by Baal; then shall they be built in the midst of my people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 12, 17, E'But if they will not obey, I will utterly pluck up and destroy that nation, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 1, E'Thus saith the LORD unto me, Go and get thee a linen girdle, and put it upon thy loins, and put it not in water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 2, E'So I got a girdle according to the word of the LORD, and put it on my loins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 3, E'And the word of the LORD came unto me the second time, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 4, E'Take the girdle that thou hast got, which is upon thy loins, and arise, go to Euphrates, and hide it there in a hole of the rock.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 5, E'So I went, and hid it by Euphrates, as the LORD commanded me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 6, E'And it came to pass after many days, that the LORD said unto me, Arise, go to Euphrates, and take the girdle from thence, which I commanded thee to hide there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 7, E'Then I went to Euphrates, and digged, and took the girdle from the place where I had hid it: and, behold, the girdle was marred, it was profitable for nothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 8, E'Then the word of the LORD came unto me, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 9, E'Thus saith the LORD, After this manner will I mar the pride of Judah, and the great pride of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 10, E'This evil people, which refuse to hear my words, which walk in the imagination of their heart, and walk after other gods, to serve them, and to worship them, shall even be as this girdle, which is good for nothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 11, E'For as the girdle cleaveth to the loins of a man, so have I caused to cleave unto me the whole house of Israel and the whole house of Judah, saith the LORD; that they might be unto me for a people, and for a name, and for a praise, and for a glory: but they would not hear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 12, E'Therefore thou shalt speak unto them this word; Thus saith the LORD God of Israel, Every bottle shall be filled with wine: and they shall say unto thee, Do we not certainly know that every bottle shall be filled with wine?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 13, E'Then shalt thou say unto them, Thus saith the LORD, Behold, I will fill all the inhabitants of this land, even the kings that sit upon Davidâ€™s throne, and the priests, and the prophets, and all the inhabitants of Jerusalem, with drunkenness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 14, E'And I will dash them one against another, even the fathers and the sons together, saith the LORD: I will not pity, nor spare, nor have mercy, but destroy them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 15, E'Hear ye, and give ear; be not proud: for the LORD hath spoken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 16, E'Give glory to the LORD your God, before he cause darkness, and before your feet stumble upon the dark mountains, and, while ye look for light, he turn it into the shadow of death, and make it gross darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 17, E'But if ye will not hear it, my soul shall weep in secret places for your pride; and mine eye shall weep sore, and run down with tears, because the LORDâ€™s flock is carried away captive.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 18, E'Say unto the king and to the queen, Humble yourselves, sit down: for your principalities shall come down, even the crown of your glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 19, E'The cities of the south shall be shut up, and none shall open them: Judah shall be carried away captive all of it, it shall be wholly carried away captive.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 20, E'Lift up your eyes, and behold them that come from the north: where is the flock that was given thee, thy beautiful flock?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 21, E'What wilt thou say when he shall punish thee? for thou hast taught them to be captains, and as chief over thee: shall not sorrows take thee, as a woman in travail?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 22, E'And if thou say in thine heart, Wherefore come these things upon me? For the greatness of thine iniquity are thy skirts discovered, and thy heels made bare.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 23, E'Can the Ethiopian change his skin, or the leopard his spots? then may ye also do good, that are accustomed to do evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 24, E'Therefore will I scatter them as the stubble that passeth away by the wind of the wilderness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 25, E'This is thy lot, the portion of thy measures from me, saith the LORD; because thou hast forgotten me, and trusted in falsehood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 26, E'Therefore will I discover thy skirts upon thy face, that thy shame may appear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 13, 27, E'I have seen thine adulteries, and thy neighings, the lewdness of thy whoredom, and thine abominations on the hills in the fields. Woe unto thee, O Jerusalem! wilt thou not be made clean? when shall it once be?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 14, 1, E'The word of the LORD that came to Jeremiah concerning the dearth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 14, 2, E'Judah mourneth, and the gates thereof languish; they are black unto the ground; and the cry of Jerusalem is gone up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 14, 3, E'And their nobles have sent their little ones to the waters: they came to the pits, and found no water; they returned with their vessels empty; they were ashamed and confounded, and covered their heads.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 14, 4, E'Because the ground is chapt, for there was no rain in the earth, the plowmen were ashamed, they covered their heads.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 14, 5, E'Yea, the hind also calved in the field, and forsook it, because there was no grass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 14, 6, E'And the wild asses did stand in the high places, they snuffed up the wind like dragons; their eyes did fail, because there was no grass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 14, 7, E'O LORD, though our iniquities testify against us, do thou it for thy nameâ€™s sake: for our backslidings are many; we have sinned against thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 14, 8, E'O the hope of Israel, the saviour thereof in time of trouble, why shouldest thou be as a stranger in the land, and as a wayfaring man that turneth aside to tarry for a night?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 14, 9, E'Why shouldest thou be as a man astonied, as a mighty man that cannot save? yet thou, O LORD, art in the midst of us, and we are called by thy name; leave us not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 14, 10, E'Thus saith the LORD unto this people, Thus have they loved to wander, they have not refrained their feet, therefore the LORD doth not accept them; he will now remember their iniquity, and visit their sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 14, 11, E'Then said the LORD unto me, Pray not for this people for their good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 14, 12, E'When they fast, I will not hear their cry; and when they offer burnt offering and an oblation, I will not accept them: but I will consume them by the sword, and by the famine, and by the pestilence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 14, 13, E'Then said I, Ah, Lord GOD! behold, the prophets say unto them, Ye shall not see the sword, neither shall ye have famine; but I will give you assured peace in this place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 14, 14, E'Then the LORD said unto me, The prophets prophesy lies in my name: I sent them not, neither have I commanded them, neither spake unto them: they prophesy unto you a false vision and divination, and a thing of nought, and the deceit of their heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 14, 15, E'Therefore thus saith the LORD concerning the prophets that prophesy in my name, and I sent them not, yet they say, Sword and famine shall not be in this land; By sword and famine shall those prophets be consumed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 14, 16, E'And the people to whom they prophesy shall be cast out in the streets of Jerusalem because of the famine and the sword; and they shall have none to bury them, them, their wives, nor their sons, nor their daughters: for I will pour their wickedness upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 14, 17, E'Therefore thou shalt say this word unto them; Let mine eyes run down with tears night and day, and let them not cease: for the virgin daughter of my people is broken with a great breach, with a very grievous blow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 14, 18, E'If I go forth into the field, then behold the slain with the sword! and if I enter into the city, then behold them that are sick with famine! yea, both the prophet and the priest go about into a land that they know not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 14, 19, E'Hast thou utterly rejected Judah? hath thy soul lothed Zion? why hast thou smitten us, and there is no healing for us? we looked for peace, and there is no good; and for the time of healing, and behold trouble!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 14, 20, E'We acknowledge, O LORD, our wickedness, and the iniquity of our fathers: for we have sinned against thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 14, 21, E'Do not abhor us, for thy nameâ€™s sake, do not disgrace the throne of thy glory: remember, break not thy covenant with us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 14, 22, E'Are there any among the vanities of the Gentiles that can cause rain? or can the heavens give showers? art not thou he, O LORD our God? therefore we will wait upon thee: for thou hast made all these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 15, 1, E'Then said the LORD unto me, Though Moses and Samuel stood before me, yet my mind could not be toward this people: cast them out of my sight, and let them go forth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 15, 2, E'And it shall come to pass, if they say unto thee, Whither shall we go forth? then thou shalt tell them, Thus saith the LORD; Such as are for death, to death; and such as are for the sword, to the sword; and such as are for the famine, to the famine; and such as are for the captivity, to the captivity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 15, 3, E'And I will appoint over them four kinds, saith the LORD: the sword to slay, and the dogs to tear, and the fowls of the heaven, and the beasts of the earth, to devour and destroy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 15, 4, E'And I will cause them to be removed into all kingdoms of the earth, because of Manasseh the son of Hezekiah king of Judah, for that which he did in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 15, 5, E'For who shall have pity upon thee, O Jerusalem? or who shall bemoan thee? or who shall go aside to ask how thou doest?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 15, 6, E'Thou hast forsaken me, saith the LORD, thou art gone backward: therefore will I stretch out my hand against thee, and destroy thee; I am weary with repenting.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 15, 7, E'And I will fan them with a fan in the gates of the land; I will bereave them of children, I will destroy my people, since they return not from their ways.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 15, 8, E'Their widows are increased to me above the sand of the seas: I have brought upon them against the mother of the young men a spoiler at noonday: I have caused him to fall upon it suddenly, and terrors upon the city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 15, 9, E'She that hath borne seven languisheth: she hath given up the ghost; her sun is gone down while it was yet day: she hath been ashamed and confounded: and the residue of them will I deliver to the sword before their enemies, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 15, 10, E'Woe is me, my mother, that thou hast borne me a man of strife and a man of contention to the whole earth! I have neither lent on usury, nor men have lent to me on usury; yet every one of them doth curse me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 15, 11, E'The LORD said, Verily it shall be well with thy remnant; verily I will cause the enemy to entreat thee well in the time of evil and in the time of affliction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 15, 12, E'Shall iron break the northern iron and the steel?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 15, 13, E'Thy substance and thy treasures will I give to the spoil without price, and that for all thy sins, even in all thy borders.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 15, 14, E'And I will make thee to pass with thine enemies into a land which thou knowest not: for a fire is kindled in mine anger, which shall burn upon you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 15, 15, E'O LORD, thou knowest: remember me, and visit me, and revenge me of my persecutors; take me not away in thy longsuffering: know that for thy sake I have suffered rebuke.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 15, 16, E'Thy words were found, and I did eat them; and thy word was unto me the joy and rejoicing of mine heart: for I am called by thy name, O LORD God of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 15, 17, E'I sat not in the assembly of the mockers, nor rejoiced; I sat alone because of thy hand: for thou hast filled me with indignation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 15, 18, E'Why is my pain perpetual, and my wound incurable, which refuseth to be healed? wilt thou be altogether unto me as a liar, and as waters that fail?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 15, 19, E'Therefore thus saith the LORD, If thou return, then will I bring thee again, and thou shalt stand before me: and if thou take forth the precious from the vile, thou shalt be as my mouth: let them return unto thee; but return not thou unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 15, 20, E'And I will make thee unto this people a fenced brasen wall: and they shall fight against thee, but they shall not prevail against thee: for I am with thee to save thee and to deliver thee, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 15, 21, E'And I will deliver thee out of the hand of the wicked, and I will redeem thee out of the hand of the terrible.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 16, 1, E'The word of the LORD came also unto me, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 16, 2, E'Thou shalt not take thee a wife, neither shalt thou have sons or daughters in this place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 16, 3, E'For thus saith the LORD concerning the sons and concerning the daughters that are born in this place, and concerning their mothers that bare them, and concerning their fathers that begat them in this land;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 16, 4, E'They shall die of grievous deaths; they shall not be lamented; neither shall they be buried; but they shall be as dung upon the face of the earth: and they shall be consumed by the sword, and by famine; and their carcases shall be meat for the fowls of heaven, and for the beasts of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 16, 5, E'For thus saith the LORD, Enter not into the house of mourning, neither go to lament nor bemoan them: for I have taken away my peace from this people, saith the LORD, even lovingkindness and mercies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 16, 6, E'Both the great and the small shall die in this land: they shall not be buried, neither shall men lament for them, nor cut themselves, nor make themselves bald for them:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 16, 7, E'Neither shall men tear themselves for them in mourning, to comfort them for the dead; neither shall men give them the cup of consolation to drink for their father or for their mother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 16, 8, E'Thou shalt not also go into the house of feasting, to sit with them to eat and to drink.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 16, 9, E'For thus saith the LORD of hosts, the God of Israel; Behold, I will cause to cease out of this place in your eyes, and in your days, the voice of mirth, and the voice of gladness, the voice of the bridegroom, and the voice of the bride.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 16, 10, E'And it shall come to pass, when thou shalt shew this people all these words, and they shall say unto thee, Wherefore hath the LORD pronounced all this great evil against us? or what is our iniquity? or what is our sin that we have committed against the LORD our God?')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Jeremiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 16, 11, E'Then shalt thou say unto them, Because your fathers have forsaken me, saith the LORD, and have walked after other gods, and have served them, and have worshipped them, and have forsaken me, and have not kept my law;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 16, 12, E'And ye have done worse than your fathers; for, behold, ye walk every one after the imagination of his evil heart, that they may not hearken unto me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 16, 13, E'Therefore will I cast you out of this land into a land that ye know not, neither ye nor your fathers; and there shall ye serve other gods day and night; where I will not shew you favour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 16, 14, E'Therefore, behold, the days come, saith the LORD, that it shall no more be said, The LORD liveth, that brought up the children of Israel out of the land of Egypt;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 16, 15, E'But, The LORD liveth, that brought up the children of Israel from the land of the north, and from all the lands whither he had driven them: and I will bring them again into their land that I gave unto their fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 16, 16, E'Behold, I will send for many fishers, saith the LORD, and they shall fish them; and after will I send for many hunters, and they shall hunt them from every mountain, and from every hill, and out of the holes of the rocks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 16, 17, E'For mine eyes are upon all their ways: they are not hid from my face, neither is their iniquity hid from mine eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 16, 18, E'And first I will recompense their iniquity and their sin double; because they have defiled my land, they have filled mine inheritance with the carcases of their detestable and abominable things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 16, 19, E'O LORD, my strength, and my fortress, and my refuge in the day of affliction, the Gentiles shall come unto thee from the ends of the earth, and shall say, Surely our fathers have inherited lies, vanity, and things wherein there is no profit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 16, 20, E'Shall a man make gods unto himself, and they are no gods?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 16, 21, E'Therefore, behold, I will this once cause them to know, I will cause them to know mine hand and my might; and they shall know that my name is The LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 1, E'The sin of Judah is written with a pen of iron, and with the point of a diamond: it is graven upon the table of their heart, and upon the horns of your altars;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 2, E'Whilst their children remember their altars and their groves by the green trees upon the high hills.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 3, E'O my mountain in the field, I will give thy substance and all thy treasures to the spoil, and thy high places for sin, throughout all thy borders.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 4, E'And thou, even thyself, shalt discontinue from thine heritage that I gave thee; and I will cause thee to serve thine enemies in the land which thou knowest not: for ye have kindled a fire in mine anger, which shall burn for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 5, E'Thus saith the LORD; Cursed be the man that trusteth in man, and maketh flesh his arm, and whose heart departeth from the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 6, E'For he shall be like the heath in the desert, and shall not see when good cometh; but shall inhabit the parched places in the wilderness, in a salt land and not inhabited.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 7, E'Blessed is the man that trusteth in the LORD, and whose hope the LORD is.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 8, E'For he shall be as a tree planted by the waters, and that spreadeth out her roots by the river, and shall not see when heat cometh, but her leaf shall be green; and shall not be careful in the year of drought, neither shall cease from yielding fruit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 9, E'The heart is deceitful above all things, and desperately wicked: who can know it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 10, E'I the LORD search the heart, I try the reins, even to give every man according to his ways, and according to the fruit of his doings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 11, E'As the partridge sitteth on eggs, and hatcheth them not; so he that getteth riches, and not by right, shall leave them in the midst of his days, and at his end shall be a fool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 12, E'A glorious high throne from the beginning is the place of our sanctuary.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 13, E'O LORD, the hope of Israel, all that forsake thee shall be ashamed, and they that depart from me shall be written in the earth, because they have forsaken the LORD, the fountain of living waters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 14, E'Heal me, O LORD, and I shall be healed; save me, and I shall be saved: for thou art my praise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 15, E'Behold, they say unto me, Where is the word of the LORD? let it come now.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 16, E'As for me, I have not hastened from being a pastor to follow thee: neither have I desired the woeful day; thou knowest: that which came out of my lips was right before thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 17, E'Be not a terror unto me: thou art my hope in the day of evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 18, E'Let them be confounded that persecute me, but let not me be confounded: let them be dismayed, but let not me be dismayed: bring upon them the day of evil, and destroy them with double destruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 19, E'Thus said the LORD unto me; Go and stand in the gate of the children of the people, whereby the kings of Judah come in, and by the which they go out, and in all the gates of Jerusalem;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 20, E'And say unto them, Hear ye the word of the LORD, ye kings of Judah, and all Judah, and all the inhabitants of Jerusalem, that enter in by these gates:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 21, E'Thus saith the LORD; Take heed to yourselves, and bear no burden on the sabbath day, nor bring it in by the gates of Jerusalem;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 22, E'Neither carry forth a burden out of your houses on the sabbath day, neither do ye any work, but hallow ye the sabbath day, as I commanded your fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 23, E'But they obeyed not, neither inclined their ear, but made their neck stiff, that they might not hear, nor receive instruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 24, E'And it shall come to pass, if ye diligently hearken unto me, saith the LORD, to bring in no burden through the gates of this city on the sabbath day, but hallow the sabbath day, to do no work therein;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 25, E'Then shall there enter into the gates of this city kings and princes sitting upon the throne of David, riding in chariots and on horses, they, and their princes, the men of Judah, and the inhabitants of Jerusalem: and this city shall remain for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 26, E'And they shall come from the cities of Judah, and from the places about Jerusalem, and from the land of Benjamin, and from the plain, and from the mountains, and from the south, bringing burnt offerings, and sacrifices, and meat offerings, and incense, and bringing sacrifices of praise, unto the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 17, 27, E'But if ye will not hearken unto me to hallow the sabbath day, and not to bear a burden, even entering in at the gates of Jerusalem on the sabbath day; then will I kindle a fire in the gates thereof, and it shall devour the palaces of Jerusalem, and it shall not be quenched.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 18, 1, E'The word which came to Jeremiah from the LORD, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 18, 2, E'Arise, and go down to the potterâ€™s house, and there I will cause thee to hear my words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 18, 3, E'Then I went down to the potterâ€™s house, and, behold, he wrought a work on the wheels.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 18, 4, E'And the vessel that he made of clay was marred in the hand of the potter: so he made it again another vessel, as seemed good to the potter to make it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 18, 5, E'Then the word of the LORD came to me, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 18, 6, E'O house of Israel, cannot I do with you as this potter? saith the LORD. Behold, as the clay is in the potterâ€™s hand, so are ye in mine hand, O house of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 18, 7, E'At what instant I shall speak concerning a nation, and concerning a kingdom, to pluck up, and to pull down, and to destroy it;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 18, 8, E'If that nation, against whom I have pronounced, turn from their evil, I will repent of the evil that I thought to do unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 18, 9, E'And at what instant I shall speak concerning a nation, and concerning a kingdom, to build and to plant it;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 18, 10, E'If it do evil in my sight, that it obey not my voice, then I will repent of the good, wherewith I said I would benefit them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 18, 11, E'Now therefore go to, speak to the men of Judah, and to the inhabitants of Jerusalem, saying, Thus saith the LORD; Behold, I frame evil against you, and devise a device against you: return ye now every one from his evil way, and make your ways and your doings good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 18, 12, E'And they said, There is no hope: but we will walk after our own devices, and we will every one do the imagination of his evil heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 18, 13, E'Therefore thus saith the LORD; Ask ye now among the heathen, who hath heard such things: the virgin of Israel hath done a very horrible thing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 18, 14, E'Will a man leave the snow of Lebanon which cometh from the rock of the field? or shall the cold flowing waters that come from another place be forsaken?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 18, 15, E'Because my people hath forgotten me, they have burned incense to vanity, and they have caused them to stumble in their ways from the ancient paths, to walk in paths, in a way not cast up;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 18, 16, E'To make their land desolate, and a perpetual hissing; every one that passeth thereby shall be astonished, and wag his head.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 18, 17, E'I will scatter them as with an east wind before the enemy; I will shew them the back, and not the face, in the day of their calamity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 18, 18, E'Then said they, Come, and let us devise devices against Jeremiah; for the law shall not perish from the priest, nor counsel from the wise, nor the word from the prophet. Come, and let us smite him with the tongue, and let us not give heed to any of his words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 18, 19, E'Give heed to me, O LORD, and hearken to the voice of them that contend with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 18, 20, E'Shall evil be recompensed for good? for they have digged a pit for my soul. Remember that I stood before thee to speak good for them, and to turn away thy wrath from them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 18, 21, E'Therefore deliver up their children to the famine, and pour out their blood by the force of the sword; and let their wives be bereaved of their children, and be widows; and let their men be put to death; let their young men be slain by the sword in battle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 18, 22, E'Let a cry be heard from their houses, when thou shalt bring a troop suddenly upon them: for they have digged a pit to take me, and hid snares for my feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 18, 23, E'Yet, LORD, thou knowest all their counsel against me to slay me: forgive not their iniquity, neither blot out their sin from thy sight, but let them be overthrown before thee; deal thus with them in the time of thine anger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 19, 1, E'Thus saith the LORD, Go and get a potterâ€™s earthen bottle, and take of the ancients of the people, and of the ancients of the priests;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 19, 2, E'And go forth unto the valley of the son of Hinnom, which is by the entry of the east gate, and proclaim there the words that I shall tell thee,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 19, 3, E'And say, Hear ye the word of the LORD, O kings of Judah, and inhabitants of Jerusalem; Thus saith the LORD of hosts, the God of Israel; Behold, I will bring evil upon this place, the which whosoever heareth, his ears shall tingle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 19, 4, E'Because they have forsaken me, and have estranged this place, and have burned incense in it unto other gods, whom neither they nor their fathers have known, nor the kings of Judah, and have filled this place with the blood of innocents;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 19, 5, E'They have built also the high places of Baal, to burn their sons with fire for burnt offerings unto Baal, which I commanded not, nor spake it, neither came it into my mind:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 19, 6, E'Therefore, behold, the days come, saith the LORD, that this place shall no more be called Tophet, nor The valley of the son of Hinnom, but The valley of slaughter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 19, 7, E'And I will make void the counsel of Judah and Jerusalem in this place; and I will cause them to fall by the sword before their enemies, and by the hands of them that seek their lives: and their carcases will I give to be meat for the fowls of the heaven, and for the beasts of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 19, 8, E'And I will make this city desolate, and an hissing; every one that passeth thereby shall be astonished and hiss because of all the plagues thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 19, 9, E'And I will cause them to eat the flesh of their sons and the flesh of their daughters, and they shall eat every one the flesh of his friend in the siege and straitness, wherewith their enemies, and they that seek their lives, shall straiten them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 19, 10, E'Then shalt thou break the bottle in the sight of the men that go with thee,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 19, 11, E'And shalt say unto them, Thus saith the LORD of hosts; Even so will I break this people and this city, as one breaketh a potterâ€™s vessel, that cannot be made whole again: and they shall bury them in Tophet, till there be no place to bury.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 19, 12, E'Thus will I do unto this place, saith the LORD, and to the inhabitants thereof, and even make this city as Tophet:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 19, 13, E'And the houses of Jerusalem, and the houses of the kings of Judah, shall be defiled as the place of Tophet, because of all the houses upon whose roofs they have burned incense unto all the host of heaven, and have poured out drink offerings unto other gods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 19, 14, E'Then came Jeremiah from Tophet, whither the LORD had sent him to prophesy; and he stood in the court of the LORDâ€™s house; and said to all the people,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 19, 15, E'Thus saith the LORD of hosts, the God of Israel; Behold, I will bring upon this city and upon all her towns all the evil that I have pronounced against it, because they have hardened their necks, that they might not hear my words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 20, 1, E'Now Pashur the son of Immer the priest, who was also chief governor in the house of the LORD, heard that Jeremiah prophesied these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 20, 2, E'Then Pashur smote Jeremiah the prophet, and put him in the stocks that were in the high gate of Benjamin, which was by the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 20, 3, E'And it came to pass on the morrow, that Pashur brought forth Jeremiah out of the stocks. Then said Jeremiah unto him, The LORD hath not called thy name Pashur, but Magormissabib.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 20, 4, E'For thus saith the LORD, Behold, I will make thee a terror to thyself, and to all thy friends: and they shall fall by the sword of their enemies, and thine eyes shall behold it: and I will give all Judah into the hand of the king of Babylon, and he shall carry them captive into Babylon, and shall slay them with the sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 20, 5, E'Moreover I will deliver all the strength of this city, and all the labours thereof, and all the precious things thereof, and all the treasures of the kings of Judah will I give into the hand of their enemies, which shall spoil them, and take them, and carry them to Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 20, 6, E'And thou, Pashur, and all that dwell in thine house shall go into captivity: and thou shalt come to Babylon, and there thou shalt die, and shalt be buried there, thou, and all thy friends, to whom thou hast prophesied lies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 20, 7, E'O LORD, thou hast deceived me, and I was deceived: thou art stronger than I, and hast prevailed: I am in derision daily, every one mocketh me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 20, 8, E'For since I spake, I cried out, I cried violence and spoil; because the word of the LORD was made a reproach unto me, and a derision, daily.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 20, 9, E'Then I said, I will not make mention of him, nor speak any more in his name. But his word was in mine heart as a burning fire shut up in my bones, and I was weary with forbearing, and I could not stay.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 20, 10, E'For I heard the defaming of many, fear on every side. Report, say they, and we will report it. All my familiars watched for my halting, saying, Peradventure he will be enticed, and we shall prevail against him, and we shall take our revenge on him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 20, 11, E'But the LORD is with me as a mighty terrible one: therefore my persecutors shall stumble, and they shall not prevail: they shall be greatly ashamed; for they shall not prosper: their everlasting confusion shall never be forgotten.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 20, 12, E'But, O LORD of hosts, that triest the righteous, and seest the reins and the heart, let me see thy vengeance on them: for unto thee have I opened my cause.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 20, 13, E'Sing unto the LORD, praise ye the LORD: for he hath delivered the soul of the poor from the hand of evildoers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 20, 14, E'Cursed be the day wherein I was born: let not the day wherein my mother bare me be blessed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 20, 15, E'Cursed be the man who brought tidings to my father, saying, A man child is born unto thee; making him very glad.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 20, 16, E'And let that man be as the cities which the LORD overthrew, and repented not: and let him hear the cry in the morning, and the shouting at noontide;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 20, 17, E'Because he slew me not from the womb; or that my mother might have been my grave, and her womb to be always great with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 20, 18, E'Wherefore came I forth out of the womb to see labour and sorrow, that my days should be consumed with shame?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 21, 1, E'The word which came unto Jeremiah from the LORD, when king Zedekiah sent unto him Pashur the son of Melchiah, and Zephaniah the son of Maaseiah the priest, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 21, 2, E'Enquire, I pray thee, of the LORD for us; for Nebuchadrezzar king of Babylon maketh war against us; if so be that the LORD will deal with us according to all his wondrous works, that he may go up from us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 21, 3, E'Then said Jeremiah unto them, Thus shall ye say to Zedekiah:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 21, 4, E'Thus saith the LORD God of Israel; Behold, I will turn back the weapons of war that are in your hands, wherewith ye fight against the king of Babylon, and against the Chaldeans, which besiege you without the walls, and I will assemble them into the midst of this city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 21, 5, E'And I myself will fight against you with an outstretched hand and with a strong arm, even in anger, and in fury, and in great wrath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 21, 6, E'And I will smite the inhabitants of this city, both man and beast: they shall die of a great pestilence.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Jeremiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 21, 7, E'And afterward, saith the LORD, I will deliver Zedekiah king of Judah, and his servants, and the people, and such as are left in this city from the pestilence, from the sword, and from the famine, into the hand of Nebuchadrezzar king of Babylon, and into the hand of their enemies, and into the hand of those that seek their life: and he shall smite them with the edge of the sword; he shall not spare them, neither have pity, nor have mercy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 21, 8, E'And unto this people thou shalt say, Thus saith the LORD; Behold, I set before you the way of life, and the way of death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 21, 9, E'He that abideth in this city shall die by the sword, and by the famine, and by the pestilence: but he that goeth out, and falleth to the Chaldeans that besiege you, he shall live, and his life shall be unto him for a prey.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 21, 10, E'For I have set my face against this city for evil, and not for good, saith the LORD: it shall be given into the hand of the king of Babylon, and he shall burn it with fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 21, 11, E'And touching the house of the king of Judah, say, Hear ye the word of the LORD;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 21, 12, E'O house of David, thus saith the LORD; Execute judgment in the morning, and deliver him that is spoiled out of the hand of the oppressor, lest my fury go out like fire, and burn that none can quench it, because of the evil of your doings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 21, 13, E'Behold, I am against thee, O inhabitant of the valley, and rock of the plain, saith the LORD; which say, Who shall come down against us? or who shall enter into our habitations?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 21, 14, E'But I will punish you according to the fruit of your doings, saith the LORD: and I will kindle a fire in the forest thereof, and it shall devour all things round about it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 1, E'Thus saith the LORD; Go down to the house of the king of Judah, and speak there this word,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 2, E'And say, Hear the word of the LORD, O king of Judah, that sittest upon the throne of David, thou, and thy servants, and thy people that enter in by these gates:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 3, E'Thus saith the LORD; Execute ye judgment and righteousness, and deliver the spoiled out of the hand of the oppressor: and do no wrong, do no violence to the stranger, the fatherless, nor the widow, neither shed innocent blood in this place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 4, E'For if ye do this thing indeed, then shall there enter in by the gates of this house kings sitting upon the throne of David, riding in chariots and on horses, he, and his servants, and his people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 5, E'But if ye will not hear these words, I swear by myself, saith the LORD, that this house shall become a desolation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 6, E'For thus saith the LORD unto the kingâ€™s house of Judah; Thou art Gilead unto me, and the head of Lebanon: yet surely I will make thee a wilderness, and cities which are not inhabited.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 7, E'And I will prepare destroyers against thee, every one with his weapons: and they shall cut down thy choice cedars, and cast them into the fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 8, E'And many nations shall pass by this city, and they shall say every man to his neighbour, Wherefore hath the LORD done thus unto this great city?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 9, E'Then they shall answer, Because they have forsaken the covenant of the LORD their God, and worshipped other gods, and served them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 10, E'Weep ye not for the dead, neither bemoan him: but weep sore for him that goeth away: for he shall return no more, nor see his native country.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 11, E'For thus saith the LORD touching Shallum the son of Josiah king of Judah, which reigned instead of Josiah his father, which went forth out of this place; He shall not return thither any more:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 12, E'But he shall die in the place whither they have led him captive, and shall see this land no more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 13, E'Woe unto him that buildeth his house by unrighteousness, and his chambers by wrong; that useth his neighbourâ€™s service without wages, and giveth him not for his work;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 14, E'That saith, I will build me a wide house and large chambers, and cutteth him out windows; and it is cieled with cedar, and painted with vermilion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 15, E'Shalt thou reign, because thou closest thyself in cedar? did not thy father eat and drink, and do judgment and justice, and then it was well with him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 16, E'He judged the cause of the poor and needy; then it was well with him: was not this to know me? saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 17, E'But thine eyes and thine heart are not but for thy covetousness, and for to shed innocent blood, and for oppression, and for violence, to do it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 18, E'Therefore thus saith the LORD concerning Jehoiakim the son of Josiah king of Judah; They shall not lament for him, saying, Ah my brother! or, Ah sister! they shall not lament for him, saying, Ah lord! or, Ah his glory!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 19, E'He shall be buried with the burial of an ass, drawn and cast forth beyond the gates of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 20, E'Go up to Lebanon, and cry; and lift up thy voice in Bashan, and cry from the passages: for all thy lovers are destroyed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 21, E'I spake unto thee in thy prosperity; but thou saidst, I will not hear. This hath been thy manner from thy youth, that thou obeyedst not my voice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 22, E'The wind shall eat up all thy pastors, and thy lovers shall go into captivity: surely then shalt thou be ashamed and confounded for all thy wickedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 23, E'O inhabitant of Lebanon, that makest thy nest in the cedars, how gracious shalt thou be when pangs come upon thee, the pain as of a woman in travail!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 24, E'As I live, saith the LORD, though Coniah the son of Jehoiakim king of Judah were the signet upon my right hand, yet would I pluck thee thence;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 25, E'And I will give thee into the hand of them that seek thy life, and into the hand of them whose face thou fearest, even into the hand of Nebuchadrezzar king of Babylon, and into the hand of the Chaldeans.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 26, E'And I will cast thee out, and thy mother that bare thee, into another country, where ye were not born; and there shall ye die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 27, E'But to the land whereunto they desire to return, thither shall they not return.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 28, E'Is this man Coniah a despised broken idol? is he a vessel wherein is no pleasure? wherefore are they cast out, he and his seed, and are cast into a land which they know not?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 29, E'O earth, earth, earth, hear the word of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 22, 30, E'Thus saith the LORD, Write ye this man childless, a man that shall not prosper in his days: for no man of his seed shall prosper, sitting upon the throne of David, and ruling any more in Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 1, E'Woe be unto the pastors that destroy and scatter the sheep of my pasture! saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 2, E'Therefore thus saith the LORD God of Israel against the pastors that feed my people; Ye have scattered my flock, and driven them away, and have not visited them: behold, I will visit upon you the evil of your doings, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 3, E'And I will gather the remnant of my flock out of all countries whither I have driven them, and will bring them again to their folds; and they shall be fruitful and increase.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 4, E'And I will set up shepherds over them which shall feed them: and they shall fear no more, nor be dismayed, neither shall they be lacking, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 5, E'Behold, the days come, saith the LORD, that I will raise unto David a righteous Branch, and a King shall reign and prosper, and shall execute judgment and justice in the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 6, E'In his days Judah shall be saved, and Israel shall dwell safely: and this is his name whereby he shall be called, THE LORD OUR RIGHTEOUSNESS.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 7, E'Therefore, behold, the days come, saith the LORD, that they shall no more say, The LORD liveth, which brought up the children of Israel out of the land of Egypt;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 8, E'But, The LORD liveth, which brought up and which led the seed of the house of Israel out of the north country, and from all countries whither I had driven them; and they shall dwell in their own land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 9, E'Mine heart within me is broken because of the prophets; all my bones shake; I am like a drunken man, and like a man whom wine hath overcome, because of the LORD, and because of the words of his holiness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 10, E'For the land is full of adulterers; for because of swearing the land mourneth; the pleasant places of the wilderness are dried up, and their course is evil, and their force is not right.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 11, E'For both prophet and priest are profane; yea, in my house have I found their wickedness, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 12, E'Wherefore their way shall be unto them as slippery ways in the darkness: they shall be driven on, and fall therein: for I will bring evil upon them, even the year of their visitation, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 13, E'And I have seen folly in the prophets of Samaria; they prophesied in Baal, and caused my people Israel to err.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 14, E'I have seen also in the prophets of Jerusalem an horrible thing: they commit adultery, and walk in lies: they strengthen also the hands of evildoers, that none doth return from his wickedness: they are all of them unto me as Sodom, and the inhabitants thereof as Gomorrah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 15, E'Therefore thus saith the LORD of hosts concerning the prophets; Behold, I will feed them with wormwood, and make them drink the water of gall: for from the prophets of Jerusalem is profaneness gone forth into all the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 16, E'Thus saith the LORD of hosts, Hearken not unto the words of the prophets that prophesy unto you: they make you vain: they speak a vision of their own heart, and not out of the mouth of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 17, E'They say still unto them that despise me, The LORD hath said, Ye shall have peace; and they say unto every one that walketh after the imagination of his own heart, No evil shall come upon you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 18, E'For who hath stood in the counsel of the LORD, and hath perceived and heard his word? who hath marked his word, and heard it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 19, E'Behold, a whirlwind of the LORD is gone forth in fury, even a grievous whirlwind: it shall fall grievously upon the head of the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 20, E'The anger of the LORD shall not return, until he have executed, and till he have performed the thoughts of his heart: in the latter days ye shall consider it perfectly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 21, E'I have not sent these prophets, yet they ran: I have not spoken to them, yet they prophesied.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 22, E'But if they had stood in my counsel, and had caused my people to hear my words, then they should have turned them from their evil way, and from the evil of their doings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 23, E'Am I a God at hand, saith the LORD, and not a God afar off?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 24, E'Can any hide himself in secret places that I shall not see him? saith the LORD. Do not I fill heaven and earth? saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 25, E'I have heard what the prophets said, that prophesy lies in my name, saying, I have dreamed, I have dreamed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 26, E'How long shall this be in the heart of the prophets that prophesy lies? yea, they are prophets of the deceit of their own heart;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 27, E'Which think to cause my people to forget my name by their dreams which they tell every man to his neighbour, as their fathers have forgotten my name for Baal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 28, E'The prophet that hath a dream, let him tell a dream; and he that hath my word, let him speak my word faithfully. What is the chaff to the wheat? saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 29, E'Is not my word like as a fire? saith the LORD; and like a hammer that breaketh the rock in pieces?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 30, E'Therefore, behold, I am against the prophets, saith the LORD, that steal my words every one from his neighbour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 31, E'Behold, I am against the prophets, saith the LORD, that use their tongues, and say, He saith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 32, E'Behold, I am against them that prophesy false dreams, saith the LORD, and do tell them, and cause my people to err by their lies, and by their lightness; yet I sent them not, nor commanded them: therefore they shall not profit this people at all, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 33, E'And when this people, or the prophet, or a priest, shall ask thee, saying, What is the burden of the LORD? thou shalt then say unto them, What burden? I will even forsake you, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 34, E'And as for the prophet, and the priest, and the people, that shall say, The burden of the LORD, I will even punish that man and his house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 35, E'Thus shall ye say every one to his neighbour, and every one to his brother, What hath the LORD answered? and, What hath the LORD spoken?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 36, E'And the burden of the LORD shall ye mention no more: for every manâ€™s word shall be his burden; for ye have perverted the words of the living God, of the LORD of hosts our God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 37, E'Thus shalt thou say to the prophet, What hath the LORD answered thee? and, What hath the LORD spoken?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 38, E'But since ye say, The burden of the LORD; therefore thus saith the LORD; Because ye say this word, The burden of the LORD, and I have sent unto you, saying, Ye shall not say, The burden of the LORD;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 39, E'Therefore, behold, I, even I, will utterly forget you, and I will forsake you, and the city that I gave you and your fathers, and cast you out of my presence:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 23, 40, E'And I will bring an everlasting reproach upon you, and a perpetual shame, which shall not be forgotten.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 24, 1, E'The LORD shewed me, and, behold, two baskets of figs were set before the temple of the LORD, after that Nebuchadrezzar king of Babylon had carried away captive Jeconiah the son of Jehoiakim king of Judah, and the princes of Judah, with the carpenters and smiths, from Jerusalem, and had brought them to Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 24, 2, E'One basket had very good figs, even like the figs that are first ripe: and the other basket had very naughty figs, which could not be eaten, they were so bad.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 24, 3, E'Then said the LORD unto me, What seest thou, Jeremiah? And I said, Figs; the good figs, very good; and the evil, very evil, that cannot be eaten, they are so evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 24, 4, E'Again the word of the LORD came unto me, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 24, 5, E'Thus saith the LORD, the God of Israel; Like these good figs, so will I acknowledge them that are carried away captive of Judah, whom I have sent out of this place into the land of the Chaldeans for their good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 24, 6, E'For I will set mine eyes upon them for good, and I will bring them again to this land: and I will build them, and not pull them down; and I will plant them, and not pluck them up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 24, 7, E'And I will give them an heart to know me, that I am the LORD: and they shall be my people, and I will be their God: for they shall return unto me with their whole heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 24, 8, E'And as the evil figs, which cannot be eaten, they are so evil; surely thus saith the LORD, So will I give Zedekiah the king of Judah, and his princes, and the residue of Jerusalem, that remain in this land, and them that dwell in the land of Egypt:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 24, 9, E'And I will deliver them to be removed into all the kingdoms of the earth for their hurt, to be a reproach and a proverb, a taunt and a curse, in all places whither I shall drive them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 24, 10, E'And I will send the sword, the famine, and the pestilence, among them, till they be consumed from off the land that I gave unto them and to their fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 1, E'The word that came to Jeremiah concerning all the people of Judah in the fourth year of Jehoiakim the son of Josiah king of Judah, that was the first year of Nebuchadrezzar king of Babylon;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 2, E'The which Jeremiah the prophet spake unto all the people of Judah, and to all the inhabitants of Jerusalem, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 3, E'From the thirteenth year of Josiah the son of Amon king of Judah, even unto this day, that is the three and twentieth year, the word of the LORD hath come unto me, and I have spoken unto you, rising early and speaking; but ye have not hearkened.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 4, E'And the LORD hath sent unto you all his servants the prophets, rising early and sending them; but ye have not hearkened, nor inclined your ear to hear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 5, E'They said, Turn ye again now every one from his evil way, and from the evil of your doings, and dwell in the land that the LORD hath given unto you and to your fathers for ever and ever:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 6, E'And go not after other gods to serve them, and to worship them, and provoke me not to anger with the works of your hands; and I will do you no hurt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 7, E'Yet ye have not hearkened unto me, saith the LORD; that ye might provoke me to anger with the works of your hands to your own hurt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 8, E'Therefore thus saith the LORD of hosts; Because ye have not heard my words,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 9, E'Behold, I will send and take all the families of the north, saith the LORD, and Nebuchadrezzar the king of Babylon, my servant, and will bring them against this land, and against the inhabitants thereof, and against all these nations round about, and will utterly destroy them, and make them an astonishment, and an hissing, and perpetual desolations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 10, E'Moreover I will take from them the voice of mirth, and the voice of gladness, the voice of the bridegroom, and the voice of the bride, the sound of the millstones, and the light of the candle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 11, E'And this whole land shall be a desolation, and an astonishment; and these nations shall serve the king of Babylon seventy years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 12, E'And it shall come to pass, when seventy years are accomplished, that I will punish the king of Babylon, and that nation, saith the LORD, for their iniquity, and the land of the Chaldeans, and will make it perpetual desolations.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Jeremiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 13, E'And I will bring upon that land all my words which I have pronounced against it, even all that is written in this book, which Jeremiah hath prophesied against all the nations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 14, E'For many nations and great kings shall serve themselves of them also: and I will recompense them according to their deeds, and according to the works of their own hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 15, E'For thus saith the LORD God of Israel unto me; Take the wine cup of this fury at my hand, and cause all the nations, to whom I send thee, to drink it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 16, E'And they shall drink, and be moved, and be mad, because of the sword that I will send among them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 17, E'Then took I the cup at the LORDâ€™s hand, and made all the nations to drink, unto whom the LORD had sent me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 18, E'To wit, Jerusalem, and the cities of Judah, and the kings thereof, and the princes thereof, to make them a desolation, an astonishment, an hissing, and a curse; as it is this day;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 19, E'Pharaoh king of Egypt, and his servants, and his princes, and all his people;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 20, E'And all the mingled people, and all the kings of the land of Uz, and all the kings of the land of the Philistines, and Ashkelon, and Azzah, and Ekron, and the remnant of Ashdod,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 21, E'Edom, and Moab, and the children of Ammon,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 22, E'And all the kings of Tyrus, and all the kings of Zidon, and the kings of the isles which are beyond the sea,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 23, E'Dedan, and Tema, and Buz, and all that are in the utmost corners,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 24, E'And all the kings of Arabia, and all the kings of the mingled people that dwell in the desert,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 25, E'And all the kings of Zimri, and all the kings of Elam, and all the kings of the Medes,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 26, E'And all the kings of the north, far and near, one with another, and all the kingdoms of the world, which are upon the face of the earth: and the king of Sheshach shall drink after them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 27, E'Therefore thou shalt say unto them, Thus saith the LORD of hosts, the God of Israel; Drink ye, and be drunken, and spue, and fall, and rise no more, because of the sword which I will send among you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 28, E'And it shall be, if they refuse to take the cup at thine hand to drink, then shalt thou say unto them, Thus saith the LORD of hosts; Ye shall certainly drink.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 29, E'For, lo, I begin to bring evil on the city which is called by my name, and should ye be utterly unpunished? Ye shall not be unpunished: for I will call for a sword upon all the inhabitants of the earth, saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 30, E'Therefore prophesy thou against them all these words, and say unto them, The LORD shall roar from on high, and utter his voice from his holy habitation; he shall mightily roar upon his habitation; he shall give a shout, as they that tread the grapes, against all the inhabitants of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 31, E'A noise shall come even to the ends of the earth; for the LORD hath a controversy with the nations, he will plead with all flesh; he will give them that are wicked to the sword, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 32, E'Thus saith the LORD of hosts, Behold, evil shall go forth from nation to nation, and a great whirlwind shall be raised up from the coasts of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 33, E'And the slain of the LORD shall be at that day from one end of the earth even unto the other end of the earth: they shall not be lamented, neither gathered, nor buried; they shall be dung upon the ground.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 34, E'Howl, ye shepherds, and cry; and wallow yourselves in the ashes, ye principal of the flock: for the days of your slaughter and of your dispersions are accomplished; and ye shall fall like a pleasant vessel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 35, E'And the shepherds shall have no way to flee, nor the principal of the flock to escape.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 36, E'A voice of the cry of the shepherds, and an howling of the principal of the flock, shall be heard: for the LORD hath spoiled their pasture.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 37, E'And the peaceable habitations are cut down because of the fierce anger of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 25, 38, E'He hath forsaken his covert, as the lion: for their land is desolate because of the fierceness of the oppressor, and because of his fierce anger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 26, 1, E'In the beginning of the reign of Jehoiakim the son of Josiah king of Judah came this word from the LORD, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 26, 2, E'Thus saith the LORD; Stand in the court of the LORDâ€™s house, and speak unto all the cities of Judah, which come to worship in the LORDâ€™s house, all the words that I command thee to speak unto them; diminish not a word:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 26, 3, E'If so be they will hearken, and turn every man from his evil way, that I may repent me of the evil, which I purpose to do unto them because of the evil of their doings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 26, 4, E'And thou shalt say unto them, Thus saith the LORD; If ye will not hearken to me, to walk in my law, which I have set before you,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 26, 5, E'To hearken to the words of my servants the prophets, whom I sent unto you, both rising up early, and sending them, but ye have not hearkened;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 26, 6, E'Then will I make this house like Shiloh, and will make this city a curse to all the nations of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 26, 7, E'So the priests and the prophets and all the people heard Jeremiah speaking these words in the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 26, 8, E'Now it came to pass, when Jeremiah had made an end of speaking all that the LORD had commanded him to speak unto all the people, that the priests and the prophets and all the people took him, saying, Thou shalt surely die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 26, 9, E'Why hast thou prophesied in the name of the LORD, saying, This house shall be like Shiloh, and this city shall be desolate without an inhabitant? And all the people were gathered against Jeremiah in the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 26, 10, E'When the princes of Judah heard these things, then they came up from the kingâ€™s house unto the house of the LORD, and sat down in the entry of the new gate of the LORDâ€™s house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 26, 11, E'Then spake the priests and the prophets unto the princes and to all the people, saying, This man is worthy to die; for he hath prophesied against this city, as ye have heard with your ears.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 26, 12, E'Then spake Jeremiah unto all the princes and to all the people, saying, The LORD sent me to prophesy against this house and against this city all the words that ye have heard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 26, 13, E'Therefore now amend your ways and your doings, and obey the voice of the LORD your God; and the LORD will repent him of the evil that he hath pronounced against you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 26, 14, E'As for me, behold, I am in your hand: do with me as seemeth good and meet unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 26, 15, E'But know ye for certain, that if ye put me to death, ye shall surely bring innocent blood upon yourselves, and upon this city, and upon the inhabitants thereof: for of a truth the LORD hath sent me unto you to speak all these words in your ears.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 26, 16, E'Then said the princes and all the people unto the priests and to the prophets; This man is not worthy to die: for he hath spoken to us in the name of the LORD our God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 26, 17, E'Then rose up certain of the elders of the land, and spake to all the assembly of the people, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 26, 18, E'Micah the Morasthite prophesied in the days of Hezekiah king of Judah, and spake to all the people of Judah, saying, Thus saith the LORD of hosts; Zion shall be plowed like a field, and Jerusalem shall become heaps, and the mountain of the house as the high places of a forest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 26, 19, E'Did Hezekiah king of Judah and all Judah put him at all to death? did he not fear the LORD, and besought the LORD, and the LORD repented him of the evil which he had pronounced against them? Thus might we procure great evil against our souls.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 26, 20, E'And there was also a man that prophesied in the name of the LORD, Urijah the son of Shemaiah of Kirjathjearim, who prophesied against this city and against this land according to all the words of Jeremiah:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 26, 21, E'And when Jehoiakim the king, with all his mighty men, and all the princes, heard his words, the king sought to put him to death: but when Urijah heard it, he was afraid, and fled, and went into Egypt;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 26, 22, E'And Jehoiakim the king sent men into Egypt, namely, Elnathan the son of Achbor, and certain men with him into Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 26, 23, E'And they fetched forth Urijah out of Egypt, and brought him unto Jehoiakim the king; who slew him with the sword, and cast his dead body into the graves of the common people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 26, 24, E'Nevertheless the hand of Ahikam the son of Shaphan was with Jeremiah, that they should not give him into the hand of the people to put him to death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 27, 1, E'In the beginning of the reign of Jehoiakim the son of Josiah king of Judah came this word unto Jeremiah from the LORD, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 27, 2, E'Thus saith the LORD to me; Make thee bonds and yokes, and put them upon thy neck,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 27, 3, E'And send them to the king of Edom, and to the king of Moab, and to the king of the Ammonites, and to the king of Tyrus, and to the king of Zidon, by the hand of the messengers which come to Jerusalem unto Zedekiah king of Judah;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 27, 4, E'And command them to say unto their masters, Thus saith the LORD of hosts, the God of Israel; Thus shall ye say unto your masters;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 27, 5, E'I have made the earth, the man and the beast that are upon the ground, by my great power and by my outstretched arm, and have given it unto whom it seemed meet unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 27, 6, E'And now have I given all these lands into the hand of Nebuchadnezzar the king of Babylon, my servant; and the beasts of the field have I given him also to serve him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 27, 7, E'And all nations shall serve him, and his son, and his sonâ€™s son, until the very time of his land come: and then many nations and great kings shall serve themselves of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 27, 8, E'And it shall come to pass, that the nation and kingdom which will not serve the same Nebuchadnezzar the king of Babylon, and that will not put their neck under the yoke of the king of Babylon, that nation will I punish, saith the LORD, with the sword, and with the famine, and with the pestilence, until I have consumed them by his hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 27, 9, E'Therefore hearken not ye to your prophets, nor to your diviners, nor to your dreamers, nor to your enchanters, nor to your sorcerers, which speak unto you, saying, Ye shall not serve the king of Babylon:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 27, 10, E'For they prophesy a lie unto you, to remove you far from your land; and that I should drive you out, and ye should perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 27, 11, E'But the nations that bring their neck under the yoke of the king of Babylon, and serve him, those will I let remain still in their own land, saith the LORD; and they shall till it, and dwell therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 27, 12, E'I spake also to Zedekiah king of Judah according to all these words, saying, Bring your necks under the yoke of the king of Babylon, and serve him and his people, and live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 27, 13, E'Why will ye die, thou and thy people, by the sword, by the famine, and by the pestilence, as the LORD hath spoken against the nation that will not serve the king of Babylon?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 27, 14, E'Therefore hearken not unto the words of the prophets that speak unto you, saying, Ye shall not serve the king of Babylon: for they prophesy a lie unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 27, 15, E'For I have not sent them, saith the LORD, yet they prophesy a lie in my name; that I might drive you out, and that ye might perish, ye, and the prophets that prophesy unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 27, 16, E'Also I spake to the priests and to all this people, saying, Thus saith the LORD; Hearken not to the words of your prophets that prophesy unto you, saying, Behold, the vessels of the LORDâ€™s house shall now shortly be brought again from Babylon: for they prophesy a lie unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 27, 17, E'Hearken not unto them; serve the king of Babylon, and live: wherefore should this city be laid waste?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 27, 18, E'But if they be prophets, and if the word of the LORD be with them, let them now make intercession to the LORD of hosts, that the vessels which are left in the house of the LORD, and in the house of the king of Judah, and at Jerusalem, go not to Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 27, 19, E'For thus saith the LORD of hosts concerning the pillars, and concerning the sea, and concerning the bases, and concerning the residue of the vessels that remain in this city,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 27, 20, E'Which Nebuchadnezzar king of Babylon took not, when he carried away captive Jeconiah the son of Jehoiakim king of Judah from Jerusalem to Babylon, and all the nobles of Judah and Jerusalem;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 27, 21, E'Yea, thus saith the LORD of hosts, the God of Israel, concerning the vessels that remain in the house of the LORD, and in the house of the king of Judah and of Jerusalem;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 27, 22, E'They shall be carried to Babylon, and there shall they be until the day that I visit them, saith the LORD; then will I bring them up, and restore them to this place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 28, 1, E'And it came to pass the same year, in the beginning of the reign of Zedekiah king of Judah, in the fourth year, and in the fifth month, that Hananiah the son of Azur the prophet, which was of Gibeon, spake unto me in the house of the LORD, in the presence of the priests and of all the people, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 28, 2, E'Thus speaketh the LORD of hosts, the God of Israel, saying, I have broken the yoke of the king of Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 28, 3, E'Within two full years will I bring again into this place all the vessels of the LORDâ€™s house, that Nebuchadnezzar king of Babylon took away from this place, and carried them to Babylon:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 28, 4, E'And I will bring again to this place Jeconiah the son of Jehoiakim king of Judah, with all the captives of Judah, that went into Babylon, saith the LORD: for I will break the yoke of the king of Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 28, 5, E'Then the prophet Jeremiah said unto the prophet Hananiah in the presence of the priests, and in the presence of all the people that stood in the house of the LORD,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 28, 6, E'Even the prophet Jeremiah said, Amen: the LORD do so: the LORD perform thy words which thou hast prophesied, to bring again the vessels of the LORDâ€™s house, and all that is carried away captive, from Babylon into this place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 28, 7, E'Nevertheless hear thou now this word that I speak in thine ears, and in the ears of all the people;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 28, 8, E'The prophets that have been before me and before thee of old prophesied both against many countries, and against great kingdoms, of war, and of evil, and of pestilence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 28, 9, E'The prophet which prophesieth of peace, when the word of the prophet shall come to pass, then shall the prophet be known, that the LORD hath truly sent him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 28, 10, E'Then Hananiah the prophet took the yoke from off the prophet Jeremiahâ€™s neck, and brake it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 28, 11, E'And Hananiah spake in the presence of all the people, saying, Thus saith the LORD; Even so will I break the yoke of Nebuchadnezzar king of Babylon from the neck of all nations within the space of two full years. And the prophet Jeremiah went his way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 28, 12, E'Then the word of the LORD came unto Jeremiah the prophet, after that Hananiah the prophet had broken the yoke from off the neck of the prophet Jeremiah, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 28, 13, E'Go and tell Hananiah, saying, Thus saith the LORD; Thou hast broken the yokes of wood; but thou shalt make for them yokes of iron.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 28, 14, E'For thus saith the LORD of hosts, the God of Israel; I have put a yoke of iron upon the neck of all these nations, that they may serve Nebuchadnezzar king of Babylon; and they shall serve him: and I have given him the beasts of the field also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 28, 15, E'Then said the prophet Jeremiah unto Hananiah the prophet, Hear now, Hananiah; The LORD hath not sent thee; but thou makest this people to trust in a lie.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 28, 16, E'Therefore thus saith the LORD; Behold, I will cast thee from off the face of the earth: this year thou shalt die, because thou hast taught rebellion against the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 28, 17, E'So Hananiah the prophet died the same year in the seventh month.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 1, E'Now these are the words of the letter that Jeremiah the prophet sent from Jerusalem unto the residue of the elders which were carried away captives, and to the priests, and to the prophets, and to all the people whom Nebuchadnezzar had carried away captive from Jerusalem to Babylon;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 2, E'(After that Jeconiah the king, and the queen, and the eunuchs, the princes of Judah and Jerusalem, and the carpenters, and the smiths, were departed from Jerusalem;)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 3, E'By the hand of Elasah the son of Shaphan, and Gemariah the son of Hilkiah, (whom Zedekiah king of Judah sent unto Babylon to Nebuchadnezzar king of Babylon) saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 4, E'Thus saith the LORD of hosts, the God of Israel, unto all that are carried away captives, whom I have caused to be carried away from Jerusalem unto Babylon;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 5, E'Build ye houses, and dwell in them; and plant gardens, and eat the fruit of them;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 6, E'Take ye wives, and beget sons and daughters; and take wives for your sons, and give your daughters to husbands, that they may bear sons and daughters; that ye may be increased there, and not diminished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 7, E'And seek the peace of the city whither I have caused you to be carried away captives, and pray unto the LORD for it: for in the peace thereof shall ye have peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 8, E'For thus saith the LORD of hosts, the God of Israel; Let not your prophets and your diviners, that be in the midst of you, deceive you, neither hearken to your dreams which ye cause to be dreamed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 9, E'For they prophesy falsely unto you in my name: I have not sent them, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 10, E'For thus saith the LORD, That after seventy years be accomplished at Babylon I will visit you, and perform my good word toward you, in causing you to return to this place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 11, E'For I know the thoughts that I think toward you, saith the LORD, thoughts of peace, and not of evil, to give you an expected end.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Jeremiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 12, E'Then shall ye call upon me, and ye shall go and pray unto me, and I will hearken unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 13, E'And ye shall seek me, and find me, when ye shall search for me with all your heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 14, E'And I will be found of you, saith the LORD: and I will turn away your captivity, and I will gather you from all the nations, and from all the places whither I have driven you, saith the LORD; and I will bring you again into the place whence I caused you to be carried away captive.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 15, E'Because ye have said, The LORD hath raised us up prophets in Babylon;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 16, E'Know that thus saith the LORD of the king that sitteth upon the throne of David, and of all the people that dwelleth in this city, and of your brethren that are not gone forth with you into captivity;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 17, E'Thus saith the LORD of hosts; Behold, I will send upon them the sword, the famine, and the pestilence, and will make them like vile figs, that cannot be eaten, they are so evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 18, E'And I will persecute them with the sword, with the famine, and with the pestilence, and will deliver them to be removed to all the kingdoms of the earth, to be a curse, and an astonishment, and an hissing, and a reproach, among all the nations whither I have driven them:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 19, E'Because they have not hearkened to my words, saith the LORD, which I sent unto them by my servants the prophets, rising up early and sending them; but ye would not hear, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 20, E'Hear ye therefore the word of the LORD, all ye of the captivity, whom I have sent from Jerusalem to Babylon:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 21, E'Thus saith the LORD of hosts, the God of Israel, of Ahab the son of Kolaiah, and of Zedekiah the son of Maaseiah, which prophesy a lie unto you in my name; Behold, I will deliver them into the hand of Nebuchadrezzar king of Babylon; and he shall slay them before your eyes;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 22, E'And of them shall be taken up a curse by all the captivity of Judah which are in Babylon, saying, The LORD make thee like Zedekiah and like Ahab, whom the king of Babylon roasted in the fire;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 23, E'Because they have committed villany in Israel, and have committed adultery with their neighboursâ€™ wives, and have spoken lying words in my name, which I have not commanded them; even I know, and am a witness, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 24, E'Thus shalt thou also speak to Shemaiah the Nehelamite, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 25, E'Thus speaketh the LORD of hosts, the God of Israel, saying, Because thou hast sent letters in thy name unto all the people that are at Jerusalem, and to Zephaniah the son of Maaseiah the priest, and to all the priests, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 26, E'The LORD hath made thee priest in the stead of Jehoiada the priest, that ye should be officers in the house of the LORD, for every man that is mad, and maketh himself a prophet, that thou shouldest put him in prison, and in the stocks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 27, E'Now therefore why hast thou not reproved Jeremiah of Anathoth, which maketh himself a prophet to you?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 28, E'For therefore he sent unto us in Babylon, saying, This captivity is long: build ye houses, and dwell in them; and plant gardens, and eat the fruit of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 29, E'And Zephaniah the priest read this letter in the ears of Jeremiah the prophet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 30, E'Then came the word of the LORD unto Jeremiah, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 31, E'Send to all them of the captivity, saying, Thus saith the LORD concerning Shemaiah the Nehelamite; Because that Shemaiah hath prophesied unto you, and I sent him not, and he caused you to trust in a lie:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 29, 32, E'Therefore thus saith the LORD; Behold, I will punish Shemaiah the Nehelamite, and his seed: he shall not have a man to dwell among this people; neither shall he behold the good that I will do for my people, saith the LORD; because he hath taught rebellion against the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 30, 1, E'The word that came to Jeremiah from the LORD, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 30, 2, E'Thus speaketh the LORD God of Israel, saying, Write thee all the words that I have spoken unto thee in a book.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 30, 3, E'For, lo, the days come, saith the LORD, that I will bring again the captivity of my people Israel and Judah, saith the LORD: and I will cause them to return to the land that I gave to their fathers, and they shall possess it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 30, 4, E'And these are the words that the LORD spake concerning Israel and concerning Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 30, 5, E'For thus saith the LORD; We have heard a voice of trembling, of fear, and not of peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 30, 6, E'Ask ye now, and see whether a man doth travail with child? wherefore do I see every man with his hands on his loins, as a woman in travail, and all faces are turned into paleness?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 30, 7, E'Alas! for that day is great, so that none is like it: it is even the time of Jacobâ€™s trouble, but he shall be saved out of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 30, 8, E'For it shall come to pass in that day, saith the LORD of hosts, that I will break his yoke from off thy neck, and will burst thy bonds, and strangers shall no more serve themselves of him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 30, 9, E'But they shall serve the LORD their God, and David their king, whom I will raise up unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 30, 10, E'Therefore fear thou not, O my servant Jacob, saith the LORD; neither be dismayed, O Israel: for, lo, I will save thee from afar, and thy seed from the land of their captivity; and Jacob shall return, and shall be in rest, and be quiet, and none shall make him afraid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 30, 11, E'For I am with thee, saith the LORD, to save thee: though I make a full end of all nations whither I have scattered thee, yet will I not make a full end of thee: but I will correct thee in measure, and will not leave thee altogether unpunished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 30, 12, E'For thus saith the LORD, Thy bruise is incurable, and thy wound is grievous.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 30, 13, E'There is none to plead thy cause, that thou mayest be bound up: thou hast no healing medicines.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 30, 14, E'All thy lovers have forgotten thee; they seek thee not; for I have wounded thee with the wound of an enemy, with the chastisement of a cruel one, for the multitude of thine iniquity; because thy sins were increased.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 30, 15, E'Why criest thou for thine affliction? thy sorrow is incurable for the multitude of thine iniquity: because thy sins were increased, I have done these things unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 30, 16, E'Therefore all they that devour thee shall be devoured; and all thine adversaries, every one of them, shall go into captivity; and they that spoil thee shall be a spoil, and all that prey upon thee will I give for a prey.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 30, 17, E'For I will restore health unto thee, and I will heal thee of thy wounds, saith the LORD; because they called thee an Outcast, saying, This is Zion, whom no man seeketh after.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 30, 18, E'Thus saith the LORD; Behold, I will bring again the captivity of Jacobâ€™s tents, and have mercy on his dwellingplaces; and the city shall be builded upon her own heap, and the palace shall remain after the manner thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 30, 19, E'And out of them shall proceed thanksgiving and the voice of them that make merry: and I will multiply them, and they shall not be few; I will also glorify them, and they shall not be small.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 30, 20, E'Their children also shall be as aforetime, and their congregation shall be established before me, and I will punish all that oppress them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 30, 21, E'And their nobles shall be of themselves, and their governor shall proceed from the midst of them; and I will cause him to draw near, and he shall approach unto me: for who is this that engaged his heart to approach unto me? saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 30, 22, E'And ye shall be my people, and I will be your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 30, 23, E'Behold, the whirlwind of the LORD goeth forth with fury, a continuing whirlwind: it shall fall with pain upon the head of the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 30, 24, E'The fierce anger of the LORD shall not return, until he have done it, and until he have performed the intents of his heart: in the latter days ye shall consider it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 1, E'At the same time, saith the LORD, will I be the God of all the families of Israel, and they shall be my people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 2, E'Thus saith the LORD, The people which were left of the sword found grace in the wilderness; even Israel, when I went to cause him to rest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 3, E'The LORD hath appeared of old unto me, saying, Yea, I have loved thee with an everlasting love: therefore with lovingkindness have I drawn thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 4, E'Again I will build thee, and thou shalt be built, O virgin of Israel: thou shalt again be adorned with thy tabrets, and shalt go forth in the dances of them that make merry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 5, E'Thou shalt yet plant vines upon the mountains of Samaria: the planters shall plant, and shall eat them as common things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 6, E'For there shall be a day, that the watchmen upon the mount Ephraim shall cry, Arise ye, and let us go up to Zion unto the LORD our God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 7, E'For thus saith the LORD; Sing with gladness for Jacob, and shout among the chief of the nations: publish ye, praise ye, and say, O LORD, save thy people, the remnant of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 8, E'Behold, I will bring them from the north country, and gather them from the coasts of the earth, and with them the blind and the lame, the woman with child and her that travaileth with child together: a great company shall return thither.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 9, E'They shall come with weeping, and with supplications will I lead them: I will cause them to walk by the rivers of waters in a straight way, wherein they shall not stumble: for I am a father to Israel, and Ephraim is my firstborn.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 10, E'Hear the word of the LORD, O ye nations, and declare it in the isles afar off, and say, He that scattered Israel will gather him, and keep him, as a shepherd doth his flock.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 11, E'For the LORD hath redeemed Jacob, and ransomed him from the hand of him that was stronger than he.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 12, E'Therefore they shall come and sing in the height of Zion, and shall flow together to the goodness of the LORD, for wheat, and for wine, and for oil, and for the young of the flock and of the herd: and their soul shall be as a watered garden; and they shall not sorrow any more at all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 13, E'Then shall the virgin rejoice in the dance, both young men and old together: for I will turn their mourning into joy, and will comfort them, and make them rejoice from their sorrow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 14, E'And I will satiate the soul of the priests with fatness, and my people shall be satisfied with my goodness, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 15, E'Thus saith the LORD; A voice was heard in Ramah, lamentation, and bitter weeping; Rahel weeping for her children refused to be comforted for her children, because they were not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 16, E'Thus saith the LORD; Refrain thy voice from weeping, and thine eyes from tears: for thy work shall be rewarded, saith the LORD; and they shall come again from the land of the enemy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 17, E'And there is hope in thine end, saith the LORD, that thy children shall come again to their own border.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 18, E'I have surely heard Ephraim bemoaning himself thus; Thou hast chastised me, and I was chastised, as a bullock unaccustomed to the yoke: turn thou me, and I shall be turned; for thou art the LORD my God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 19, E'Surely after that I was turned, I repented; and after that I was instructed, I smote upon my thigh: I was ashamed, yea, even confounded, because I did bear the reproach of my youth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 20, E'Is Ephraim my dear son? is he a pleasant child? for since I spake against him, I do earnestly remember him still: therefore my bowels are troubled for him; I will surely have mercy upon him, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 21, E'Set thee up waymarks, make thee high heaps: set thine heart toward the highway, even the way which thou wentest: turn again, O virgin of Israel, turn again to these thy cities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 22, E'How long wilt thou go about, O thou backsliding daughter? for the LORD hath created a new thing in the earth, A woman shall compass a man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 23, E'Thus saith the LORD of hosts, the God of Israel; As yet they shall use this speech in the land of Judah and in the cities thereof, when I shall bring again their captivity; The LORD bless thee, O habitation of justice, and mountain of holiness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 24, E'And there shall dwell in Judah itself, and in all the cities thereof together, husbandmen, and they that go forth with flocks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 25, E'For I have satiated the weary soul, and I have replenished every sorrowful soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 26, E'Upon this I awaked, and beheld; and my sleep was sweet unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 27, E'Behold, the days come, saith the LORD, that I will sow the house of Israel and the house of Judah with the seed of man, and with the seed of beast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 28, E'And it shall come to pass, that like as I have watched over them, to pluck up, and to break down, and to throw down, and to destroy, and to afflict; so will I watch over them, to build, and to plant, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 29, E'In those days they shall say no more, The fathers have eaten a sour grape, and the childrenâ€™s teeth are set on edge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 30, E'But every one shall die for his own iniquity: every man that eateth the sour grape, his teeth shall be set on edge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 31, E'Behold, the days come, saith the LORD, that I will make a new covenant with the house of Israel, and with the house of Judah:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 32, E'Not according to the covenant that I made with their fathers in the day that I took them by the hand to bring them out of the land of Egypt; which my covenant they brake, although I was an husband unto them, saith the LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 33, E'But this shall be the covenant that I will make with the house of Israel; After those days, saith the LORD, I will put my law in their inward parts, and write it in their hearts; and will be their God, and they shall be my people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 34, E'And they shall teach no more every man his neighbour, and every man his brother, saying, Know the LORD: for they shall all know me, from the least of them unto the greatest of them, saith the LORD: for I will forgive their iniquity, and I will remember their sin no more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 35, E'Thus saith the LORD, which giveth the sun for a light by day, and the ordinances of the moon and of the stars for a light by night, which divideth the sea when the waves thereof roar; The LORD of hosts is his name:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 36, E'If those ordinances depart from before me, saith the LORD, then the seed of Israel also shall cease from being a nation before me for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 37, E'Thus saith the LORD; If heaven above can be measured, and the foundations of the earth searched out beneath, I will also cast off all the seed of Israel for all that they have done, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 38, E'Behold, the days come, saith the LORD, that the city shall be built to the LORD from the tower of Hananeel unto the gate of the corner.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 39, E'And the measuring line shall yet go forth over against it upon the hill Gareb, and shall compass about to Goath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 31, 40, E'And the whole valley of the dead bodies, and of the ashes, and all the fields unto the brook of Kidron, unto the corner of the horse gate toward the east, shall be holy unto the LORD; it shall not be plucked up, nor thrown down any more for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 1, E'The word that came to Jeremiah from the LORD in the tenth year of Zedekiah king of Judah, which was the eighteenth year of Nebuchadrezzar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 2, E'For then the king of Babylonâ€™s army besieged Jerusalem: and Jeremiah the prophet was shut up in the court of the prison, which was in the king of Judahâ€™s house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 3, E'For Zedekiah king of Judah had shut him up, saying, Wherefore dost thou prophesy, and say, Thus saith the LORD, Behold, I will give this city into the hand of the king of Babylon, and he shall take it;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 4, E'And Zedekiah king of Judah shall not escape out of the hand of the Chaldeans, but shall surely be delivered into the hand of the king of Babylon, and shall speak with him mouth to mouth, and his eyes shall behold his eyes;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 5, E'And he shall lead Zedekiah to Babylon, and there shall he be until I visit him, saith the LORD: though ye fight with the Chaldeans, ye shall not prosper.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 6, E'And Jeremiah said, The word of the LORD came unto me, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 7, E'Behold, Hanameel the son of Shallum thine uncle shall come unto thee, saying, Buy thee my field that is in Anathoth: for the right of redemption is thine to buy it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 8, E'So Hanameel mine uncleâ€™s son came to me in the court of the prison according to the word of the LORD, and said unto me, Buy my field, I pray thee, that is in Anathoth, which is in the country of Benjamin: for the right of inheritance is thine, and the redemption is thine; buy it for thyself. Then I knew that this was the word of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 9, E'And I bought the field of Hanameel my uncleâ€™s son, that was in Anathoth, and weighed him the money, even seventeen shekels of silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 10, E'And I subscribed the evidence, and sealed it, and took witnesses, and weighed him the money in the balances.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 11, E'So I took the evidence of the purchase, both that which was sealed according to the law and custom, and that which was open:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 12, E'And I gave the evidence of the purchase unto Baruch the son of Neriah, the son of Maaseiah, in the sight of Hanameel mine uncleâ€™s son, and in the presence of the witnesses that subscribed the book of the purchase, before all the Jews that sat in the court of the prison.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 13, E'And I charged Baruch before them, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 14, E'Thus saith the LORD of hosts, the God of Israel; Take these evidences, this evidence of the purchase, both which is sealed, and this evidence which is open; and put them in an earthen vessel, that they may continue many days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 15, E'For thus saith the LORD of hosts, the God of Israel; Houses and fields and vineyards shall be possessed again in this land.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Jeremiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 16, E'Now when I had delivered the evidence of the purchase unto Baruch the son of Neriah, I prayed unto the LORD, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 17, E'Ah Lord GOD! behold, thou hast made the heaven and the earth by thy great power and stretched out arm, and there is nothing too hard for thee:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 18, E'Thou shewest lovingkindness unto thousands, and recompensest the iniquity of the fathers into the bosom of their children after them: the Great, the Mighty God, the LORD of hosts, is his name,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 19, E'Great in counsel, and mighty in work: for thine eyes are open upon all the ways of the sons of men: to give every one according to his ways, and according to the fruit of his doings:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 20, E'Which hast set signs and wonders in the land of Egypt, even unto this day, and in Israel, and among other men; and hast made thee a name, as at this day;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 21, E'And hast brought forth thy people Israel out of the land of Egypt with signs, and with wonders, and with a strong hand, and with a stretched out arm, and with great terror;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 22, E'And hast given them this land, which thou didst swear to their fathers to give them, a land flowing with milk and honey;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 23, E'And they came in, and possessed it; but they obeyed not thy voice, neither walked in thy law; they have done nothing of all that thou commandedst them to do: therefore thou hast caused all this evil to come upon them:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 24, E'Behold the mounts, they are come unto the city to take it; and the city is given into the hand of the Chaldeans, that fight against it, because of the sword, and of the famine, and of the pestilence: and what thou hast spoken is come to pass; and, behold, thou seest it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 25, E'And thou hast said unto me, O Lord GOD, Buy thee the field for money, and take witnesses; for the city is given into the hand of the Chaldeans.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 26, E'Then came the word of the LORD unto Jeremiah, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 27, E'Behold, I am the LORD, the God of all flesh: is there any thing too hard for me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 28, E'Therefore thus saith the LORD; Behold, I will give this city into the hand of the Chaldeans, and into the hand of Nebuchadrezzar king of Babylon, and he shall take it:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 29, E'And the Chaldeans, that fight against this city, shall come and set fire on this city, and burn it with the houses, upon whose roofs they have offered incense unto Baal, and poured out drink offerings unto other gods, to provoke me to anger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 30, E'For the children of Israel and the children of Judah have only done evil before me from their youth: for the children of Israel have only provoked me to anger with the work of their hands, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 31, E'For this city hath been to me as a provocation of mine anger and of my fury from the day that they built it even unto this day; that I should remove it from before my face,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 32, E'Because of all the evil of the children of Israel and of the children of Judah, which they have done to provoke me to anger, they, their kings, their princes, their priests, and their prophets, and the men of Judah, and the inhabitants of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 33, E'And they have turned unto me the back, and not the face: though I taught them, rising up early and teaching them, yet they have not hearkened to receive instruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 34, E'But they set their abominations in the house, which is called by my name, to defile it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 35, E'And they built the high places of Baal, which are in the valley of the son of Hinnom, to cause their sons and their daughters to pass through the fire unto Molech; which I commanded them not, neither came it into my mind, that they should do this abomination, to cause Judah to sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 36, E'And now therefore thus saith the LORD, the God of Israel, concerning this city, whereof ye say, It shall be delivered into the hand of the king of Babylon by the sword, and by the famine, and by the pestilence;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 37, E'Behold, I will gather them out of all countries, whither I have driven them in mine anger, and in my fury, and in great wrath; and I will bring them again unto this place, and I will cause them to dwell safely:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 38, E'And they shall be my people, and I will be their God:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 39, E'And I will give them one heart, and one way, that they may fear me for ever, for the good of them, and of their children after them:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 40, E'And I will make an everlasting covenant with them, that I will not turn away from them, to do them good; but I will put my fear in their hearts, that they shall not depart from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 41, E'Yea, I will rejoice over them to do them good, and I will plant them in this land assuredly with my whole heart and with my whole soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 42, E'For thus saith the LORD; Like as I have brought all this great evil upon this people, so will I bring upon them all the good that I have promised them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 43, E'And fields shall be bought in this land, whereof ye say, It is desolate without man or beast; it is given into the hand of the Chaldeans.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 32, 44, E'Men shall buy fields for money, and subscribe evidences, and seal them, and take witnesses in the land of Benjamin, and in the places about Jerusalem, and in the cities of Judah, and in the cities of the mountains, and in the cities of the valley, and in the cities of the south: for I will cause their captivity to return, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 1, E'Moreover the word of the LORD came unto Jeremiah the second time, while he was yet shut up in the court of the prison, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 2, E'Thus saith the LORD the maker thereof, the LORD that formed it, to establish it; the LORD is his name;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 3, E'Call unto me, and I will answer thee, and shew thee great and mighty things, which thou knowest not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 4, E'For thus saith the LORD, the God of Israel, concerning the houses of this city, and concerning the houses of the kings of Judah, which are thrown down by the mounts, and by the sword;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 5, E'They come to fight with the Chaldeans, but it is to fill them with the dead bodies of men, whom I have slain in mine anger and in my fury, and for all whose wickedness I have hid my face from this city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 6, E'Behold, I will bring it health and cure, and I will cure them, and will reveal unto them the abundance of peace and truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 7, E'And I will cause the captivity of Judah and the captivity of Israel to return, and will build them, as at the first.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 8, E'And I will cleanse them from all their iniquity, whereby they have sinned against me; and I will pardon all their iniquities, whereby they have sinned, and whereby they have transgressed against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 9, E'And it shall be to me a name of joy, a praise and an honour before all the nations of the earth, which shall hear all the good that I do unto them: and they shall fear and tremble for all the goodness and for all the prosperity that I procure unto it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 10, E'Thus saith the LORD; Again there shall be heard in this place, which ye say shall be desolate without man and without beast, even in the cities of Judah, and in the streets of Jerusalem, that are desolate, without man, and without inhabitant, and without beast,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 11, E'The voice of joy, and the voice of gladness, the voice of the bridegroom, and the voice of the bride, the voice of them that shall say, Praise the LORD of hosts: for the LORD is good; for his mercy endureth for ever: and of them that shall bring the sacrifice of praise into the house of the LORD. For I will cause to return the captivity of the land, as at the first, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 12, E'Thus saith the LORD of hosts; Again in this place, which is desolate without man and without beast, and in all the cities thereof, shall be an habitation of shepherds causing their flocks to lie down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 13, E'In the cities of the mountains, in the cities of the vale, and in the cities of the south, and in the land of Benjamin, and in the places about Jerusalem, and in the cities of Judah, shall the flocks pass again under the hands of him that telleth them, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 14, E'Behold, the days come, saith the LORD, that I will perform that good thing which I have promised unto the house of Israel and to the house of Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 15, E'In those days, and at that time, will I cause the Branch of righteousness to grow up unto David; and he shall execute judgment and righteousness in the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 16, E'In those days shall Judah be saved, and Jerusalem shall dwell safely: and this is the name wherewith she shall be called, The LORD our righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 17, E'For thus saith the LORD; David shall never want a man to sit upon the throne of the house of Israel;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 18, E'Neither shall the priests the Levites want a man before me to offer burnt offerings, and to kindle meat offerings, and to do sacrifice continually.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 19, E'And the word of the LORD came unto Jeremiah, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 20, E'Thus saith the LORD; If ye can break my covenant of the day, and my covenant of the night, and that there should not be day and night in their season;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 21, E'Then may also my covenant be broken with David my servant, that he should not have a son to reign upon his throne; and with the Levites the priests, my ministers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 22, E'As the host of heaven cannot be numbered, neither the sand of the sea measured: so will I multiply the seed of David my servant, and the Levites that minister unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 23, E'Moreover the word of the LORD came to Jeremiah, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 24, E'Considerest thou not what this people have spoken, saying, The two families which the LORD hath chosen, he hath even cast them off? thus they have despised my people, that they should be no more a nation before them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 25, E'Thus saith the LORD; If my covenant be not with day and night, and if I have not appointed the ordinances of heaven and earth;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 33, 26, E'Then will I cast away the seed of Jacob, and David my servant, so that I will not take any of his seed to be rulers over the seed of Abraham, Isaac, and Jacob: for I will cause their captivity to return, and have mercy on them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 34, 1, E'The word which came unto Jeremiah from the LORD, when Nebuchadnezzar king of Babylon, and all his army, and all the kingdoms of the earth of his dominion, and all the people, fought against Jerusalem, and against all the cities thereof, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 34, 2, E'Thus saith the LORD, the God of Israel; Go and speak to Zedekiah king of Judah, and tell him, Thus saith the LORD; Behold, I will give this city into the hand of the king of Babylon, and he shall burn it with fire:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 34, 3, E'And thou shalt not escape out of his hand, but shalt surely be taken, and delivered into his hand; and thine eyes shall behold the eyes of the king of Babylon, and he shall speak with thee mouth to mouth, and thou shalt go to Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 34, 4, E'Yet hear the word of the LORD, O Zedekiah king of Judah; Thus saith the LORD of thee, Thou shalt not die by the sword:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 34, 5, E'But thou shalt die in peace: and with the burnings of thy fathers, the former kings which were before thee, so shall they burn odours for thee; and they will lament thee, saying, Ah lord! for I have pronounced the word, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 34, 6, E'Then Jeremiah the prophet spake all these words unto Zedekiah king of Judah in Jerusalem,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 34, 7, E'When the king of Babylonâ€™s army fought against Jerusalem, and against all the cities of Judah that were left, against Lachish, and against Azekah: for these defenced cities remained of the cities of Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 34, 8, E'This is the word that came unto Jeremiah from the LORD, after that the king Zedekiah had made a covenant with all the people which were at Jerusalem, to proclaim liberty unto them;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 34, 9, E'That every man should let his manservant, and every man his maidservant, being an Hebrew or an Hebrewess, go free; that none should serve himself of them, to wit, of a Jew his brother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 34, 10, E'Now when all the princes, and all the people, which had entered into the covenant, heard that every one should let his manservant, and every one his maidservant, go free, that none should serve themselves of them any more, then they obeyed, and let them go.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 34, 11, E'But afterward they turned, and caused the servants and the handmaids, whom they had let go free, to return, and brought them into subjection for servants and for handmaids.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 34, 12, E'Therefore the word of the LORD came to Jeremiah from the LORD, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 34, 13, E'Thus saith the LORD, the God of Israel; I made a covenant with your fathers in the day that I brought them forth out of the land of Egypt, out of the house of bondmen, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 34, 14, E'At the end of seven years let ye go every man his brother an Hebrew, which hath been sold unto thee; and when he hath served thee six years, thou shalt let him go free from thee: but your fathers hearkened not unto me, neither inclined their ear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 34, 15, E'And ye were now turned, and had done right in my sight, in proclaiming liberty every man to his neighbour; and ye had made a covenant before me in the house which is called by my name:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 34, 16, E'But ye turned and polluted my name, and caused every man his servant, and every man his handmaid, whom he had set at liberty at their pleasure, to return, and brought them into subjection, to be unto you for servants and for handmaids.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 34, 17, E'Therefore thus saith the LORD; Ye have not hearkened unto me, in proclaiming liberty, every one to his brother, and every man to his neighbour: behold, I proclaim a liberty for you, saith the LORD, to the sword, to the pestilence, and to the famine; and I will make you to be removed into all the kingdoms of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 34, 18, E'And I will give the men that have transgressed my covenant, which have not performed the words of the covenant which they had made before me, when they cut the calf in twain, and passed between the parts thereof,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 34, 19, E'The princes of Judah, and the princes of Jerusalem, the eunuchs, and the priests, and all the people of the land, which passed between the parts of the calf;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 34, 20, E'I will even give them into the hand of their enemies, and into the hand of them that seek their life: and their dead bodies shall be for meat unto the fowls of the heaven, and to the beasts of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 34, 21, E'And Zedekiah king of Judah and his princes will I give into the hand of their enemies, and into the hand of them that seek their life, and into the hand of the king of Babylonâ€™s army, which are gone up from you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 34, 22, E'Behold, I will command, saith the LORD, and cause them to return to this city; and they shall fight against it, and take it, and burn it with fire: and I will make the cities of Judah a desolation without an inhabitant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 35, 1, E'The word which came unto Jeremiah from the LORD in the days of Jehoiakim the son of Josiah king of Judah, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 35, 2, E'Go unto the house of the Rechabites, and speak unto them, and bring them into the house of the LORD, into one of the chambers, and give them wine to drink.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 35, 3, E'Then I took Jaazaniah the son of Jeremiah, the son of Habaziniah, and his brethren, and all his sons, and the whole house of the Rechabites;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 35, 4, E'And I brought them into the house of the LORD, into the chamber of the sons of Hanan, the son of Igdaliah, a man of God, which was by the chamber of the princes, which was above the chamber of Maaseiah the son of Shallum, the keeper of the door:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 35, 5, E'And I set before the sons of the house of the Rechabites pots full of wine, and cups, and I said unto them, Drink ye wine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 35, 6, E'But they said, We will drink no wine: for Jonadab the son of Rechab our father commanded us, saying, Ye shall drink no wine, neither ye, nor your sons for ever:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 35, 7, E'Neither shall ye build house, nor sow seed, nor plant vineyard, nor have any: but all your days ye shall dwell in tents; that ye may live many days in the land where ye be strangers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 35, 8, E'Thus have we obeyed the voice of Jonadab the son of Rechab our father in all that he hath charged us, to drink no wine all our days, we, our wives, our sons, nor our daughters;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 35, 9, E'Nor to build houses for us to dwell in: neither have we vineyard, nor field, nor seed:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 35, 10, E'But we have dwelt in tents, and have obeyed, and done according to all that Jonadab our father commanded us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 35, 11, E'But it came to pass, when Nebuchadrezzar king of Babylon came up into the land, that we said, Come, and let us go to Jerusalem for fear of the army of the Chaldeans, and for fear of the army of the Syrians: so we dwell at Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 35, 12, E'Then came the word of the LORD unto Jeremiah, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 35, 13, E'Thus saith the LORD of hosts, the God of Israel; Go and tell the men of Judah and the inhabitants of Jerusalem, Will ye not receive instruction to hearken to my words? saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 35, 14, E'The words of Jonadab the son of Rechab, that he commanded his sons not to drink wine, are performed; for unto this day they drink none, but obey their fatherâ€™s commandment: notwithstanding I have spoken unto you, rising early and speaking; but ye hearkened not unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 35, 15, E'I have sent also unto you all my servants the prophets, rising up early and sending them, saying, Return ye now every man from his evil way, and amend your doings, and go not after other gods to serve them, and ye shall dwell in the land which I have given to you and to your fathers: but ye have not inclined your ear, nor hearkened unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 35, 16, E'Because the sons of Jonadab the son of Rechab have performed the commandment of their father, which he commanded them; but this people hath not hearkened unto me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 35, 17, E'Therefore thus saith the LORD God of hosts, the God of Israel; Behold, I will bring upon Judah and upon all the inhabitants of Jerusalem all the evil that I have pronounced against them: because I have spoken unto them, but they have not heard; and I have called unto them, but they have not answered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 35, 18, E'And Jeremiah said unto the house of the Rechabites, Thus saith the LORD of hosts, the God of Israel; Because ye have obeyed the commandment of Jonadab your father, and kept all his precepts, and done according unto all that he hath commanded you:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 35, 19, E'Therefore thus saith the LORD of hosts, the God of Israel; Jonadab the son of Rechab shall not want a man to stand before me for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 1, E'And it came to pass in the fourth year of Jehoiakim the son of Josiah king of Judah, that this word came unto Jeremiah from the LORD, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 2, E'Take thee a roll of a book, and write therein all the words that I have spoken unto thee against Israel, and against Judah, and against all the nations, from the day I spake unto thee, from the days of Josiah, even unto this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 3, E'It may be that the house of Judah will hear all the evil which I purpose to do unto them; that they may return every man from his evil way; that I may forgive their iniquity and their sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 4, E'Then Jeremiah called Baruch the son of Neriah: and Baruch wrote from the mouth of Jeremiah all the words of the LORD, which he had spoken unto him, upon a roll of a book.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Jeremiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 5, E'And Jeremiah commanded Baruch, saying, I am shut up; I cannot go into the house of the LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 6, E'Therefore go thou, and read in the roll, which thou hast written from my mouth, the words of the LORD in the ears of the people in the LORDâ€™s house upon the fasting day: and also thou shalt read them in the ears of all Judah that come out of their cities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 7, E'It may be they will present their supplication before the LORD, and will return every one from his evil way: for great is the anger and the fury that the LORD hath pronounced against this people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 8, E'And Baruch the son of Neriah did according to all that Jeremiah the prophet commanded him, reading in the book the words of the LORD in the LORDâ€™s house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 9, E'And it came to pass in the fifth year of Jehoiakim the son of Josiah king of Judah, in the ninth month, that they proclaimed a fast before the LORD to all the people in Jerusalem, and to all the people that came from the cities of Judah unto Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 10, E'Then read Baruch in the book the words of Jeremiah in the house of the LORD, in the chamber of Gemariah the son of Shaphan the scribe, in the higher court, at the entry of the new gate of the LORDâ€™s house, in the ears of all the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 11, E'When Michaiah the son of Gemariah, the son of Shaphan, had heard out of the book all the words of the LORD,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 12, E'Then he went down into the kingâ€™s house, into the scribeâ€™s chamber: and, lo, all the princes sat there, even Elishama the scribe, and Delaiah the son of Shemaiah, and Elnathan the son of Achbor, and Gemariah the son of Shaphan, and Zedekiah the son of Hananiah, and all the princes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 13, E'Then Michaiah declared unto them all the words that he had heard, when Baruch read the book in the ears of the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 14, E'Therefore all the princes sent Jehudi the son of Nethaniah, the son of Shelemiah, the son of Cushi, unto Baruch, saying, Take in thine hand the roll wherein thou hast read in the ears of the people, and come. So Baruch the son of Neriah took the roll in his hand, and came unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 15, E'And they said unto him, Sit down now, and read it in our ears. So Baruch read it in their ears.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 16, E'Now it came to pass, when they had heard all the words, they were afraid both one and other, and said unto Baruch, We will surely tell the king of all these words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 17, E'And they asked Baruch, saying, Tell us now, How didst thou write all these words at his mouth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 18, E'Then Baruch answered them, He pronounced all these words unto me with his mouth, and I wrote them with ink in the book.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 19, E'Then said the princes unto Baruch, Go, hide thee, thou and Jeremiah; and let no man know where ye be.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 20, E'And they went in to the king into the court, but they laid up the roll in the chamber of Elishama the scribe, and told all the words in the ears of the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 21, E'So the king sent Jehudi to fetch the roll: and he took it out of Elishama the scribeâ€™s chamber. And Jehudi read it in the ears of the king, and in the ears of all the princes which stood beside the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 22, E'Now the king sat in the winterhouse in the ninth month: and there was a fire on the hearth burning before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 23, E'And it came to pass, that when Jehudi had read three or four leaves, he cut it with the penknife, and cast it into the fire that was on the hearth, until all the roll was consumed in the fire that was on the hearth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 24, E'Yet they were not afraid, nor rent their garments, neither the king, nor any of his servants that heard all these words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 25, E'Nevertheless Elnathan and Delaiah and Gemariah had made intercession to the king that he would not burn the roll: but he would not hear them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 26, E'But the king commanded Jerahmeel the son of Hammelech, and Seraiah the son of Azriel, and Shelemiah the son of Abdeel, to take Baruch the scribe and Jeremiah the prophet: but the LORD hid them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 27, E'Then the word of the LORD came to Jeremiah, after that the king had burned the roll, and the words which Baruch wrote at the mouth of Jeremiah, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 28, E'Take thee again another roll, and write in it all the former words that were in the first roll, which Jehoiakim the king of Judah hath burned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 29, E'And thou shalt say to Jehoiakim king of Judah, Thus saith the LORD; Thou hast burned this roll, saying, Why hast thou written therein, saying, The king of Babylon shall certainly come and destroy this land, and shall cause to cease from thence man and beast?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 30, E'Therefore thus saith the LORD of Jehoiakim king of Judah; He shall have none to sit upon the throne of David: and his dead body shall be cast out in the day to the heat, and in the night to the frost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 31, E'And I will punish him and his seed and his servants for their iniquity; and I will bring upon them, and upon the inhabitants of Jerusalem, and upon the men of Judah, all the evil that I have pronounced against them; but they hearkened not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 36, 32, E'Then took Jeremiah another roll, and gave it to Baruch the scribe, the son of Neriah; who wrote therein from the mouth of Jeremiah all the words of the book which Jehoiakim king of Judah had burned in the fire: and there were added besides unto them many like words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 37, 1, E'And king Zedekiah the son of Josiah reigned instead of Coniah the son of Jehoiakim, whom Nebuchadrezzar king of Babylon made king in the land of Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 37, 2, E'But neither he, nor his servants, nor the people of the land, did hearken unto the words of the LORD, which he spake by the prophet Jeremiah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 37, 3, E'And Zedekiah the king sent Jehucal the son of Shelemiah and Zephaniah the son of Maaseiah the priest to the prophet Jeremiah, saying, Pray now unto the LORD our God for us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 37, 4, E'Now Jeremiah came in and went out among the people: for they had not put him into prison.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 37, 5, E'Then Pharaohâ€™s army was come forth out of Egypt: and when the Chaldeans that besieged Jerusalem heard tidings of them, they departed from Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 37, 6, E'Then came the word of the LORD unto the prophet Jeremiah, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 37, 7, E'Thus saith the LORD, the God of Israel; Thus shall ye say to the king of Judah, that sent you unto me to enquire of me; Behold, Pharaohâ€™s army, which is come forth to help you, shall return to Egypt into their own land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 37, 8, E'And the Chaldeans shall come again, and fight against this city, and take it, and burn it with fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 37, 9, E'Thus saith the LORD; Deceive not yourselves, saying, The Chaldeans shall surely depart from us: for they shall not depart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 37, 10, E'For though ye had smitten the whole army of the Chaldeans that fight against you, and there remained but wounded men among them, yet should they rise up every man in his tent, and burn this city with fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 37, 11, E'And it came to pass, that when the army of the Chaldeans was broken up from Jerusalem for fear of Pharaohâ€™s army,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 37, 12, E'Then Jeremiah went forth out of Jerusalem to go into the land of Benjamin, to separate himself thence in the midst of the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 37, 13, E'And when he was in the gate of Benjamin, a captain of the ward was there, whose name was Irijah, the son of Shelemiah, the son of Hananiah; and he took Jeremiah the prophet, saying, Thou fallest away to the Chaldeans.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 37, 14, E'Then said Jeremiah, It is false; I fall not away to the Chaldeans. But he hearkened not to him: so Irijah took Jeremiah, and brought him to the princes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 37, 15, E'Wherefore the princes were wroth with Jeremiah, and smote him, and put him in prison in the house of Jonathan the scribe: for they had made that the prison.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 37, 16, E'When Jeremiah was entered into the dungeon, and into the cabins, and Jeremiah had remained there many days;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 37, 17, E'Then Zedekiah the king sent, and took him out: and the king asked him secretly in his house, and said, Is there any word from the LORD? And Jeremiah said, There is: for, said he, thou shalt be delivered into the hand of the king of Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 37, 18, E'Moreover Jeremiah said unto king Zedekiah, What have I offended against thee, or against thy servants, or against this people, that ye have put me in prison?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 37, 19, E'Where are now your prophets which prophesied unto you, saying, The king of Babylon shall not come against you, nor against this land?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 37, 20, E'Therefore hear now, I pray thee, O my lord the king: let my supplication, I pray thee, be accepted before thee; that thou cause me not to return to the house of Jonathan the scribe, lest I die there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 37, 21, E'Then Zedekiah the king commanded that they should commit Jeremiah into the court of the prison, and that they should give him daily a piece of bread out of the bakersâ€™ street, until all the bread in the city were spent. Thus Jeremiah remained in the court of the prison.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 1, E'Then Shephatiah the son of Mattan, and Gedaliah the son of Pashur, and Jucal the son of Shelemiah, and Pashur the son of Malchiah, heard the words that Jeremiah had spoken unto all the people, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 2, E'Thus saith the LORD, He that remaineth in this city shall die by the sword, by the famine, and by the pestilence: but he that goeth forth to the Chaldeans shall live; for he shall have his life for a prey, and shall live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 3, E'Thus saith the LORD, This city shall surely be given into the hand of the king of Babylonâ€™s army, which shall take it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 4, E'Therefore the princes said unto the king, We beseech thee, let this man be put to death: for thus he weakeneth the hands of the men of war that remain in this city, and the hands of all the people, in speaking such words unto them: for this man seeketh not the welfare of this people, but the hurt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 5, E'Then Zedekiah the king said, Behold, he is in your hand: for the king is not he that can do any thing against you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 6, E'Then took they Jeremiah, and cast him into the dungeon of Malchiah the son of Hammelech, that was in the court of the prison: and they let down Jeremiah with cords. And in the dungeon there was no water, but mire: so Jeremiah sunk in the mire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 7, E'Now when Ebedmelech the Ethiopian, one of the eunuchs which was in the kingâ€™s house, heard that they had put Jeremiah in the dungeon; the king then sitting in the gate of Benjamin;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 8, E'Ebedmelech went forth out of the kingâ€™s house, and spake to the king, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 9, E'My lord the king, these men have done evil in all that they have done to Jeremiah the prophet, whom they have cast into the dungeon; and he is like to die for hunger in the place where he is: for there is no more bread in the city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 10, E'Then the king commanded Ebedmelech the Ethiopian, saying, Take from hence thirty men with thee, and take up Jeremiah the prophet out of the dungeon, before he die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 11, E'So Ebedmelech took the men with him, and went into the house of the king under the treasury, and took thence old cast clouts and old rotten rags, and let them down by cords into the dungeon to Jeremiah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 12, E'And Ebedmelech the Ethiopian said unto Jeremiah, Put now these old cast clouts and rotten rags under thine armholes under the cords. And Jeremiah did so.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 13, E'So they drew up Jeremiah with cords, and took him up out of the dungeon: and Jeremiah remained in the court of the prison.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 14, E'Then Zedekiah the king sent, and took Jeremiah the prophet unto him into the third entry that is in the house of the LORD: and the king said unto Jeremiah, I will ask thee a thing; hide nothing from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 15, E'Then Jeremiah said unto Zedekiah, If I declare it unto thee, wilt thou not surely put me to death? and if I give thee counsel, wilt thou not hearken unto me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 16, E'So Zedekiah the king sware secretly unto Jeremiah, saying, As the LORD liveth, that made us this soul, I will not put thee to death, neither will I give thee into the hand of these men that seek thy life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 17, E'Then said Jeremiah unto Zedekiah, Thus saith the LORD, the God of hosts, the God of Israel; If thou wilt assuredly go forth unto the king of Babylonâ€™s princes, then thy soul shall live, and this city shall not be burned with fire; and thou shalt live, and thine house:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 18, E'But if thou wilt not go forth to the king of Babylonâ€™s princes, then shall this city be given into the hand of the Chaldeans, and they shall burn it with fire, and thou shalt not escape out of their hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 19, E'And Zedekiah the king said unto Jeremiah, I am afraid of the Jews that are fallen to the Chaldeans, lest they deliver me into their hand, and they mock me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 20, E'But Jeremiah said, They shall not deliver thee. Obey, I beseech thee, the voice of the LORD, which I speak unto thee: so it shall be well unto thee, and thy soul shall live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 21, E'But if thou refuse to go forth, this is the word that the LORD hath shewed me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 22, E'And, behold, all the women that are left in the king of Judahâ€™s house shall be brought forth to the king of Babylonâ€™s princes, and those women shall say, Thy friends have set thee on, and have prevailed against thee: thy feet are sunk in the mire, and they are turned away back.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 23, E'So they shall bring out all thy wives and thy children to the Chaldeans: and thou shalt not escape out of their hand, but shalt be taken by the hand of the king of Babylon: and thou shalt cause this city to be burned with fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 24, E'Then said Zedekiah unto Jeremiah, Let no man know of these words, and thou shalt not die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 25, E'But if the princes hear that I have talked with thee, and they come unto thee, and say unto thee, Declare unto us now what thou hast said unto the king, hide it not from us, and we will not put thee to death; also what the king said unto thee:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 26, E'Then thou shalt say unto them, I presented my supplication before the king, that he would not cause me to return to Jonathanâ€™s house, to die there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 27, E'Then came all the princes unto Jeremiah, and asked him: and he told them according to all these words that the king had commanded. So they left off speaking with him; for the matter was not perceived.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 38, 28, E'So Jeremiah abode in the court of the prison until the day that Jerusalem was taken: and he was there when Jerusalem was taken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 39, 1, E'In the ninth year of Zedekiah king of Judah, in the tenth month, came Nebuchadrezzar king of Babylon and all his army against Jerusalem, and they besieged it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 39, 2, E'And in the eleventh year of Zedekiah, in the fourth month, the ninth day of the month, the city was broken up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 39, 3, E'And all the princes of the king of Babylon came in, and sat in the middle gate, even Nergalsharezer, Samgarnebo, Sarsechim, Rabsaris, Nergalsharezer, Rabmag, with all the residue of the princes of the king of Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 39, 4, E'And it came to pass, that when Zedekiah the king of Judah saw them, and all the men of war, then they fled, and went forth out of the city by night, by the way of the kingâ€™s garden, by the gate betwixt the two walls: and he went out the way of the plain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 39, 5, E'But the Chaldeansâ€™ army pursued after them, and overtook Zedekiah in the plains of Jericho: and when they had taken him, they brought him up to Nebuchadnezzar king of Babylon to Riblah in the land of Hamath, where he gave judgment upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 39, 6, E'Then the king of Babylon slew the sons of Zedekiah in Riblah before his eyes: also the king of Babylon slew all the nobles of Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 39, 7, E'Moreover he put out Zedekiahâ€™s eyes, and bound him with chains, to carry him to Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 39, 8, E'And the Chaldeans burned the kingâ€™s house, and the houses of the people, with fire, and brake down the walls of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 39, 9, E'Then Nebuzaradan the captain of the guard carried away captive into Babylon the remnant of the people that remained in the city, and those that fell away, that fell to him, with the rest of the people that remained.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 39, 10, E'But Nebuzaradan the captain of the guard left of the poor of the people, which had nothing, in the land of Judah, and gave them vineyards and fields at the same time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 39, 11, E'Now Nebuchadrezzar king of Babylon gave charge concerning Jeremiah to Nebuzaradan the captain of the guard, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 39, 12, E'Take him, and look well to him, and do him no harm; but do unto him even as he shall say unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 39, 13, E'So Nebuzaradan the captain of the guard sent, and Nebushasban, Rabsaris, and Nergalsharezer, Rabmag, and all the king of Babylonâ€™s princes;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 39, 14, E'Even they sent, and took Jeremiah out of the court of the prison, and committed him unto Gedaliah the son of Ahikam the son of Shaphan, that he should carry him home: so he dwelt among the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 39, 15, E'Now the word of the LORD came unto Jeremiah, while he was shut up in the court of the prison, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 39, 16, E'Go and speak to Ebedmelech the Ethiopian, saying, Thus saith the LORD of hosts, the God of Israel; Behold, I will bring my words upon this city for evil, and not for good; and they shall be accomplished in that day before thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 39, 17, E'But I will deliver thee in that day, saith the LORD: and thou shalt not be given into the hand of the men of whom thou art afraid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 39, 18, E'For I will surely deliver thee, and thou shalt not fall by the sword, but thy life shall be for a prey unto thee: because thou hast put thy trust in me, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 40, 1, E'The word that came to Jeremiah from the LORD, after that Nebuzaradan the captain of the guard had let him go from Ramah, when he had taken him being bound in chains among all that were carried away captive of Jerusalem and Judah, which were carried away captive unto Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 40, 2, E'And the captain of the guard took Jeremiah, and said unto him, The LORD thy God hath pronounced this evil upon this place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 40, 3, E'Now the LORD hath brought it, and done according as he hath said: because ye have sinned against the LORD, and have not obeyed his voice, therefore this thing is come upon you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 40, 4, E'And now, behold, I loose thee this day from the chains which were upon thine hand. If it seem good unto thee to come with me into Babylon, come; and I will look well unto thee: but if it seem ill unto thee to come with me into Babylon, forbear: behold, all the land is before thee: whither it seemeth good and convenient for thee to go, thither go.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 40, 5, E'Now while he was not yet gone back, he said, Go back also to Gedaliah the son of Ahikam the son of Shaphan, whom the king of Babylon hath made governor over the cities of Judah, and dwell with him among the people: or go wheresoever it seemeth convenient unto thee to go. So the captain of the guard gave him victuals and a reward, and let him go.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Jeremiah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 40, 6, E'Then went Jeremiah unto Gedaliah the son of Ahikam to Mizpah; and dwelt with him among the people that were left in the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 40, 7, E'Now when all the captains of the forces which were in the fields, even they and their men, heard that the king of Babylon had made Gedaliah the son of Ahikam governor in the land, and had committed unto him men, and women, and children, and of the poor of the land, of them that were not carried away captive to Babylon;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 40, 8, E'Then they came to Gedaliah to Mizpah, even Ishmael the son of Nethaniah, and Johanan and Jonathan the sons of Kareah, and Seraiah the son of Tanhumeth, and the sons of Ephai the Netophathite, and Jezaniah the son of a Maachathite, they and their men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 40, 9, E'And Gedaliah the son of Ahikam the son of Shaphan sware unto them and to their men, saying, Fear not to serve the Chaldeans: dwell in the land, and serve the king of Babylon, and it shall be well with you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 40, 10, E'As for me, behold, I will dwell at Mizpah, to serve the Chaldeans, which will come unto us: but ye, gather ye wine, and summer fruits, and oil, and put them in your vessels, and dwell in your cities that ye have taken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 40, 11, E'Likewise when all the Jews that were in Moab, and among the Ammonites, and in Edom, and that were in all the countries, heard that the king of Babylon had left a remnant of Judah, and that he had set over them Gedaliah the son of Ahikam the son of Shaphan;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 40, 12, E'Even all the Jews returned out of all places whither they were driven, and came to the land of Judah, to Gedaliah, unto Mizpah, and gathered wine and summer fruits very much.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 40, 13, E'Moreover Johanan the son of Kareah, and all the captains of the forces that were in the fields, came to Gedaliah to Mizpah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 40, 14, E'And said unto him, Dost thou certainly know that Baalis the king of the Ammonites hath sent Ishmael the son of Nethaniah to slay thee? But Gedaliah the son of Ahikam believed them not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 40, 15, E'Then Johanan the son of Kareah spake to Gedaliah in Mizpah secretly, saying, Let me go, I pray thee, and I will slay Ishmael the son of Nethaniah, and no man shall know it: wherefore should he slay thee, that all the Jews which are gathered unto thee should be scattered, and the remnant in Judah perish?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 40, 16, E'But Gedaliah the son of Ahikam said unto Johanan the son of Kareah, Thou shalt not do this thing: for thou speakest falsely of Ishmael.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 41, 1, E'Now it came to pass in the seventh month, that Ishmael the son of Nethaniah the son of Elishama, of the seed royal, and the princes of the king, even ten men with him, came unto Gedaliah the son of Ahikam to Mizpah; and there they did eat bread together in Mizpah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 41, 2, E'Then arose Ishmael the son of Nethaniah, and the ten men that were with him, and smote Gedaliah the son of Ahikam the son of Shaphan with the sword, and slew him, whom the king of Babylon had made governor over the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 41, 3, E'Ishmael also slew all the Jews that were with him, even with Gedaliah, at Mizpah, and the Chaldeans that were found there, and the men of war.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 41, 4, E'And it came to pass the second day after he had slain Gedaliah, and no man knew it,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 41, 5, E'That there came certain from Shechem, from Shiloh, and from Samaria, even fourscore men, having their beards shaven, and their clothes rent, and having cut themselves, with offerings and incense in their hand, to bring them to the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 41, 6, E'And Ishmael the son of Nethaniah went forth from Mizpah to meet them, weeping all along as he went: and it came to pass, as he met them, he said unto them, Come to Gedaliah the son of Ahikam.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 41, 7, E'And it was so, when they came into the midst of the city, that Ishmael the son of Nethaniah slew them, and cast them into the midst of the pit, he, and the men that were with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 41, 8, E'But ten men were found among them that said unto Ishmael, Slay us not: for we have treasures in the field, of wheat, and of barley, and of oil, and of honey. So he forbare, and slew them not among their brethren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 41, 9, E'Now the pit wherein Ishmael had cast all the dead bodies of the men, whom he had slain because of Gedaliah, was it which Asa the king had made for fear of Baasha king of Israel: and Ishmael the son of Nethaniah filled it with them that were slain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 41, 10, E'Then Ishmael carried away captive all the residue of the people that were in Mizpah, even the kingâ€™s daughters, and all the people that remained in Mizpah, whom Nebuzaradan the captain of the guard had committed to Gedaliah the son of Ahikam: and Ishmael the son of Nethaniah carried them away captive, and departed to go over to the Ammonites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 41, 11, E'But when Johanan the son of Kareah, and all the captains of the forces that were with him, heard of all the evil that Ishmael the son of Nethaniah had done,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 41, 12, E'Then they took all the men, and went to fight with Ishmael the son of Nethaniah, and found him by the great waters that are in Gibeon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 41, 13, E'Now it came to pass, that when all the people which were with Ishmael saw Johanan the son of Kareah, and all the captains of the forces that were with him, then they were glad.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 41, 14, E'So all the people that Ishmael had carried away captive from Mizpah cast about and returned, and went unto Johanan the son of Kareah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 41, 15, E'But Ishmael the son of Nethaniah escaped from Johanan with eight men, and went to the Ammonites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 41, 16, E'Then took Johanan the son of Kareah, and all the captains of the forces that were with him, all the remnant of the people whom he had recovered from Ishmael the son of Nethaniah, from Mizpah, after that he had slain Gedaliah the son of Ahikam, even mighty men of war, and the women, and the children, and the eunuchs, whom he had brought again from Gibeon:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 41, 17, E'And they departed, and dwelt in the habitation of Chimham, which is by Bethlehem, to go to enter into Egypt,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 41, 18, E'Because of the Chaldeans: for they were afraid of them, because Ishmael the son of Nethaniah had slain Gedaliah the son of Ahikam, whom the king of Babylon made governor in the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 42, 1, E'Then all the captains of the forces, and Johanan the son of Kareah, and Jezaniah the son of Hoshaiah, and all the people from the least even unto the greatest, came near,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 42, 2, E'And said unto Jeremiah the prophet, Let, we beseech thee, our supplication be accepted before thee, and pray for us unto the LORD thy God, even for all this remnant; (for we are left but a few of many, as thine eyes do behold us:)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 42, 3, E'That the LORD thy God may shew us the way wherein we may walk, and the thing that we may do.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 42, 4, E'Then Jeremiah the prophet said unto them, I have heard you; behold, I will pray unto the LORD your God according to your words; and it shall come to pass, that whatsoever thing the LORD shall answer you, I will declare it unto you; I will keep nothing back from you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 42, 5, E'Then they said to Jeremiah, The LORD be a true and faithful witness between us, if we do not even according to all things for the which the LORD thy God shall send thee to us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 42, 6, E'Whether it be good, or whether it be evil, we will obey the voice of the LORD our God, to whom we send thee; that it may be well with us, when we obey the voice of the LORD our God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 42, 7, E'And it came to pass after ten days, that the word of the LORD came unto Jeremiah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 42, 8, E'Then called he Johanan the son of Kareah, and all the captains of the forces which were with him, and all the people from the least even to the greatest,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 42, 9, E'And said unto them, Thus saith the LORD, the God of Israel, unto whom ye sent me to present your supplication before him;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 42, 10, E'If ye will still abide in this land, then will I build you, and not pull you down, and I will plant you, and not pluck you up: for I repent me of the evil that I have done unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 42, 11, E'Be not afraid of the king of Babylon, of whom ye are afraid; be not afraid of him, saith the LORD: for I am with you to save you, and to deliver you from his hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 42, 12, E'And I will shew mercies unto you, that he may have mercy upon you, and cause you to return to your own land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 42, 13, E'But if ye say, We will not dwell in this land, neither obey the voice of the LORD your God,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 42, 14, E'Saying, No; but we will go into the land of Egypt, where we shall see no war, nor hear the sound of the trumpet, nor have hunger of bread; and there will we dwell:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 42, 15, E'And now therefore hear the word of the LORD, ye remnant of Judah; Thus saith the LORD of hosts, the God of Israel; If ye wholly set your faces to enter into Egypt, and go to sojourn there;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 42, 16, E'Then it shall come to pass, that the sword, which ye feared, shall overtake you there in the land of Egypt, and the famine, whereof ye were afraid, shall follow close after you there in Egypt; and there ye shall die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 42, 17, E'So shall it be with all the men that set their faces to go into Egypt to sojourn there; they shall die by the sword, by the famine, and by the pestilence: and none of them shall remain or escape from the evil that I will bring upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 42, 18, E'For thus saith the LORD of hosts, the God of Israel; As mine anger and my fury hath been poured forth upon the inhabitants of Jerusalem; so shall my fury be poured forth upon you, when ye shall enter into Egypt: and ye shall be an execration, and an astonishment, and a curse, and a reproach; and ye shall see this place no more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 42, 19, E'The LORD hath said concerning you, O ye remnant of Judah; Go ye not into Egypt: know certainly that I have admonished you this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 42, 20, E'For ye dissembled in your hearts, when ye sent me unto the LORD your God, saying, Pray for us unto the LORD our God; and according unto all that the LORD our God shall say, so declare unto us, and we will do it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 42, 21, E'And now I have this day declared it to you; but ye have not obeyed the voice of the LORD your God, nor any thing for the which he hath sent me unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 42, 22, E'Now therefore know certainly that ye shall die by the sword, by the famine, and by the pestilence, in the place whither ye desire to go and to sojourn.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 43, 1, E'And it came to pass, that when Jeremiah had made an end of speaking unto all the people all the words of the LORD their God, for which the LORD their God had sent him to them, even all these words,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 43, 2, E'Then spake Azariah the son of Hoshaiah, and Johanan the son of Kareah, and all the proud men, saying unto Jeremiah, Thou speakest falsely: the LORD our God hath not sent thee to say, Go not into Egypt to sojourn there:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 43, 3, E'But Baruch the son of Neriah setteth thee on against us, for to deliver us into the hand of the Chaldeans, that they might put us to death, and carry us away captives into Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 43, 4, E'So Johanan the son of Kareah, and all the captains of the forces, and all the people, obeyed not the voice of the LORD, to dwell in the land of Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 43, 5, E'But Johanan the son of Kareah, and all the captains of the forces, took all the remnant of Judah, that were returned from all nations, whither they had been driven, to dwell in the land of Judah;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 43, 6, E'Even men, and women, and children, and the kingâ€™s daughters, and every person that Nebuzaradan the captain of the guard had left with Gedaliah the son of Ahikam the son of Shaphan, and Jeremiah the prophet, and Baruch the son of Neriah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 43, 7, E'So they came into the land of Egypt: for they obeyed not the voice of the LORD: thus came they even to Tahpanhes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 43, 8, E'Then came the word of the LORD unto Jeremiah in Tahpanhes, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 43, 9, E'Take great stones in thine hand, and hide them in the clay in the brickkiln, which is at the entry of Pharaohâ€™s house in Tahpanhes, in the sight of the men of Judah;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 43, 10, E'And say unto them, Thus saith the LORD of hosts, the God of Israel; Behold, I will send and take Nebuchadrezzar the king of Babylon, my servant, and will set his throne upon these stones that I have hid; and he shall spread his royal pavilion over them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 43, 11, E'And when he cometh, he shall smite the land of Egypt, and deliver such as are for death to death; and such as are for captivity to captivity; and such as are for the sword to the sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 43, 12, E'And I will kindle a fire in the houses of the gods of Egypt; and he shall burn them, and carry them away captives: and he shall array himself with the land of Egypt, as a shepherd putteth on his garment; and he shall go forth from thence in peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 43, 13, E'He shall break also the images of Bethshemesh, that is in the land of Egypt; and the houses of the gods of the Egyptians shall he burn with fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 1, E'The word that came to Jeremiah concerning all the Jews which dwell in the land of Egypt, which dwell at Migdol, and at Tahpanhes, and at Noph, and in the country of Pathros, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 2, E'Thus saith the LORD of hosts, the God of Israel; Ye have seen all the evil that I have brought upon Jerusalem, and upon all the cities of Judah; and, behold, this day they are a desolation, and no man dwelleth therein,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 3, E'Because of their wickedness which they have committed to provoke me to anger, in that they went to burn incense, and to serve other gods, whom they knew not, neither they, ye, nor your fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 4, E'Howbeit I sent unto you all my servants the prophets, rising early and sending them, saying, Oh, do not this abominable thing that I hate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 5, E'But they hearkened not, nor inclined their ear to turn from their wickedness, to burn no incense unto other gods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 6, E'Wherefore my fury and mine anger was poured forth, and was kindled in the cities of Judah and in the streets of Jerusalem; and they are wasted and desolate, as at this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 7, E'Therefore now thus saith the LORD, the God of hosts, the God of Israel; Wherefore commit ye this great evil against your souls, to cut off from you man and woman, child and suckling, out of Judah, to leave you none to remain;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 8, E'In that ye provoke me unto wrath with the works of your hands, burning incense unto other gods in the land of Egypt, whither ye be gone to dwell, that ye might cut yourselves off, and that ye might be a curse and a reproach among all the nations of the earth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 9, E'Have ye forgotten the wickedness of your fathers, and the wickedness of the kings of Judah, and the wickedness of their wives, and your own wickedness, and the wickedness of your wives, which they have committed in the land of Judah, and in the streets of Jerusalem?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 10, E'They are not humbled even unto this day, neither have they feared, nor walked in my law, nor in my statutes, that I set before you and before your fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 11, E'Therefore thus saith the LORD of hosts, the God of Israel; Behold, I will set my face against you for evil, and to cut off all Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 12, E'And I will take the remnant of Judah, that have set their faces to go into the land of Egypt to sojourn there, and they shall all be consumed, and fall in the land of Egypt; they shall even be consumed by the sword and by the famine: they shall die, from the least even unto the greatest, by the sword and by the famine: and they shall be an execration, and an astonishment, and a curse, and a reproach.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 13, E'For I will punish them that dwell in the land of Egypt, as I have punished Jerusalem, by the sword, by the famine, and by the pestilence:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 14, E'So that none of the remnant of Judah, which are gone into the land of Egypt to sojourn there, shall escape or remain, that they should return into the land of Judah, to the which they have a desire to return to dwell there: for none shall return but such as shall escape.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 15, E'Then all the men which knew that their wives had burned incense unto other gods, and all the women that stood by, a great multitude, even all the people that dwelt in the land of Egypt, in Pathros, answered Jeremiah, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 16, E'As for the word that thou hast spoken unto us in the name of the LORD, we will not hearken unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 17, E'But we will certainly do whatsoever thing goeth forth out of our own mouth, to burn incense unto the queen of heaven, and to pour out drink offerings unto her, as we have done, we, and our fathers, our kings, and our princes, in the cities of Judah, and in the streets of Jerusalem: for then had we plenty of victuals, and were well, and saw no evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 18, E'But since we left off to burn incense to the queen of heaven, and to pour out drink offerings unto her, we have wanted all things, and have been consumed by the sword and by the famine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 19, E'And when we burned incense to the queen of heaven, and poured out drink offerings unto her, did we make her cakes to worship her, and pour out drink offerings unto her, without our men?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 20, E'Then Jeremiah said unto all the people, to the men, and to the women, and to all the people which had given him that answer, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 21, E'The incense that ye burned in the cities of Judah, and in the streets of Jerusalem, ye, and your fathers, your kings, and your princes, and the people of the land, did not the LORD remember them, and came it not into his mind?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 22, E'So that the LORD could no longer bear, because of the evil of your doings, and because of the abominations which ye have committed; therefore is your land a desolation, and an astonishment, and a curse, without an inhabitant, as at this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 23, E'Because ye have burned incense, and because ye have sinned against the LORD, and have not obeyed the voice of the LORD, nor walked in his law, nor in his statutes, nor in his testimonies; therefore this evil is happened unto you, as at this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 24, E'Moreover Jeremiah said unto all the people, and to all the women, Hear the word of the LORD, all Judah that are in the land of Egypt:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 25, E'Thus saith the LORD of hosts, the God of Israel, saying; Ye and your wives have both spoken with your mouths, and fulfilled with your hand, saying, We will surely perform our vows that we have vowed, to burn incense to the queen of heaven, and to pour out drink offerings unto her: ye will surely accomplish your vows, and surely perform your vows.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 26, E'Therefore hear ye the word of the LORD, all Judah that dwell in the land of Egypt; Behold, I have sworn by my great name, saith the LORD, that my name shall no more be named in the mouth of any man of Judah in all the land of Egypt, saying, The Lord GOD liveth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 27, E'Behold, I will watch over them for evil, and not for good: and all the men of Judah that are in the land of Egypt shall be consumed by the sword and by the famine, until there be an end of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 28, E'Yet a small number that escape the sword shall return out of the land of Egypt into the land of Judah, and all the remnant of Judah, that are gone into the land of Egypt to sojourn there, shall know whose words shall stand, mine, or theirs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 29, E'And this shall be a sign unto you, saith the LORD, that I will punish you in this place, that ye may know that my words shall surely stand against you for evil:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 44, 30, E'Thus saith the LORD; Behold, I will give Pharaohhophra king of Egypt into the hand of his enemies, and into the hand of them that seek his life; as I gave Zedekiah king of Judah into the hand of Nebuchadrezzar king of Babylon, his enemy, and that sought his life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 45, 1, E'The word that Jeremiah the prophet spake unto Baruch the son of Neriah, when he had written these words in a book at the mouth of Jeremiah, in the fourth year of Jehoiakim the son of Josiah king of Judah, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 45, 2, E'Thus saith the LORD, the God of Israel, unto thee, O Baruch:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 45, 3, E'Thou didst say, Woe is me now! for the LORD hath added grief to my sorrow; I fainted in my sighing, and I find no rest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 45, 4, E'Thus shalt thou say unto him, The LORD saith thus; Behold, that which I have built will I break down, and that which I have planted I will pluck up, even this whole land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 45, 5, E'And seekest thou great things for thyself? seek them not: for, behold, I will bring evil upon all flesh, saith the LORD: but thy life will I give unto thee for a prey in all places whither thou goest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'c77ff5f7-fa3c-40f6-9a2a-a2663b7ee768', 46, 1, E'The word of the LORD which came to Jeremiah the prophet against the Gentiles;')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Jeremiah') b
ON CONFLICT DO NOTHING;

